  if(e.ch&&G.player&&!G.c[G.player].ai&&e.ch.who().includes(G.player)){if(G.card)continue;const k=e.ch.build(G.player);if(k&&cardOpen({kind:"ev",id:e.id,title:k.title,txt:k.txt,history:k.history,opts:k.opts.map(o=>({k:o.k,label:o.label,txt:o.txt})),def:k.def||k.opts[0].k})){G.ev[e.id]=G.t;continue;}}
