ev("famine").ch={who:()=>["GBR"],build:()=>({title:"Potato blight in Ireland, 1845",txt:"The potato crop has failed across Ireland. Landlords are evicting tenants who cannot pay, and grain is leaving the ports.",def:"market",opts:[{k:"market",label:"Leave it to the market",txt:"The famine lasts about five years. Hundreds of thousands die or leave. No cost to the treasury.",run(){ev("famine").run();}},{k:"relief",label:"Open the ports and fund relief",txt:"It costs six months of income, but the famine lasts about two years and many fewer die.",run(){const c=G.c.GBR;pay(c,incOf(c)*6);G.famine={p:"IRE",until:G.t+24};msg("politics","Potato blight: famine in Ireland. Relief works and open ports ease it.");}}]})};
ev("y1848").ch={who:()=>Object.keys(G.c).filter(t=>{const c=G.c[t];return c.alive&&c.civ&&c.gov==="abs"&&P(c.cap).x>1250&&P(c.cap).x<1700&&P(c.cap).y<520;}),build:pt=>({title:"1848: revolution in the capitals",txt:"Crowds fill the streets of the cities of Europe. Students, workers and liberals demand a constitution.",def:"ride",opts:[{k:"ride",label:"Ride it out",txt:"The unrest spreads: workers and the middle class become more militant for a while.",run(){ev("y1848").run();}},{k:"const",label:"Grant a constitution",txt:"We become a constitutional monarchy; unrest fades, but the old nobles are angry and we lose 3 prestige.",run(){const c=G.c[pt];c.gov="const";c.pres=Math.max(0,c.pres-3);for(const p of provsOf(pt))for(const q of p.pops)q.mil=Math.max(0,q.mil-1);msg("politics","1848: "+c.n+" grants a constitution.");}},{k:"crush",label:"Send in the troops",txt:"The revolt is crushed, but militancy rises sharply in the cities and we gain 3 prestige with the other crowns.",run(){const c=G.c[pt];ev("y1848").run();for(const p of provsOf(pt))for(const q of p.pops)if(PTYPES[q.t].s>0||q.t==="CRA")q.mil=Math.min(10,q.mil+1);c.pres+=3;}}]})};
ev("taiping").ch={who:()=>["CHI"],build:()=>({title:"The Taiping rising, 1850",txt:"A prophet who says he is Christ's younger brother has raised a huge army in the south, and the land is hungry.",def:"fight",opts:[{k:"fight",label:"Raise the banner armies",txt:"A very large rebel army takes the south. We must beat it in the field.",run(){ev("taiping").run();}},{k:"relief",label:"Cut taxes and feed the south",txt:"It costs six months of income, but the rebellion is half the size.",run(){const c=G.c.CHI;pay(c,incOf(c)*6);rebelsIn("NAN","CHI",15,3);rebelsIn("WUH","CHI",8,1);msg("war","The Taiping Heavenly Kingdom rises in the south of China; tax relief weakens it.");}},{k:"west",label:"Hire Western drill",txt:"We pay four months of income for 8 trained regiments, but the Great Powers gain a foothold: the rebellion stays large.",run(){const c=G.c.CHI;pay(c,incOf(c)*4);G.armies.push(mkArmy("CHI","NAN",{inf:8}));ev("taiping").run();}}]})};
ev("italy1").ch={who:()=>["SAR","AUS"],build:pt=>pt==="SAR"?{title:"Italy and Austria, 1859",txt:"Cavour has French promises at Plombieres. War against Austria would free Lombardy.",def:"france",opts:[{k:"france",label:"Go to war with French help",txt:"War with Austria; France joins us in most cases. Russia and Prussia stay out.",run(){ev("italy1").run();}},{k:"alone",label:"Strike alone",txt:"War with Austria without France; Russia and Prussia stay out. We gain 3 prestige for boldness if we survive.",run(){G.c.SAR.pres+=3;const w=declareWar("SAR","AUS",{k:"conquer",tag:"AUS",prov:"LOM",hist:1});if(w){w.unify="ITA";stayOut(w,["RUS","PRU"]);}}},{k:"wait",label:"Wait two more years",txt:"No war now. Relations with Austria improve slightly.",run(){evAt("italy1",24);G.c.SAR.rel.AUS=(G.c.SAR.rel.AUS||0)+10;}}]}:{title:"Piedmont threatens Lombardy, 1859",txt:"Sardinia, backed by France, will attack us unless we give way.",def:"fight",opts:[{k:"fight",label:"Fight for Lombardy",txt:"War with Sardinia-Piedmont, and probably France.",run(){ev("italy1").run();}},{k:"cede",label:"Cede Lombardy",txt:"No war. Lombardy goes to Sardinia; we lose 5 prestige.",run(){transferProv(P("LOM"),"SAR");G.unif=G.unif||{};G.unif.ITA="SAR";G.c.AUS.pres=Math.max(0,G.c.AUS.pres-5);G.c.SAR.pres+=5;}}]}};
ev("germany1").ch={who:()=>["PRU","DEN"],build:pt=>pt==="PRU"?{title:"Schleswig and Holstein, 1864",txt:"The King of Denmark has tied Schleswig to his crown. Prussia and Austria can take it.",def:"both",opts:[{k:"both",label:"Take it with Austria",txt:"War with Denmark, Austria beside us.",run(){ev("germany1").run();}},{k:"alone",label:"Take it alone",txt:"War with Denmark with no Austrian help; the gains are ours alone.",run(){declareWar("PRU","DEN",{k:"conquer",tag:"DEN",prov:"SLH",hist:1});}},{k:"drop",label:"Let it be",txt:"No war. Relations with Denmark improve; German nationalists are angry (we lose 3 prestige).",run(){G.c.PRU.pres=Math.max(0,G.c.PRU.pres-3);G.c.PRU.rel.DEN=(G.c.PRU.rel.DEN||0)+20;}}]}:{title:"Prussia and Austria march on Schleswig, 1864",txt:"Our crown is tied to Schleswig and the German states want it.",def:"fight",opts:[{k:"fight",label:"Fight on",txt:"War with Prussia, probably Austria too.",run(){ev("germany1").run();}},{k:"cede",label:"Give up Schleswig",txt:"No war. We lose Schleswig and 5 prestige.",run(){transferProv(P("SLH"),"PRU");G.c.DEN.pres=Math.max(0,G.c.DEN.pres-5);}},{k:"help",label:"Ask Britain to stand with us",txt:"War, but Britain joins us half the time.",run(){const w=ev("germany1").run();const g=G.wars[G.wars.length-1];if(g&&g.def.includes("DEN")&&alive("GBR")&&rng()<.5)pullIn(g,"GBR",2);}}]}};
ev("germany2").ch={who:()=>["PRU","AUS"],build:pt=>pt==="PRU"?{title:"Who leads Germany? 1866",txt:"Bismarck says the question of German leadership can only be settled by war with Austria.",def:"war",opts:[{k:"war",label:"War with Austria",txt:"A short, hard war for leadership of Germany. Some German states fight for Austria, and Italy joins us if it is free to. Russia, France and Britain stay out. Prussia mobilises first by rail and starts with 15 war score.",run(){ev("germany2").run();}},{k:"wait",label:"Settle quietly",txt:"No war for three years. Austria stays our ally, but German unification waits.",run(){evAt("germany2",36);}}]}:{title:"Prussia wants the leadership of Germany, 1866",txt:"Bismarck is stirring up the German question and has Italy as a friend.",def:"war",opts:[{k:"war",label:"Fight for our place in Germany",txt:"War with Prussia and Italy; Saxony, Hanover and Bavaria are each about even odds to stand with us. Russia, France and Britain stay out. Prussia mobilises first by rail and starts with 15 war score.",run(){ev("germany2").run();}},{k:"yield",label:"Accept Prussian leadership",txt:"No war. The German states go into Prussia's sphere; we lose 10 prestige and Prussia gains 6.",run(){const c=G.c.AUS;c.pres=Math.max(0,c.pres-10);G.c.PRU.pres+=6;G.unif=G.unif||{};G.unif.GER="PRU";for(const t of["HAN","SAX","BAV","WUR"])toSphere(t,"PRU");G.c.PRU.ally=G.c.PRU.ally.filter(t=>t!=="AUS");G.c.AUS.ally=G.c.AUS.ally.filter(t=>t!=="PRU");G.c.AUS.truce.PRU=G.t+60;G.c.PRU.truce.AUS=G.t+60;}}]}};
