const COMPANY_DISTRICTS=["DEL","CAL","BOM"];
const COMPANY_TRANSFER=(1858-1836)*12+10;
function indiaAdministrator(province){
 if(province?.o!=="GBR"||!COMPANY_DISTRICTS.includes(province.id))return null;
 if(province.ctl!=="GBR")return "Occupied";
 return G.t<COMPANY_TRANSFER?"East India Company":"Crown administration";
}
function companyBudget(country){
 const districts=COMPANY_DISTRICTS.map(P).filter(p=>indiaAdministrator(p)==="East India Company");
 const taxes=sum(districts,p=>sum(p.pops,q=>q._tax||0));
 const retained=taxes*.12;
 const officials=districts.flatMap(p=>p.pops.filter(q=>q.t==="BUR"));
 const population=sum(officials,q=>q.n);
 const reserve=(country.companyBudget?.reserve||0)+retained;
 const spent=population?Math.min(reserve,retained*.75):0;
 if(population)for(const q of officials)q.cash+=spent*q.n/population;
 const transfer=G.t>=COMPANY_TRANSFER?reserve:0;
 country.companyBudget={month:G.t,taxes,retained,spent,remitted:taxes-retained,
  reserve:reserve-spent-transfer,transferred:transfer};
 return retained-transfer;
}

function companyLahoreDo(){const c=G.c.GBR;if(!c||!c.alive||!alive("PUN"))return;
 rememberRegional("companyLahore","offer");
 if(!(c.commercialRoute?.until>G.t))c.commercialRoute={seller:"PUN",good:"grain",until:G.t+24,rights:["trade"]};
 msg("diplomacy","Punjab accepts the Company's commercial proposal.");
}
hd("companyLahore",1846,3,"GBR","The Company and Lahore",
 "Company officials ask London for instructions on commercial negotiations with Punjab.",
 "This is an alternate-history decision. It uses the Lahore settlement already modelled in the Punjab campaign.",
 [["Authorise a commercial offer","Request access to Punjab grain without acquiring Punjab's territory or tax powers.",c=>{
  const punjab=G.c.PUN;
  if((punjab.rel.GBR||0)<0||atWarWith(c,punjab)){
   msg("diplomacy","Punjab refuses the Company's commercial proposal.");
   return;
  }
  /* A3: a human Punjab is asked; the AI accepts */
  if(askHuman("PUN",{a:"companyLahore"},"The Company's commercial proposal","The Company asks for access to Punjab grain, without territory or tax powers.",["Accept the offer","Punjab sells grain to the Company under a two-year commercial route."],["Refuse the offer","Nothing changes."]))return;
  companyLahoreDo();
 }],["Keep existing terms","Leave territory, taxation and commercial rights as they stand.",()=>{
  rememberRegional("companyLahore","hold");
 }]],()=>alive("PUN")&&owns("PUN","LAH")&&COMPANY_DISTRICTS.some(id=>indiaAdministrator(P(id))==="East India Company"));

;

/* === src/greatwar.js === */
"use strict";

function julyTies(c, side, enemy){
 if(!c.alive||side.includes(c.tag)||enemy.includes(c.tag)||c.war.length)return 0;
 if(enemy.some(t=>(c.truce[t]||0)>G.t)||side.some(t=>atWarWith(c,G.c[t])))return 0;
 let tie=0;
 for(const t of side){
  const a=G.c[t];
  if(!a?.alive)continue;
  if(c.ally.includes(t)||a.ally.includes(c.tag))tie=Math.max(tie,4);
  if((c.guar||[]).includes(t))tie=Math.max(tie,5);
  if(c.sphere===t||a.sphere===c.tag||c.overlord===t)tie=Math.max(tie,3);
 }
 if(tie&&enemy.some(t=>(c.rel[t]||0)<-35))tie++;
 return tie;
}

function julyAlignment(c,w){
 const a=julyTies(c,w.att,w.def),d=julyTies(c,w.def,w.att);
 return a===d?null:{side:a>d?1:2,weight:Math.max(a,d)};
}

function julyJoin(w,c,side){
 const current=julyAlignment(c,w);
 if(!current||current.side!==side||w.july.answers[c.tag])return false;
 joinWar(w,c.tag,side);
 w.july.answers[c.tag]="joined";
 w.july.wear[c.tag]=0;
 msg("war",c.n+" enters the July Crisis war alongside "+G.c[(side===1?w.att:w.def)[0]].n+".");
 return true;
}

function startJulyWar(c){
 const w=declareWar(c.tag,"SER",{k:"humble",tag:"SER",hist:1,managed:true});
 if(!w){msg("diplomacy","The ultimatum expires without a declaration of war.");return;}
 w.july={wear:{[c.tag]:0,SER:0},answers:{},general:false};
 msg("diplomacy","The July Crisis becomes a regional war. Treaty partners must decide whether to intervene.");
}

ev("july1914").run=()=>{
 const c=G.c.AUS,ser=G.c.SER;
 const involved=Object.values(G.c).filter(n=>isGP(n.tag));
 const rivalBlocs=involved.some(n=>julyTies(n,[c.tag],["SER"])>=4)&&involved.some(n=>julyTies(n,["SER"],[c.tag])>=4);
 if((c.rel.SER||0)<-25&&rivalBlocs)startJulyWar(c);
 else {
  hr("SER",20)(c);hr("RUS",20)(c);
  msg("diplomacy",c.n+" seeks mediation with "+ser.n+".");
 }
};

function julySeparate(w,c){
 const own=w.att.includes(c.tag)?w.att:w.def,foes=own===w.att?w.def:w.att;
 const i=own.indexOf(c.tag);
 if(i<1)return false;
 own.splice(i,1);
 c.war=c.war.filter(id=>id!==w.id);
 for(const t of foes){
  c.truce[t]=Math.max(c.truce[t]||0,G.t+48);
  G.c[t].truce[c.tag]=Math.max(G.c[t].truce[c.tag]||0,G.t+48);
 }
 for(const p of G.plist)if(p.ctl!==p.o&&((p.o===c.tag&&foes.includes(p.ctl))||(p.ctl===c.tag&&foes.includes(p.o)))&&!atWarWith(G.c[p.o],G.c[p.ctl]))p.ctl=p.o;
 w.july.answers[c.tag]="withdrawn";
 c.pres=Math.max(0,c.pres-5);
 msg("diplomacy",c.n+" signs a separate peace and leaves the war.");
 return true;
}

const JULY_EXIT_WEAR=65;
function julyArmistice(w,c){
 const sides=w.att.includes(c.tag)?[w.att,w.def]:[w.def,w.att],j=w.july;
 if(sides[0][0]!==c.tag)return false;
 const signedScore=sides[0]===w.att?w.ws:-w.ws;
 const enemyWear=j.wear[sides[1][0]]||0;
 if(enemyWear<45&&Math.abs(signedScore)>15&&signedScore<35)return false;
 endWar(w,signedScore>=35?(sides[0]===w.att?"att":"def"):"white");
 return true;
}

function julyCard(w,c,kind,side){
 if(kind==="entry"){
  const leader=G.c[(side===1?w.att:w.def)[0]].n;
  return cardOpen({kind:"july",id:"july-entry",ctx:{war:w.id,side},title:"The call to intervene",txt:leader+" is asking for support. Your current treaties make intervention possible.",
   history:"In 1914 several powers entered the war following a series of separate decisions. Some remained neutral.",
   def:"neutral",opts:[{k:"join",label:"Join "+leader,txt:"Enter the war on that side."},{k:"neutral",label:"Remain neutral",txt:"Decline entry in this escalation."}]});
 }
 const lead=w.att[0]===c.tag||w.def[0]===c.tag;
 return cardOpen({kind:"july",id:"july-exit",ctx:{war:w.id},title:"A government under strain",txt:"War exhaustion has reached "+Math.round(w.july.wear[c.tag])+" out of 100. Unless you choose otherwise, your government does what any other would at this point.",
  def:lead?"armistice":"exit",opts:[{k:lead?"armistice":"exit",label:lead?"Propose an armistice":"Sign a separate peace",txt:lead?"If your opponent agrees, end the war. The war score and enemy exhaustion affect acceptance.":"Return occupied provinces, leave the war, sign a four-year truce and lose 5 prestige."},{k:"continue",label:"Continue the war",txt:"Keep fighting. A new peace review can follow in twelve months."}]});
}

function chooseJulyCard(card,key){
 const c=G.c[G.player];
 if(!c?.alive)return;
 if(card.id==="july-conference"){
  const p=(G.peaceConferences||[]).find(x=>x.war===card.ctx.war);
  if(p&&!p.resolved)resolveConference(p,key);
  return;
 }
 const w=G.wars.find(x=>x.id===card.ctx.war);
 if(!w?.july)return;
 const j=w.july;
 if(key==="join")julyJoin(w,c,card.ctx.side);
 if(key==="neutral")j.answers[c.tag]="neutral";
 if(key==="continue")(j.review||={})[c.tag]=G.t+12;
 if(key==="exit")julySeparate(w,c);
 if(key==="armistice"&&!julyArmistice(w,c))msg("diplomacy","The opposing government declines the armistice.");
}

function julyWear(w,c){
 const land=provsOf(c.tag),inc=Math.max(1,c.stat.inc||1);
 const occupied=land.filter(p=>p.ctl&&p.ctl!==c.tag).length/Math.max(1,land.length);
 const deficit=clamp(-(c.stat.net||0)/inc,0,1);
 const warSpending=clamp((c.stat.gov||0)/inc,0,1);
 const j=w.july,previous=j.wear[c.tag]||0;
 j.wear[c.tag]=clamp(previous+.45+1.4*occupied+.55*deficit+.25*warSpending,0,100);
 c.we=clamp((c.we||0)+Math.max(0,j.wear[c.tag]-previous),0,100);
 return j.wear[c.tag];
}

function resolveConference(p,key){
 const win=G.c[p.chair],lose=G.c[p.other];
 if(p.resolved||!win?.alive||!lose?.alive)return;
 p.resolved=key;
 if(key==="rebuild"){
  const amount=Math.min(Math.max(0,win.tr),incOf(win)*.5);
  if(amount<=0||((lose.rel[win.tag]||0)<-75)){
   p.resolved="rebuild-refused";
   msg("diplomacy","The reconstruction proposal was refused. Existing peace terms stand.");
   return;
  }
  win.tr-=amount;
  lose.tr+=amount;
  hr(lose.tag,25)(win);
  win.truce[lose.tag]=Math.max(win.truce[lose.tag]||0,G.t+72);
  lose.truce[win.tag]=Math.max(lose.truce[win.tag]||0,G.t+72);
  msg("diplomacy","The conference agrees on "+money(amount)+" in reconstruction aid and a six-year truce.");
  return;
 }
 if(key==="reparations"&&p.victory){
  (lose.owes||=[]).push({to:win.tag,share:.04,until:G.t+36});
  hr(lose.tag,-15)(win);
 }else{
  hr(lose.tag,20)(win);
  win.truce[lose.tag]=Math.max(win.truce[lose.tag]||0,G.t+72);
  lose.truce[win.tag]=Math.max(lose.truce[win.tag]||0,G.t+72);
 }
 msg("diplomacy","The peace conference adopts "+(key==="reparations"&&p.victory?"three years of reparations.":"a reconciliation agreement."));
}

function julyConferences(){
 for(const p of G.peaceConferences||[]){
  if(p.resolved||G.t<=p.t)continue;
  if(!alive(p.chair)||!alive(p.other)){p.resolved="lapsed";continue;}
  if(p.chair===G.player&&!G.c[p.chair].ai){
   if(G.card)continue;
   const opts=[{k:"reconcile",label:"Seek reconciliation",txt:"Improve relations by 20 and extend the minimum truce to six years."}];
   if(G.c[p.chair].tr>0)opts.push({k:"rebuild",label:"Offer reconstruction aid",txt:"Offer up to half a month’s revenue. If accepted, relations improve by 25 and the truce lasts at least six years."});
   if(p.victory)opts.push({k:"reparations",label:"Demand reparations",txt:"Receive up to 4% of the other government's monthly income for three years. Relations worsen by 15."});
   cardOpen({kind:"july",id:"july-conference",ctx:{war:p.war},title:"The peace conference",txt:"The fighting is over. You now set the supplementary terms with "+G.c[p.other].n+".",def:"reconcile",opts});
  }else resolveConference(p,p.victory&&Math.abs(p.score)>=50?"reparations":"reconcile");
 }
}

function julyMonth(){
 for(const w of G.wars.slice()){
  if(!w.july)continue;
  const j=w.july,age=G.t-w.start;
  if(age>0&&age<=18){
   for(const c of Object.values(G.c)){
    if(j.answers[c.tag])continue;
    const choice=julyAlignment(c,w);
    if(!choice)continue;
    if(c.tag===G.player&&!c.ai){if(!G.card)julyCard(w,c,"entry",choice.side);}
    else if(choice.weight>=4)julyJoin(w,c,choice.side);
   }
  }
  const participants=w.att.concat(w.def);
  if(!j.general&&participants.filter(isGP).length>=3&&w.att.some(isGP)&&w.def.some(isGP)){
   j.general=true;
   msg("war","The regional conflict has escalated into a Great War.");
  }
  for(const tag of participants){
   const c=G.c[tag],wear=julyWear(w,c),lead=w.att[0]===tag||w.def[0]===tag;
   /* A4: one threshold for every seat. The AI acts at JULY_EXIT_WEAR; a human gets the same decision at the same point, as a card whose
      default option is the AI's policy (an armistice for a war leader, a separate peace for anyone else), with the same consequences.
      A voluntary earlier peace remains available through the diplomacy screens. */
   if(wear<JULY_EXIT_WEAR||G.t<(j.review?.[tag]||0))continue;
   if(tag===G.player&&!c.ai){
    if(!G.card)julyCard(w,c,"exit");
   }else if(lead){if(julyArmistice(w,c))break;}
   else julySeparate(w,c);
  }
 }
 julyConferences();
}

{
 const nextEvents=eventsMonth;
 eventsMonth=function(){nextEvents();julyMonth();};
 const finish=endWar;
 endWar=function(w,winner){
  if(w.july?.general){
   const chair=(winner==="def"?w.def:w.att)[0],other=(winner==="def"?w.att:w.def)[0];
   (G.peaceConferences||=[]).push({war:w.id,t:G.t,chair,other,victory:winner==="att"||winner==="def",score:w.ws});
  }
  return finish(w,winner);
 };
}

;

/* === src/build.js === */
"use strict";
/* ================= PROVINCE BUILDINGS ================= */
const BLD={
 fort:{n:"Fortress",max:5,cost:{cement:400,steel:60,timber:400},d:"Defenders fight better; sieges take longer.",lv:p=>p.fort,up:p=>{p.fort++;}},
 port:{n:"Naval base",max:3,cost:{timber:900,cement:200,machinery:30},d:"Repairs and supplies fleets; level 2 can build ironclads and later ships.",lv:p=>p.port||0,ok:p=>p.sea,up:p=>{p.port=(p.port||0)+1;}},
 uni:{n:"University",max:2,cost:{cement:200,paper:250,furniture:150},d:"Research +4 points a month per level; literacy rises faster here.",lv:p=>p.uni||0,up:p=>{p.uni=(p.uni||0)+1;}},
 hosp:{n:"Hospital",max:2,cost:{cement:150,clothes:150,furniture:100},d:"The population here grows faster and is less angry.",lv:p=>p.hosp||0,up:p=>{p.hosp=(p.hosp||0)+1;}},
 irr:{n:"Irrigation",max:3,cost:{timber:600,cement:250,machinery:20},d:"Farm output +12% per level.",lv:p=>p.irr||0,ok:p=>!!p.farm,up:p=>{p.irr=(p.irr||0)+1;}},
 minew:{n:"Mine works",max:3,cost:{timber:500,steel:80,machinery:40},d:"Mine output +15% per level.",lv:p=>p.minew||0,ok:p=>!!p.mine,up:p=>{p.minew=(p.minew||0)+1;}}};
/* ---- B1: more province buildings. Levels of the new ones live in p.bx (missing = level 0); each effect is read by a system that already exists (hook named in each line) ---- */
const bxl=(p,k)=>(p.bx&&p.bx[k])||0,bxUp=(p,k)=>{(p.bx=p.bx||{})[k]=bxl(p,k)+1;};
const popAvg=(p,f)=>{let a=0,n=0;for(const q of p.pops){a+=q[f]*q.n;n+=q.n;}return n>0?a/n:0;};
const hostBorder=(c,p)=>ADJ[p.id].some(id=>{const o=P(id).o;return o&&o!==c.tag&&((c.rel[o]||0)<-30||atWarWith(c,G.c[o]));});
const needT=(c,id)=>c.tech[id]?"":"Needs "+tNm(TF[id].n)+".";
function mkB(k,o){const B=BLD[k]=Object.assign({max:2,m:10,grp:"eco",sc:1,lv:p=>bxl(p,k),up:p=>bxUp(p,k)},o);let v=0;for(const g in B.cost)v+=B.cost[g]*GOODS[g].p;B.upk=Math.round(v*.008);return B;}
mkB("depot",{n:"Railway depot",max:3,grp:"mil",m:8,cost:{timber:500,cement:200,steel:80},tech:"rail1",chk:(c,p)=>p.rail<1?"Needs a railway here first.":"",d:"Supply limit +2 and marching speed +6% in this province, for each level (stacks with the railway). Read by supply limits and army movement."});
mkB("barracks",{n:"Barracks",max:3,grp:"mil",m:8,cost:{timber:450,cement:150,clothes:80},d:"Mobilization draws 25% more brigades from this province per level. Read by the mobilization plan."});
mkB("arsenal",{n:"Arsenal",max:2,grp:"mil",m:12,cost:{timber:400,cement:350,steel:150,machinery:60},tech:"percussion",d:"Brigades and ships raised here cost 10% less per level and are finished 20% faster. Read by recruitment."});
mkB("dock",{n:"Dry dock",max:2,grp:"mil",m:14,cost:{timber:700,cement:500,steel:200,machinery:60},tech:"ironclad",chk:(c,p)=>!p.sea?"Needs a coast.":(p.port||0)<2?"Needs a naval base of level 2 here first.":"",d:"Ships in this port mend 6% faster each month per level, and dreadnoughts can be built only where there is a dry dock."});
mkB("coal",{n:"Coaling station",max:2,grp:"mil",m:6,cost:{timber:300,cement:120,steel:60},tech:"ironclad",chk:(c,p)=>p.sea?"":"Needs a coast.",d:"Steam warships within two sea zones (three at level 2) keep their organization; far from any station they recover at half pace. Read by fleet recovery."});
mkB("telegraph",{n:"Telegraph office",max:2,grp:"eco",m:8,cost:{timber:100,machinery:25,paper:60},tech:"telegraph",d:"Administration +2% and tax collection +1% per level for the whole nation (at most +10% and +5% with courts too). Read by administration and tax collection."});
mkB("customs",{n:"Customs house",max:2,grp:"eco",m:8,cost:{timber:250,cement:150,paper:100},chk:(c,p)=>p.sea?"":"Needs a coast.",d:"Tariff income +8% per level (at most +30% for the nation). Read by tariff revenue."});
mkB("bank",{n:"Bank branch",max:2,grp:"eco",m:10,cost:{cement:250,furniture:150,paper:150},chk:(c,p)=>(G.decDone&&G.decDone[c.tag]||[]).includes("bank")?"":"Needs the central bank decision.",d:"More private capital stays invested instead of flowing back to households: the reserve for new factories grows 18% per level (at most +120% with the exchange). Read by the investment reserve."});
mkB("exchange",{n:"Stock exchange",max:1,grp:"eco",m:14,cost:{cement:400,furniture:200,paper:300},tech:"exchange",chk:(c,p)=>p.id!==c.cap?"Only in the capital.":"",d:"The reserve of private capital for new factories grows 45%. Capital only. Read by the investment reserve."});
mkB("school",{n:"School",max:3,grp:"soc",m:6,cost:{timber:150,cement:60,paper:80},d:"People here learn to read faster: the literacy target rises 3 points per level. Cheaper than a university. Read by the literacy growth."});
mkB("college",{n:"Technical college",max:2,grp:"soc",m:12,cost:{cement:250,paper:250,machinery:30},tech:"steam_eng",chk:(c,p)=>popAvg(p,"lit")<.35?"Needs a literacy of 35% here.":"",d:"Research +3 points a month per level. Needs a literate province. Read by the research rate."});
mkB("silo",{n:"Grain silo",max:2,grp:"soc",m:6,cost:{timber:300,cement:200},d:"In a bad year the people here keep their life needs 12 points higher per level, and a famine bites less. Read by population growth, unrest and the famine."});
mkB("water",{n:"Waterworks and sewers",max:2,grp:"soc",m:14,cost:{cement:500,timber:300,steel:100,machinery:30},tech:"antisep",chk:(c,p)=>p.pop<2000?"Only in cities of two million people or more.":"",d:"The people here grow faster, 0.02% a month per level, and are calmer. Read by population growth."});
mkB("power",{n:"Power station",max:2,grp:"eco",m:12,cost:{steel:200,machinery:120,cement:200},tech:"dynamo",chk:(c,p)=>p.factories.some(f=>f.lv>0)?"":"Needs a factory here.",d:"Every factory in this province produces 8% more per level. Read by factory output."});
mkB("police",{n:"Police station",max:2,grp:"soc",m:6,cost:{timber:150,cement:100,clothes:40},d:"Militancy here falls by 0.35 per level; people grow a little more politically aware. Read by militancy and consciousness."});
