/* === src/ui3.js === */
"use strict";
/* ================= U7: every page redesigned (Nation, Economy, Politics, Military) =================
   Shared parts first: page hero, jump chips, folding frames with an i button, tiles with sparklines,
   gauges, list rows, confirm sheets. Pages only read the game and draw. */
const VS=(b)=>`<svg class="vig" viewBox="0 0 160 92" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${b}</svg>`;
const PGV={
 nat:VS('<path d="M14 84h132M30 84c10-16 26-22 50-22s40 6 50 22" /><path d="M80 62V12"/><path d="M80 12c14-6 24 6 40 0v26c-16 6-26-6-40 0z" fill="var(--red)" stroke="none"/><circle cx="80" cy="10" r="2.6" fill="var(--gold)" stroke="none"/><path d="M42 84V72h8v12M104 84V70h10v14M54 84V76h6v8" stroke-width="1.6"/>'),
 eco:VS('<path d="M14 84h132"/><path d="M26 84V50l20 10V50l20 10V50l20 10V84z" fill="var(--gold-soft)"/><path d="M92 84V28h14v56M89 28h20" stroke-width="2.2"/><path d="M99 22c-6-4 4-8-1-13M110 16c-5-4 3-7-1-11" stroke-width="1.3" opacity=".6"/><circle cx="130" cy="70" r="12" fill="var(--gold-soft)"/><path d="M130 63v14M126 67h6a3 3 0 0 1 0 6h-6" stroke-width="1.6"/><path d="M36 74h6M52 74h6M68 74h6" stroke-width="1.6"/>'),
 pol:VS('<rect x="46" y="44" width="68" height="40" rx="3" fill="var(--gold-soft)"/><path d="M46 56h68M64 44V34h32v10"/><path d="M66 14h28v32H66z" fill="var(--panel)"/><path d="M72 22h16M72 28h16M72 34h10" stroke-width="1.4"/><circle cx="80" cy="70" r="3.5" fill="var(--red)" stroke="none"/><path d="M14 84h132"/>'),
 mil:VS('<path d="M14 84h132"/><path d="M40 84L64 44l24 40z" fill="var(--gold-soft)"/><path d="M64 44V84M54 84l10-24 10 24" stroke-width="1.5"/><path d="M104 84V16"/><path d="M104 16c10-4 16 4 28 0v20c-12 4-18-4-28 0z" fill="var(--red)" stroke="none"/><path d="M114 84h22M118 84v-8h14v8" stroke-width="1.6"/><circle cx="104" cy="13" r="2.4" fill="var(--gold)" stroke="none"/>'),
 dip:VS('<circle cx="80" cy="46" r="32" fill="var(--gold-soft)"/><path d="M48 46h64M80 14c14 12 14 52 0 64M80 14c-14 12-14 52 0 64M54 30c16 6 36 6 52 0M54 62c16-6 36-6 52 0" stroke-width="1.5"/><path d="M62 86h36M80 78v8" /><circle cx="80" cy="10" r="2.4" fill="var(--red)" stroke="none"/>'),
 tech:VS('<path d="M24 80c18-8 38-8 56 0 18-8 38-8 56 0V30c-18-8-38-8-56 0-18-8-38-8-56 0z" fill="var(--gold-soft)"/><path d="M80 30v50" /><path d="M36 42c12-3 24-3 34 2M36 54c12-3 24-3 34 2M90 44c10-5 22-5 34-2M90 56c10-5 22-5 34-2" stroke-width="1.3"/><path d="M80 6l3 7 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1z" fill="var(--red)" stroke="none"/>'),
 chron:VS('<rect x="34" y="14" width="92" height="68" rx="2" fill="var(--panel)"/><path d="M44 28h72M44 36h30M44 44h30M44 52h30M44 60h30M82 36h34v26H82z" stroke-width="1.5"/><path d="M44 22h72" stroke-width="3"/><circle cx="99" cy="49" r="7" fill="var(--gold-soft)"/><path d="M126 30l12 6v46H34" stroke-width="1.5" opacity=".6"/>'),
 ledger:VS('<path d="M30 14h84a6 6 0 0 1 6 6v62H36a6 6 0 0 1-6-6z" fill="var(--panel)"/><path d="M30 76a6 6 0 0 1 6-6h84" /><path d="M46 62V44M60 62V34M74 62V50M88 62V28M102 62V40" stroke-width="5" stroke="var(--gold)"/><path d="M42 62h68" stroke-width="1.4"/><path d="M46 24h40" stroke-width="2"/><circle cx="102" cy="22" r="3" fill="var(--red)" stroke="none"/>'),
 peace:VS('<circle cx="80" cy="46" r="30" fill="var(--gold-soft)" opacity=".7"/><path d="M26 76c26-6 52-24 80-34" stroke-width="2.4"/><path d="M44 70c-8-10-4-18 4-20 2 10-2 14-4 20zM62 64c-8-10-4-18 4-20 2 10-2 14-4 20zM80 56c-8-10-4-18 4-20 2 10-2 14-4 20zM98 48c-8-10-4-18 4-20 2 10-2 14-4 20z" fill="var(--turq)" stroke="none"/><path d="M52 56c4-8 12-8 14 0-4 6-10 6-14 0zM70 48c4-8 12-8 14 0-4 6-10 6-14 0zM88 40c4-8 12-8 14 0-4 6-10 6-14 0z" fill="var(--turq)" stroke="none" opacity=".8"/><path d="M110 40c10-10 20-6 28-14-2 12-10 20-24 20z" fill="var(--panel)"/>'),
 war:VS('<path d="M40 14l60 60M120 14L60 74" stroke-width="3"/><path d="M96 70l12 12M64 70L52 82M36 10l8 0 0 8M124 10l-8 0 0 8" stroke-width="3"/><path d="M80 24c10 0 18 4 18 12 0 10-8 18-18 24-10-6-18-14-18-24 0-8 8-12 18-12z" fill="var(--red)" stroke="none"/><path d="M80 32v18M72 40h16" stroke="var(--panel)" stroke-width="2.4"/>'),
 prov:VS('<path d="M10 84h140"/><path d="M14 84c14-26 30-34 46-34s30 12 40 34M64 84c10-18 22-26 36-26s30 10 46 26" fill="var(--gold-soft)"/><path d="M92 58V40h22v18" fill="var(--panel)"/><path d="M92 40l11-9 11 9M103 31V20" /><path d="M103 20l9 3-9 3z" fill="var(--red)" stroke="none"/><path d="M26 74v-8M32 74v-10M38 74v-8" stroke="var(--turq)" stroke-width="3"/>')
};
/* a page opens with a vignette, a title, an italic line and the ornament */
const hero=(k,t,s)=>`<header class="headpiece">${PGV[k]||VIG}<h1>${t}</h1><div class="sub">${s}</div>${HEADORN}</header>`;
const DA=(a,d)=>`data-a="${a}"`+Object.keys(d||{}).map(k=>` data-${k}="${esc(d[k])}"`).join("");
/* the i button: long explanations live behind it */
const INFO=(ti,x)=>`<button class="inf" data-a="info" data-ti="${esc(ti)}" data-x="${esc(x)}" aria-label="What this means: ${esc(ti)}"><span>i</span></button>`;
/* a folding frame; o: {info:[title,text], sum:"short text shown beside the title", closed:1} */
function fr(pg,i,title,body,o){o=o||{};const key=pg+":"+title,F=FOLDS(),col=F[key]===undefined?!!o.closed:F[key]===true;
 return`<section class="frame${col?" collapsed":""}" data-si="${i}"><h2 class="foldh" data-a="fold" data-k="${esc(key)}" role="button" tabindex="0" aria-expanded="${!col}"><span class="ft">${esc(title)}</span>${o.sum?`<span class="fsum">${o.sum}</span>`:""}${o.info?INFO(o.info[0],o.info[1]):""}${CHEV}</h2>${body}</section>`;}
/* a whole page: hero, tips, optional lead block, jump chips, frames. secs: [chip, title, body, opts] */
function pageHTML(pg,vig,title,sub,secs,o){o=o||{};secs=secs.filter(s=>s);
 const nav=secs.length>2?`<nav class="jumpbar" aria-label="Sections on this page">${secs.map((s,i)=>`<button data-a="jumpsec" data-i="${i}">${s[0]}</button>`).join("")}</nav>`:"";
 return hero(vig,title,sub)+(o.pre||"")+coachHTML(pg)+nav+secs.map((s,i)=>fr(pg,i,s[1],s[2],s[3])).join("")+TAILORN;}
/* sparkline: values oldest first */
function spark(v,o){v=(v||[]).filter(x=>x!=null&&isFinite(x));if(v.length<3)return"";const lo=Math.min(...v),hi=Math.max(...v),W=72,H=24,n=v.length,X=i=>(2+i/(n-1)*(W-4)).toFixed(1),Y=x=>(hi-lo<1e-9?H/2:H-3-(x-lo)/(hi-lo)*(H-6)).toFixed(1);
 return`<svg class="sp${o&&o.bad?" bad":""}" viewBox="0 0 ${W} ${H}" aria-hidden="true"><path d="${v.map((x,i)=>(i?"L":"M")+X(i)+" "+Y(x)).join("")}"/><circle cx="${X(n-1)}" cy="${Y(v[n-1])}" r="2.2"/></svg>`;}
const hv=(t,k,neg)=>{const h=G.hist&&G.hist.n[t];return h&&h[k]?h[k].filter(x=>x!=null).map(x=>neg?-x:x):[];};
/* a tile: o {bad, good, a, d, ex, sp} */
function tl(k,v,d,o){o=o||{};const a=o.ex?"why":o.a,dd=o.ex?{k:o.ex}:o.d,t=a?"button":"div";
 return`<${t} class="kpi${a?" tap":""}${o.ex?" ex":""}${o.bad?" bad":""}${o.good?" ok":""}"${a?" "+DA(a,dd):""}><span class="k">${k}</span><span class="v">${v}</span><span class="d">${d||""}</span>${o.sp||""}</${t}>`;}
/* a gauge row: label, bar, right-aligned number. o {c: red|green|dim, mk: marker 0..1, a, d} */
function gz(l,v,mx,txt,o){o=o||{};const p=clamp(mx>0?v/mx:0,0,1),h=`<span class="gl">${l}</span><span class="meter ${o.c||""}"><i style="width:${(p*100).toFixed(0)}%"></i>${o.mk!=null?`<u style="left:${(clamp(o.mk,0,1)*100).toFixed(0)}%"></u>`:""}</span><em>${txt}</em>`;
 return o.a?`<button class="gz tap" ${DA(o.a,o.d)}>${h}</button>`:`<div class="gz">${h}</div>`;}
/* a list row: {lead, t, s, v, vs, vc, bar:[0..1], bc, a, d, btn:[label, act, data, class, disabled, why]} */
function lr(o){const inner=`${o.lead?`<span class="ll">${o.lead}</span>`:""}<span class="lm"><b>${o.t}</b>${o.s?`<small>${o.s}</small>`:""}${o.mid||""}${o.bar!=null?`<span class="meter ${o.bc||""}"><i style="width:${(clamp(o.bar,0,1)*100).toFixed(0)}%"></i></span>`:""}</span>${o.v!=null?`<span class="rv ${o.vc||""}">${o.v}${o.vs?`<small>${o.vs}</small>`:""}</span>`:""}`;
 const b=(o.btn?`<button class="btn sm ${o.btn[3]||""}" ${DA(o.btn[1],o.btn[2])}${o.btn[4]?" disabled":""}>${o.btn[0]}</button>`:"")+(o.btn2||[]).map(x=>`<button class="btn sm ${x[3]||""}" ${DA(x[1],x[2])}${x[4]?" disabled":""}${x[5]?` aria-label="${x[5]}"`:""}>${x[0]}</button>`).join("");
 return`<div class="lr${o.cls?" "+o.cls:""}">${o.a?`<button class="lrb" ${DA(o.a,o.d)}>${inner}</button>`:`<div class="lrb">${inner}</div>`}${b}</div>${o.btn&&o.btn[4]&&o.btn[5]?`<div class="why">${o.btn[5]}</div>`:""}`;}
const kr=(k,v,c)=>`<div class="kr"><span>${k}</span><b class="${c||""}">${v}</b></div>`;
const cta=(label,a,d,o)=>{o=o||{};return`<div class="cta"><button class="btn ${o.sec?"":o.dng?"dng":"pri"}" ${DA(a,d)}${o.off?" disabled":""}>${label}</button>${o.off&&o.why?`<small>${o.why}</small>`:""}</div>`;};
const note=t=>`<p class="small muted">${t}</p>`;
const FL=t=>`<span class="fl2">${flagOf(t)}</span>`;
const dot=c=>`<i class="dt2" style="background:${c}"></i>`;
/* confirm sheet for anything that cannot be undone: it says what it costs, and the red button does it */
function askSheet(o){const g=o.go||["close",{}];
 openModal(`<div class="msheet cf" tabindex="-1"><div class="sh-h"><h2>${o.ti}</h2><button class="x" data-a="close" aria-label="Close">×</button></div>${o.lead||""}${o.body?`<p>${o.body}</p>`:""}${o.rows?`<div class="exl">${o.rows.map(r=>exR(r[0],r[1],r[2])).join("")}</div>`:""}${o.note?`<p class="small muted">${o.note}</p>`:""}<div class="dfoot2"><button class="btn" data-a="close">${o.cancel||"Not now"}</button><button class="btn ${o.danger?"dng":"pri"}" ${DA("cf",Object.assign({go:g[0]},g[1]))}${o.off?" disabled":""}>${o.lab}</button></div>${o.off&&o.why?`<p class="small bad" style="text-align:center">${o.why}</p>`:""}</div>`);}
Object.assign(ACT,{cf:(d,el)=>{closeModal();const f=ACT[d.go];if(f)f(d,el);},
 info:d=>openModal(`<div class="msheet" tabindex="-1"><div class="sh-h"><h2>${esc(d.ti)}</h2><button class="x" data-a="close" aria-label="Close">×</button></div>${String(d.x).split("|").map(x=>`<p>${esc(x)}</p>`).join("")}</div>`)});

/* ---------- history helpers ---------- */
function slider(lbl,key,val,min,max,notes){return`<div class="sl"><div class="sl-h"><span>${lbl}</span>${notes?INFO(lbl,notes):""}<b>${Math.round(val*100)}%</b></div><input type="range" min="${min}" max="${max}" value="${Math.round(val*100)}" data-c="${key}" aria-label="${esc(lbl)}"></div>`;}
function histBody(c){const t=c.tag,L=(s,o)=>lineChart(natSeries(t,s[0],s[1]),o);
 return`<h3>People</h3>${L(["pop","People"],{fmt:(v,sp)=>v>=1e3?(v/1e3).toFixed(sp<8000?1:0)+"M":Math.round(v)+"k",label:"Population by year"})}<h3>National income</h3>${L(["inc","Income"],{fmt:v=>money(v),label:"National income by year"})}<h3>Factory levels</h3>${L(["fac","Levels"],{fmt:v=>String(Math.round(v)),zero:1,label:"Factory levels by year"})}<h3>Rank among nations</h3>${lineChart(natSeries(t,"rank","Rank").map(s=>({n:s.n,i:s.i,v:s.v.map(v=>v?-v:v)})),{fmt:v=>"#"+Math.round(-v),label:"Rank by year"})}`;}

/* ================= THE NATION ================= */
function pgNat(){const c=me(),st=c.stat||{},N=st.N||{},tag=c.tag,nf=natFig(c),net=st.net||0,rank=G.rank.indexOf(tag)+1,inc=(st.gdp||0)*12,cl=creditLimit(c),mh=(G.mh||[]),tx=st.taxes||0,tf=st.tariffs||0,tin=tx+tf,pay=st.pay||0,gov=st.gov||0,itr=st.interest||0,mx=Math.max(tin,pay+gov+itr,1),run=net<0&&c.tr>0?Math.floor(c.tr/-net):null,H=G.hist&&G.hist.n[tag]||{};
 const s0=`<div class="kgrid">${tl("Rank",ord(rank),isGP(tag)?"a Great Power":"among the nations",{ex:"rank",sp:spark(hv(tag,"rank",1))})}${tl("People",ppl(st.pop||0),"literacy "+pct(st.lit||0),{sp:spark(H.pop)})}${tl("National income",money(inc),"a year",{ex:"inc",sp:spark(H.inc)})}${tl("Factory levels",String(Math.round(sum(provsOf(tag),p=>sum(p.factories,f=>f.lv)))),"across the land",{a:"tab",d:{t:"eco"},sp:spark(H.fac)})}</div>
 <div class="facts">${kr("Government",esc(GOVS[c.gov].n))}${kr("Ruling party",esc(IDEOS[c.ideo].n))}${kr("Economy",esc(ECON[c.econ].n))}${kr("Trade policy",esc(TRADE[c.trade].n))}${kr("Status",c.civ?"Civilized":"Unrecognized",c.civ?"good":"bad")}</div>
 ${gz("Prestige",c.pres,Math.max(150,c.pres),Math.round(c.pres))}${gz("War exhaustion",c.we,100,Math.round(c.we)+" of 100",{c:c.we>=40?"red":"",mk:.5})}${gz("Infamy",c.infamy,COAL_AT*1.2,c.infamy.toFixed(1)+" of "+COAL_AT,{c:c.infamy>COAL_AT-6?"red":"",mk:COAL_AT/(COAL_AT*1.2)})}`;
 const lock=(c.noBorrow||0)>G.t?`<div class="al bad" style="pointer-events:none;margin:.4rem 0">Lenders have shut their doors on us until ${1836+Math.ceil(c.noBorrow/12)}.</div>`:"";
 const s1=`<div class="kgrid">${tl("Balance",(net>=0?"+":"−")+money(Math.abs(net)),net<0?(run!=null?"reserves last "+run+" month"+(run===1?"":"s"):"reserves are gone"):"a month, in the black",{ex:"net",bad:net<0,sp:spark(mh.map(x=>x[2]),{bad:net<0})})}${tl("Treasury",moneyS(c.tr),c.debt>0?"debt "+money(c.debt):"no debt",{ex:"net",bad:c.tr<0,sp:spark(mh.map(x=>x[1]),{bad:c.tr<0})})}</div>
 <h3>Coming in</h3>${gz("Taxes",tx,mx,money(tx),{c:"green"})}${gz("Tariffs",tf,mx,money(tf),{c:"green"})}<h3>Going out</h3>${gz("Pay",pay,mx,money(pay),{c:"red"})}${gz("Supplies and building",gov,mx,money(gov),{c:"red"})}${gz("Interest",itr,mx,money(itr),{c:"red"})}
 <h3>Credit</h3>${gz("Debt",c.debt,Math.max(cl,1),money(c.debt)+" of "+money(cl),{c:c.debt>.8*cl&&cl>0?"red":""})}${kr("Interest rate",pct(interestRate(c))+" a year")}${lock}
 ${net<0?cta("Adjust the taxes","jumpsec",{i:2}):""}${c.debt>0?cta("Default on the debt","dfltask",{},{sec:1}):""}`;
 const sl=(l,k,v,min,mxx,n)=>slider(l,k,v,min,mxx,n);
 const s2=`${sl("The poor","tax0",c.tax[0],0,100,"Farmers, labourers, craftsmen and soldiers. Heavy taxes here anger the most people but raise the least from each.")}${sl("The middle classes","tax1",c.tax[1],0,100,"Artisans, clerks, clergy, officials and officers. They pay well and notice it.")}${sl("The rich","tax2",c.tax[2],0,100,"Aristocrats and capitalists. They pay the most, and they invest what they keep.")}${sl("Tariff","tariff",c.tariff,0,Math.round(TRADE[c.trade].max*100),TRADE[c.trade].n+" allows up to "+pct(TRADE[c.trade].max)+". Tariffs raise money and protect home industry; they make imports dearer.")}${gz("Taxes collected",c.eff.tax,1,pct(c.eff.tax),{c:"green"})}`;
 const s3=`${sl("Education","edu",c.sp.edu,0,100,"Pays "+ppl(N.CLE||0)+" clergy and teachers. It raises literacy and research.")}${sl("Administration","adm",c.sp.adm,0,100,"Pays "+ppl(N.BUR||0)+" officials. It decides how well taxes are collected.")}${sl("Social spending","soc",c.sp.soc,0,100,"Relief, pensions and health care, if reforms allow. It calms the poor.")}${sl("Military","mil",c.sp.mil,0,100,"Pays "+ppl(N.SOL||0)+" soldiers and their officers. It buys supplies and morale.")}${gz("Administration at work",c.eff.admin,1,pct(c.eff.admin),{c:"green"})}`;
 return pageHTML("nat","nat",esc(c.n),esc(GOVS[c.gov].n)+", "+esc(IDEOS[c.ideo].n)+" rule",[
  ["State","The state of the nation",s0,{info:["Status and prestige","Prestige comes from industry, army and victories, and sets the rank.|Infamy rises when we take land. At "+COAL_AT+" our neighbours form a coalition against us.|Unrecognized nations become civilized by reaching literacy of 18% and ten technologies."]}],
  ["Budget","The budget",s1,{sum:moneyS(net),info:["Credit and default","The credit limit is about five years of income.|Defaulting wipes out the debt, but it costs prestige, closes the credit market for ten years and gives the Great Powers a reason for war. A treasury below zero for six months forces it."]}],
  ["Taxes","Taxes",s2,{info:["Taxes","Each class is taxed at its own rate. Higher rates bring in more money and anger the people taxed. The slider changes the rate at once; the effect shows next month."]}],
  ["Spending","Spending",s3,{info:["Spending","Each budget line pays a group of public servants. Cutting a line saves money now but weakens what it buys: schools, officials, relief or the army."]}],
  ["History","Over the years",histBody(c),{closed:1}]]);}

/* ================= THE ECONOMY ================= */
function ecoPriceChart(){const c=me(),H=G.hist,sel=(UI.cg||CG0).filter(g=>GOODS[g]);const chips=GK.filter(g=>goodOK(c,g)).map(g=>`<button class="pill${sel.includes(g)?" on":""}" data-a="chgood" data-g="${g}">${GOODS[g].n}</button>`).join("");
 const ser=H?sel.slice(0,6).map(g=>({n:GOODS[g].n,v:H.pr[g]||[],i:0})):[];
 return`<p class="small muted">Against the 1836 price. The dashed line is 1.0.</p>${lineChart(ser,{base:1,fmt:v=>v.toFixed(1),legend:1,label:"Price index by year"})}<div class="dfil chips">${chips}</div>`;}
function tradeRows(m,imp,c){const rows=Object.keys(m).map(g=>[g,m[g][0]*G.price[g],m[g][1]*G.price[g]]).sort((a,b)=>b[1]-a[1]).slice(0,7),mx=Math.max(1,...rows.map(r=>r[1]));
 return rows.length?rows.map(([g,v,sv])=>lr({t:GOODS[g].n,s:sv>v*.05?(imp?"from":"to")+" sphere partner, no tariff":"",bar:v/mx,bc:imp?"red":"green",v:money(v)})).join(""):note("None.");}
function pgEco(){const c=me(),st=c.stat||{},N=st.N||{},tag=c.tag,H=G.hist&&G.hist.n[tag]||{},nf=natFig(c);let ef=0,nn=0;for(const p of provsOf(tag))for(const q of p.pops)if(PTYPES[q.t].s===0){ef+=q.ed*q.n;nn+=q.n;}
 const inc=(st.gdp||0)*12,L=[];for(const p of provsOf(tag))for(const b of p.build)L.push([p,b]);
 const fac={};for(const p of provsOf(tag))for(const f of p.factories)if(f.lv>0)fac[f.g]=(fac[f.g]||0)+f.lv;
 const lead=c.sphere&&G.c[c.sphere]?G.c[c.sphere]:null,isl=Object.keys(G.c).filter(t=>G.c[t].alive&&G.c[t].sphere===tag).length;
 const workforce=provsOf(tag).map(p=>{
  const h=provincialHouseholds(p);
  const local=p.localMarket?Object.entries(p.localMarket).map(([g,r])=>
   kr(gnm(g),pct(r.fill)+" allocated · "+money((r.basePaid+r.freightPaid)/Math.max(r.purchased,1e-9))+" average paid · "+money(r.freightPaid)+" freight")
  ).join(""):"";
  const land=p.landUse;
  const employers=p.factories.filter(f=>f.employerAccount).map(f=>{
   const a=f.employerAccount;
   return `<h4>${esc(gnm(f.g))}</h4>${kr("Sales",money(a.revenue))}
    ${kr("Input costs",money(a.inputs))}${kr("Wages",money(a.wages))}${kr("Operating profit",money(a.profit))}`;
  }).join("");
  const landRows=land?`<h4>Farm capacity in labour units</h4>${kr("Subsistence use",ppl(land.subsistence))}
   ${kr("Commercial use",ppl(land.commercial))}${kr("Unused capacity",ppl(land.fallow))}`:"";
  return `<section><h3>${esc(p.n)}</h3>${kr("Subsistence population",ppl(h.subsistence))}
   ${kr("Craft workers",ppl(h.craft))}${kr("Clerks",ppl(h.clerks))}
   ${kr("Craft vacancies",ppl(h.craftVacancies))}${kr("Clerk vacancies",ppl(h.clerkVacancies))}
   ${kr("Qualified artisans available for clerical work",ppl(h.qualifiedArtisans))}
   ${kr("Household income",money(h.income))}${kr("Household taxes",money(h.tax))}
   ${kr("Household purchases",money(h.spending))}${landRows}${employers}${local?`<h4>Local household markets</h4>${local}`:""}</section>`;
 }).join("");
 const company=c.companyBudget,companyAccounts=tag==="GBR"&&company?
  `<section><h3>India administration accounts</h3>${kr("District tax collections",money(company.taxes))}
   ${kr("Revenue retained by the Company",money(company.retained))}${kr("Remitted to Britain",money(company.remitted))}
   ${kr("Company payroll",money(company.spent))}${kr("Company reserve",money(company.reserve))}
   ${company.transferred?kr("Reserve transferred to Crown",money(company.transferred)):""}</section>`:"";
 const tradePolicy=`<section><h3>Import policy</h3>
  ${c.commercialRoute?.until>G.t?`<p>Transit from ${esc(nameOf(c.commercialRoute.seller))} · ${esc(GOODS[c.commercialRoute.good].n)} · ends ${dateStr(c.commercialRoute.until)}</p><button class="btn sm" data-a="renewroute">Request renewal</button>`:
  `<label>Commercial partner <select id="route-seller">${Object.values(G.c).filter(x=>x.alive&&x!==c).map(x=>`<option value="${x.tag}">${esc(x.n)}</option>`).join("")}</select></label>
  <label>Good <select id="route-good">${GK.map(g=>`<option value="${g}">${esc(GOODS[g].n)}</option>`).join("")}</select></label>
  <button class="btn sm" data-a="commercialroute">Offer transit</button><p class="small muted">A controlled freight depot is required to receive shipments.</p>`}
  ${(G.tradeReceipts||[]).filter(r=>r.buyer===tag||r.seller===tag).map(r=>kr(GOODS[r.good].n,Math.round(r.quantity)+" units · "+money(r.value)+" goods"+(r.fee!=null?" · "+money(r.fee)+" treasury fee":""))).join("")}
  <p>Customs offices preserve more access to non-priority imports.</p>
  ${IMPORT_POLICIES.map(policy=>`<button class="btn sm" data-a="importpolicy" data-policy="${policy}" aria-pressed="${(c.importPolicy||"balanced")===policy}">${({balanced:"Balanced",industry:"Industry first",essentials:"Essentials first"})[policy]}</button>`).join("")}
  ${kr("Interest paid",money(st.interest||0))}${kr("Net change in debt",money(st.debtChange||0))}${(c.debt||0)>0?`<div class="cta"><button class="btn pri" data-a="repayall">Repay all loans</button></div>`:""}
  ${kr("Foreign dividends received",money(st.dividendsIn||0))}${kr("Dividends remitted abroad",money(st.dividendsOut||0))}</section>`;
 const s0=`<div class="kgrid">${tl("National income",money(inc),"a year",{ex:"inc",sp:spark(H.inc)})}${tl("Capital to invest",money(c.inv||0),"in private hands")}${tl("Imports",money(st.imp||0),"a month",{a:"jumpsec",d:{i:4}})}${tl("Exports",money(st.exp||0),"a month",{a:"jumpsec",d:{i:4}})}</div>
  ${gz("Life needs of the poor",nf.poor,1,pct(nf.poor),{c:nf.poor<.6?"red":"green",mk:.6})}${gz("Everyday needs of the poor",nn?ef/nn:0,1,pct(nn?ef/nn:0),{c:"green"})}${kr("Factory workers",ppl(N.CRA||0))}${kr("Immigrants",ppl(st.immig||0))}${workforce?`<details><summary>Provincial markets and households</summary>${workforce}</details>`:""}${tradePolicy}${companyAccounts}`;
 const mn=BR().all.find(r=>r.id==="fac"),slots=Math.max(2,Math.min(10,2+Math.floor(provsOf(tag).filter(p=>p.ctl===p.o&&p.col).length/4)));
 const gwst=GW.map(w=>[w,gwState(c,w),c.gw&&c.gw[w.id]]);
 const s1=`${L.length?L.map(([p,b])=>lr({t:projName(b),s:"in "+esc(p.n),bar:projProgress(b),v:pct(projProgress(b))})).join(""):`<p class="calm">Nothing is being built.</p>`}${gz("Works under way",L.length,slots,L.length+" of "+slots+" at a time")}
  ${mn?cta("Build "+gnm(mn.d.g)+" in "+esc(P(mn.d.p).n),"facmenu",{p:mn.d.p}):cta("Choose a province on the map","tab",{t:"map"},{sec:1})}
  <h3>Buildings and great works</h3>${cta("Open Works: what to build next","tab",{t:"works"},{sec:1})}`;
 const fk=Object.keys(fac).sort((a,b)=>fac[b]-fac[a]),fm=Math.max(1,...fk.map(g=>fac[g]));
 const s2=fk.length?fk.map(g=>{const m=facMargin(c,g);return lr({t:GOODS[g].n,s:r2(fac[g])+" levels",bar:fac[g]/fm,v:pct(m),vs:"margin",vc:m<.1?"bad":""});}).join("")+(modernLine(c)?note(modernLine(c)):""):`<p class="calm">No factories yet.</p>`;
 const mk=GK.filter(g=>goodOK(c,g)).map(g=>{const r=G.price[g]/GOODS[g].p,ch=G.price[g]/G.pricePrev[g]-1;return lr({t:GOODS[g].n,s:[(c.impSh&&c.impSh[g]>.05)?"import "+pct(c.impSh[g]):"",c.fill&&c.fill[g]<.95?'<span class="bad">short</span>':""].filter(x=>x).join(" · "),v:"£"+G.price[g].toFixed(2),vs:`<span class="${r>1.15?"bad":r<.85?"good":""}">${r>=1?"+":""}${Math.round((r-1)*100)}% on 1836</span>`});}).join("");
 const s4=`<div class="kgrid">${tl("Imports",money(st.imp||0),"a month")}${tl("Exports",money(st.exp||0),"a month")}</div><h3>Bought from abroad</h3>${c._tIm?tradeRows(c._tIm,1,c):note("Trade figures appear after the next month.")}<h3>Sold abroad</h3>${c._tEx?tradeRows(c._tEx,0,c):""}`;
 return pageHTML("eco","eco","The economy","Mills, markets, prices and trade",[
  ["Summary","Summary",s0],
  ["Building","Building",s1,{sum:L.length?L.length+" under way":"idle"}],
  ["Industry","Industry",s2,{info:["Industry",(ECON[c.econ].build?"The state may build factories: tap a province, then Build a factory.":"Under laissez-faire, capitalists mostly build factories. The state may still order one at a 50% premium.")+"|Capitalists invest in the goods with the best margins. A margin is what a factory earns over what its inputs cost.|Modernizing a factory (tap its province) raises output per worker."]}],
  ["Prices","Prices over the years",ecoPriceChart(),{closed:1}],
  ["Trade","Trade",s4,{info:["Trade","A month's flow, by value. "+(lead?"We are in the sphere of "+lead.n+": its goods reach us first and pay no tariff.":isl?"We lead a sphere of "+isl+" state"+(isl>1?"s":"")+": goods pass between us without tariffs.":"Spheres of the Great Powers trade among themselves without tariffs.")]}],
  ["Market","World market",`<p class="small muted">Prices against their 1836 level.</p>${mk}`,{closed:1}]]);}

/* ================= POLITICS ================= */
function stackBar(o){return`<div class="stack">${IK.filter(k=>o[k]>.01).map(k=>`<i style="width:${o[k]*100}%;background:${IDEOS[k].c}" title="${IDEOS[k].n}"></i>`).join("")}</div><div class="legp">${IK.filter(k=>o[k]>.02).sort((a,b)=>o[b]-o[a]).map(k=>`<span>${dot(IDEOS[k].c)}${IDEOS[k].n}<b>${pct(o[k])}</b></span>`).join("")}</div>`;}
function reformRow(c,r){const l=c.reforms[r.id]||0,can=canReform(c,r),n=r.lv.length-1,pips=Array.from({length:n},(_,i)=>`<i class="${i<l?"on":""}"></i>`).join("");
 return lr({t:esc(r.n),s:esc(r.lv[l]),cls:"reform",bar:null,v:`<span class="pips" aria-label="level ${l} of ${n}">${pips}</span>`,btn:l<n?[esc(r.lv[l+1]),"reformask",{id:r.id},can.ok?"pri":"",!can.ok&&r.id!=="vote",esc(can.why||"")]:null})+(l>=n?"":"");}
function pgPol(){const c=me(),uh=c.uh||upperHouse(c),lv=c.lastVote,mv=movements(c).slice(0,6),el=GOVS[c.gov].elect,sh=uh[c.ideo]||0,tag=c.tag,nf=natFig(c);
 const bill=c.landRevenue;
 const revenueBill=tag==="PUN"?`<section class="card"><h3>Land revenue bill</h3>
  ${bill?.enacted?`<p>Enacted ${bill.amended?"with the landholder amendment":"as introduced"}.</p>`:
  `<p>Transfer part of the tax burden from cultivators to landholders. An amendment reduces that transfer to win more landholder support.</p>
  <p>Support as introduced ${pct(landRevenueVote(c,false).yes)} · with amendment ${pct(landRevenueVote(c,true).yes)}</p>
  ${bill?.movement?`<p>Reform movement ${pct(bill.movement)} · the campaign survives defeat.</p>`:""}
  <button class="btn" data-a="landvote" data-amended="0" ${bill?.month===G.t?"disabled":""}>A. Vote on original bill</button>
  <button class="btn" data-a="landvote" data-amended="1" ${bill?.month===G.t?"disabled":""}>B. Vote with amendment</button>`}
  <p>Administrative reach ${pct(landRevenueVote(c,!!bill?.amended).administration)}</p>
  <h3>Standing school order</h3>${c.schoolOrder?
   `<p>${esc(P(c.schoolOrder.province).n)} · ${c.schoolOrder.queuedAt==null?"Waiting for the funding and control requirements":"Queued"}</p>`:
   `<p>Queue one school when the treasury holds two months of revenue.</p>
   ${provsOf(tag).filter(p=>p.ctl===tag&&bldCan(c,p,"school").ok).map(p=>
    `<button class="btn" data-a="schoolorder" data-p="${esc(p.id)}">${esc(p.n)}</button>`).join("")}`}
  </section>`:"";
 const s0=`<div class="kgrid">${tl("Government",esc(GOVS[c.gov].n),el?"elected":"appointed")}${tl("In power",esc(IDEOS[c.ideo].n)+"s","")}${tl("Next election",el?c.elect+" months":"none",el?"the voters decide":"the sovereign decides")}${tl("Citizenship",esc(CITIZEN[c.cit].n),"who counts as a citizen")}</div>
  ${gz("Support in the chamber",sh,1,pct(sh),{c:sh<.3?"red":"green",mk:.5})}${gz("Popular anger",nf.mil,10,nf.mil.toFixed(1)+" of 10",{c:nf.mil>=4?"red":"",mk:.4,a:"why",d:{k:"mil"}})}
  ${revenueBill}
 <h3>Upper house</h3>${stackBar(uh)}${lv?`<h3>Last election</h3>${stackBar(lv)}`:""}
  ${!c.ai?`<h3>Choose the government ${INFO("Choosing the government",el?"Under this constitution, the voters decide.":"The monarch appoints the government. Pick the party you want in power.")}</h3><div class="seg">${IK.filter(ideoOK).map(k=>`<button class="btn sm ${c.ideo===k?"on":""}" data-a="party" data-k="${k}" ${el?"disabled":""}>${IDEOS[k].n}</button>`).join("")}</div>`:""}`;
 const decs=DEC.map(d=>[d,decState(c,d)]).filter(([,s])=>s!==null&&s!=="done"),taken=(G.decDone&&G.decDone[tag]||[]);
 const s1=decs.length?decs.map(([d,s])=>lr({t:"<b>"+esc(d.n)+"</b>",s:esc(d.d)+(s==="date"?" From "+d.y+".":s==="cond"&&d.why?" "+esc(d.why(c)):""),btn:["Enact","decask",{id:d.id},s==="ok"?"pri":"",s!=="ok"]})).join("")+(taken.length?note("Taken: "+taken.map(id=>DEC.find(d=>d.id===id).n).join("; ")+"."):""):`<p class="calm">No decisions are open to us now.</p>`+(taken.length?note("Taken: "+taken.map(id=>DEC.find(d=>d.id===id).n).join("; ")+"."):"");
 const rf=k=>gz("Upper house support",reformSupport(c,k),1,pct(reformSupport(c,k)),{mk:.5,c:reformSupport(c,k)>=.5?"green":""})+gz("Popular pressure",reformPressure(c,k),2,reformPressure(c,k).toFixed(2),{mk:.6,c:reformPressure(c,k)>=1.2?"green":""})+REFORMS.filter(r=>r.k===k).map(r=>reformRow(c,r)).join("");
 const s4=mv.length?mv.map(m=>lr({t:esc(rebelName(m.key)),bar:Math.min(1,m.n/Math.max(1,(c.stat.pop||1)*.1)),bc:"red",v:ppl(m.n)})).join(""):`<p class="calm">No movement threatens the state.</p>`;
 return pageHTML("pol","pol","Politics","Parties, reforms and the mood of the people",[
  ["Government","The government",s0],
  ...(c.civ?[]:[["Modern","Modernisation",modBody(c),{sum:Math.round(c.modern||0)+"%",info:["Modernisation","Nine reforms in three tracks, paid in research points. Each raises research, lowers study costs and stirs resistance. Every card shows the five-year payoffs and the chance of revolt."]}]]),
  ["Decisions","Decisions",s1,{sum:decs.filter(x=>x[1]==="ok").length?decs.filter(x=>x[1]==="ok").length+" open":"",info:["Decisions","Each decision is a one-time choice, offered when its conditions are met."]}],
  ["Political","Political reforms",rf("p"),{info:["Reforms","A reform passes when the upper house supports it (half or more), or when popular pressure is 1.2 or higher. After one reform the government waits a year before the next."]}],
  ["Social","Social reforms",rf("s")],
  ["Movements","Movements",s4,{info:["Movements","People with militancy above 5 gather into movements; large ones rise in arms."]}]]);}

/* A6: Modernisation panel (uncivilised nations): progress, nine reforms in three tracks, payoff table per reform */
function modTbl(c,id){const t=modTable(c,id);return`<table class="modt" style="width:100%;font-size:.78em;border-collapse:collapse"><tr><th></th><th>Research</th><th>Tax</th><th>Attack</th><th>Revolt</th></tr>${t.rows.map(r=>`<tr><td>${r.l}</td><td>${r.res>=0?"+":""}${r.res}</td><td>${r.tax>=0?"+":""}${r.tax}</td><td>${r.atk}%</td><td>${r.rev}%</td></tr>`).join("")}</table><small>${t.pick===id?"Minister's pick. ":""}5 years: research points, tax pounds, a Great Power's chance to win a war, revolt within 24 months. ${esc(t.assume)}</small>`;}
function modBody(c){const m=Math.round(c.modern||0),tr={army:"Army",economy:"Economy",administration:"Administration"};let h=`<div class="kgrid">${tl("Modernisation",m+"%","of 100")}${tl("Research points",String(Math.floor(c.rp)),"shared with studies")}</div>${gz("Progress",(c.modern||0)/100,1,m+"%",{mk:.8})}${note("Westernise at 100%, or at 80% with 25% literacy. One reform every 6 months.")}`;
 for(const k of Object.keys(tr)){h+=`<h3>${tr[k]}</h3>`+MOD_REFORMS.filter(r=>r.tr===k).map(r=>{const d=modHas(c,r.id),can=modCan(c,r.id);return lr({t:esc(r.n),s:esc(r.fx)+" +"+r.pr+"%, "+r.cost+" points"+(d?". Done.":""),mid:d?"":modTbl(c,r.id),btn:d?null:["Enact","modreform",{id:r.id},can.ok?"pri":"",!can.ok],})+(d||can.ok?"":note(esc(can.why)));}).join("");}
 return h;}
/* ================= MILITARY ================= */
const GEN_PILL=g=>`<span class="pills"><span title="attack">A ${g.atk}</span><span title="defense">D ${g.def}</span><span title="marching">M ${g.mv}</span></span>`;
function mobBody(c){const m=c.mob||{st:0},pl=mobPlan(c);
 if(!m.st){const bad=mobCan(c,pl);return`<div class="kgrid">${tl("Standing army",String(pl.now),"brigades")}${tl("Could be raised",String(pl.units),"more brigades, "+ppl(pl.men)+" men")}</div>${cta("Mobilize","mobask",{},{off:!!bad,why:bad?esc(bad):""})}`;}
 let n=0;for(const a of G.armies)if(a.o===c.tag&&!a.naval)for(const u of a.u)if(u.mob)n++;let away=0;for(const k in m.tk)away+=m.tk[k][0]+m.tk[k][1];
 return`<div class="al ${m.st===3?"good":"warn"}" style="pointer-events:none">${m.st===1?"Mobilizing, month "+Math.min(2,m.ph+1)+" of 2":m.st===2?"Mobilized since "+dateStr(m.t0):"Demobilizing: the men go home at the start of next month"}.</div><div class="kgrid">${tl("Conscripts",String(n),"brigades under arms")}${tl("Away from work",ppl(away),"in the fields and mines")}</div>${m.st===3?"":cta("Demobilize","demask",{},{})}`;}
function pgMil(){thSync();const c=me(),A=G.armies.filter(a=>a.o===c.tag&&a.u.length),N=c.stat.N||{},tag=c.tag,land=A.filter(a=>!a.naval),sea=A.filter(a=>a.naval),leaders=c.leaders||[],gen=A.filter(a=>a.gen);
 const ty={inf:0,cav:0,art:0,con:0};for(const a of land)for(const u of a.u){ty[thTypeOf(u)]++;if(u.mob)ty.con++;}
 const wars=G.wars.filter(w=>w.att.includes(tag)||w.def.includes(tag)),inf=Object.values(G.c).filter(k=>k.alive&&k.blk&&k.blk.by===tag&&k.blk.share>.02),blk=c.blk&&c.blk.share>.02;
 const warBar=wars.length?wars.map(w=>{const side=w.att.includes(tag)?1:2,ws=side===1?w.ws:-w.ws,foes=(side===1?w.def:w.att).map(nameOf).join(", ");return`<div class="al ${ws<-20?"bad":"warn"}" style="pointer-events:none">At war with ${esc(foes)}: score ${Math.round(ws).toString().replace("-","−")}.</div>`;}).join(""):"";
 const s0=`${blk?`<div class="al bad" style="pointer-events:none">Our ports are blockaded by ${esc(nameOf(c.blk.by))}: ${Math.round(c.blk.share*100)}% of our coast. Trade is at ${Math.round(c.access*100)}%. Send a stronger fleet to the port to break it.</div>`:""}${warBar}
  <div class="kgrid">${tl("Infantry",String(ty.inf),ty.con?ty.con+" are conscripts":"brigades")}${tl("Cavalry",String(ty.cav),"scouts and pursuit")}${tl("Artillery",String(ty.art),"breaks trenches and forts")}${tl("Reserve",String(thBrig(tag,"res").n),"brigades at the capital")}${tl("Soldiers",ppl(N.SOL||0),"the conscription pool",{ex:"sup"})}${tl("Being raised",String((c.recq||[]).length),"in the barracks")}</div>${gz("War exhaustion",c.we,100,Math.round(c.we)+" of 100",{c:c.we>=40?"red":"",mk:.5})}${wars.length?cta("Peace terms","dealopen",{w:wars[0].id},{sec:1}):""}`;
 const mobInfo=["Mobilization",mobFx(c,mobPlan(c))];
 const s2=thHTML(c),thn=thRows(c).length;
 const s3=A.filter(a=>a.gen).map(a=>lr({t:esc(a.gen.n),s:"leads "+a.u.length+" "+(a.naval?"ships":"brigades")+(a.naval?" at "+esc(P(a.loc).n):" in "+esc(thName(a.th)))+", age "+Math.floor(a.gen.age),v:GEN_PILL(a.gen)})).join("")+leaders.map(g=>lr({t:esc(g.n),s:"no army, age "+Math.floor(g.age),v:GEN_PILL(g),vs:"free"})).join("")||`<p class="calm">We have no generals yet.</p>`;
 const navImg=window.LC_ASSETS?.pictures?.navalFleet;
 const navBanner=navImg?`<div class="lc-scene-banner" style="background:${navImg.fallbackGradient}"><img src="${navImg.src}" alt="${esc(navImg.alt)}" loading="lazy" onerror="this.style.display='none'"><div class="lc-scene-cap">Admiralty Fleet Command</div></div>`:"";
 const s4=`${navBanner}<div class="kgrid">${tl("Warships",String(sum(navFleets(tag),a=>a.u.length)),"in "+navRows(c).filter(x=>navFleets(tag).some(a=>a.sr===x)).length+" sea"+(navRows(c).filter(x=>navFleets(tag).some(a=>a.sr===x)).length===1?"":"s"))}${tl("Transports",String(sum(sea.filter(a=>!a.u.some(isWarship)),a=>a.u.length)),"carry armies")}${tl("Our blockades",String(inf.length),inf.length?"nations shut in":"none")}${tl("Blockade on us",blk?Math.round(c.blk.share*100)+"%":"none",blk?esc(nameOf(c.blk.by)):"",{bad:blk})}</div>${inf.length?inf.map(k=>lr({lead:FL(k.tag),t:esc(k.n),s:"our blockade",bar:k.blk.share,bc:"green",v:Math.round(k.blk.share*100)+"%",vs:"of its coast"})).join(""):""}${navHTML(c)}`;
 const s5=Object.keys(UNITS).filter(k=>!UNITS[k].tech||c.tech[UNITS[k].tech]).map(k=>{const U=UNITS[k],st=uStat(c,k);return lr({t:U.n,s:"costs "+Object.keys(U.cost).map(g=>U.cost[g]+" "+GOODS[g].n.toLowerCase()).join(", "),v:`<span class="pills"><span>A ${st.a.toFixed(1)}</span><span>D ${st.d.toFixed(1)}</span></span>`,btn:["Raise","recruit",{k,p:c.cap},"pri"]});}).join("")+`<label class="mvto rdest">New brigades join<select data-sel="rdest" aria-label="Where new brigades join"><option value="">Where they are raised (the capital)</option><option value="res"${c.rdest==="res"?" selected":""}>The reserve</option>${thList(tag).filter(r=>thHub(tag,r)).map(r=>`<option value="${r}"${c.rdest===r?" selected":""}>${esc(REGION[r].n)}</option>`).join("")}</select></label>`+note("Raised at the capital, then sent where you choose. Ships are raised at a port: tap the province, then Recruit.");
 return pageHTML("mil","mil","The army","Armies, fleets and commanders",[
  ["Strength","Men and supply",s0,{info:["War exhaustion","War exhaustion rises with every month of war and every defeat. At 50 the people want peace; at 100 the government may fall."]}],
  ["Mobilize","Mobilization",mobBody(c),{info:mobInfo,sum:c.mob&&c.mob.st?"under way":""}],
  ["Armies","Theatres",s2,{sum:thn?thn+"":"",info:["Theatres","The map is split into regions. Our brigades in a region form a theatre. Give each theatre a stance and, for an attack, an objective; its general does the marching. Move brigades between theatres with the Move button. Infantry holds the line, cavalry scouts and runs down a beaten enemy, and artillery cuts trenches and forts. Brigades above a province's supply limit lose strength every month."]}],
  ["Navy","Navy by station",s4,{sum:sea.length?sum(sea,a=>a.u.length)+" ships":"",info:["Navy by station","Ships are posted to a sea, not moved one by one. Each sea has a mission: Blockade, Patrol and escort, Seek battle, Support landing or Fleet in port. The ships sail to the right port by themselves each month. Send ships from one sea to another with the Send ships button."]}],
  ["Generals","Commanders",s3,{info:["Generals","Each point of attack or defense is worth 8% in battle; each point of marching makes an army 10% faster. Leadership grows with our officers and military spending: "+Math.floor((c.lead||0)/GEN_AT*100)+"% of the way to the next general. Generals are given to the biggest armies of each theatre automatically."]}],
  ["Raise","Raise forces",s5]]);}


ACT.repayall=()=>{const r=applyCampaignCommand({...issueCampaignCommand(),kind:"repayall"});toast(r.txt||r.why);render();};
ACT.landvote=d=>{
 if(G.player!=="PUN")return;
 const result=voteOnLandRevenue(me(),d.amended==="1");
 if(!result)return;
 autosave();
 render();
 toast(result.enacted?"The land revenue bill passed.":"The bill failed. The reform movement remains active.");
};


ACT.schoolorder=d=>{
 const c=me(),province=P(d.p);
 if(c.tag!=="PUN"||c.schoolOrder||!province||!bldCan(c,province,"school").ok)return;
 c.schoolOrder={province:province.id};
 autosave();
 render();
 toast("Standing school order recorded.");
};


ACT.importpolicy=d=>{
 if(!IMPORT_POLICIES.includes(d.policy))return;
 me().importPolicy=d.policy;
 autosave();
 render();
};


ACT.commercialroute=()=>{
 const result=proposeCommercialTransit(me(),G.c[$("#route-seller")?.value],$("#route-good")?.value);
 autosave();
 render();
 toast(result);
};


ACT.renewroute=()=>{
 const route=me().commercialRoute,seller=route&&G.c[route.seller];
 if(!seller)return;
 const result=proposeCommercialTransit(me(),seller,route.good,true);
 autosave();render();toast(result);
};

;

/* === src/ui4.js === */
"use strict";
/* ================= U7 (part 2): World, nation pages, Ledger, Research, News, sheets, peace screen, war declaration ================= */
/* a modal that keeps its scroll position when it is drawn again */
function modalRe(h){const m=$("#modal"),o=m&&m.firstElementChild,sc=o?o.scrollTop:0;openModal(h);const n=m.firstElementChild;if(n)n.scrollTop=sc;}
/* ---------- the World page ---------- */
function crisisBanner(){const co=G.coal||{};let h="";
 if(G.card&&G.card.kind==="cong")h+=`<button class="al bad" data-a="cardshow">Crisis: ${esc(G.card.title)}. The powers are waiting for our answer. Tap to decide.</button>`;
 return h?`<div class="alerts">${h}</div>`:"";}
function warCard(w,c){const tag=c.tag,side=w.att.includes(tag)?1:2,ws=side===1?w.ws:-w.ws,need=WARGOALS[w.goal.k].ws,lead=w.att[0]===tag||w.def[0]===tag,foes=side===1?w.def:w.att,allies=(side===1?w.att:w.def).filter(t=>t!==tag),left=ws>=0?50:50+ws/2,wd=Math.abs(ws)/2;
 return`<div class="war"><div class="wh">${foes.slice(0,3).map(FL).join("")}<b class="t">${esc(foes.map(nameOf).join(", "))}</b></div><div class="small muted">${WARGOALS[w.goal.k].n}${w.goal.prov?": "+esc(P(w.goal.prov).n):""}${allies.length?"; with "+esc(allies.map(nameOf).join(", ")):""}; ${G.t-w.start} month${G.t-w.start===1?"":"s"} old</div>
  ${w.july?`<p class="small muted">${w.july.general?"Great War":"July Crisis war"} · War exhaustion ${Math.round(w.july.wear[tag]||0)} / 100</p>`:""}
  <div class="wscore" role="img" aria-label="War score ${Math.round(ws)}"><i class="${ws<0?"neg":""}" style="left:${left}%;width:${wd}%"></i><u style="left:50%"></u><s style="left:${clamp(50+need/2,0,100)}%"></s></div>
  <div class="small">War score <b class="${ws<0?"bad":"good"}">${Math.round(ws).toString().replace("-","−")}</b>; our goal needs <b>${need}</b>.</div>
  ${lead?`<div class="row"><button class="btn sm pri" data-a="dealopen" data-w="${w.id}">Peace terms</button><button class="btn sm" data-a="peaceask" data-w="${w.id}" data-k="white">White peace</button><button class="btn sm" data-a="peaceask" data-w="${w.id}" data-k="concede">Concede</button><button class="btn sm" data-a="why" data-k="ws" data-w="${w.id}">The score</button></div>`:`<p class="small muted">Only ${esc(nameOf(side===1?w.att[0]:w.def[0]))}, who leads our side, can make peace.</p>`}</div>`;}
function infamyBody(c){const co=G.coal||{},mine=co[c.tag],inf=c.infamy||0,others=Object.keys(co).filter(t=>t!==c.tag&&G.c[t]&&G.c[t].alive&&co[t].mem.length),lc=(G.congLog||[])[0];
 let h=gz("Our infamy",inf,COAL_AT*1.2,inf.toFixed(1)+" of "+COAL_AT,{c:inf>COAL_AT-6?"red":"",mk:COAL_AT/(COAL_AT*1.2),a:"why",d:{k:"inf"}})+(mine?`<div class="al bad" style="pointer-events:none">A coalition of ${mine.mem.length} states stands against us: ${mine.mem.map(t=>esc(nameOf(t))).join(", ")}.</div>`:"");
 if(others.length)h+=`<h3>Coalitions in the world</h3>`+others.slice(0,5).map(t=>lr({lead:FL(t),t:esc(G.c[t].n),s:"against it: "+esc(co[t].mem.slice(0,4).map(nameOf).join(", "))+(co[t].mem.length>4?" and others":""),v:Math.round(G.c[t].infamy),vs:"infamy",a:"dipnat",d:{t}})).join("");
 if(lc&&G.t-lc.t<=24){const wd={down:"one side backed down",comp:"a compromise was agreed",fight:"it ended in war"}[lc.out];h+=`<h3>Last congress</h3>`+note(dateStr(lc.t)+": "+esc(nameOf(lc.att))+" against "+esc(nameOf(lc.def))+": "+wd+".");}
 const out=[];for(const t in G.c){const o=G.c[t];if(!o.alive)continue;for(const x of o.owes||[]){if(t===c.tag)out.push(`We pay ${esc(nameOf(x.to))} a quarter of our income until ${dateStr(x.until)}.`);else if(x.to===c.tag)out.push(`${esc(nameOf(t))} pays us a quarter of its income until ${dateStr(x.until)}.`);}}
 if(out.length)h+=`<h3>Reparations</h3>`+out.map(s=>note(s)).join("");return h;}
function pgDip(){if(UI.dipT)return pgDipNation(UI.dipT);const c=me(),cbs=cbsOf(c),tag=c.tag;
 const wars=G.wars.filter(w=>w.att.includes(tag)||w.def.includes(tag)),R=G.rank.slice(0,10),busy=c.war.length&&!c.ai;
 const s1=wars.map(w=>warCard(w,c)).join("");
 const s3=cbs.length?cbs.slice(0,12).map(cb=>{const e=warEV(c,cb),inf=estInf(c,cb);return lr({lead:FL(cb.t),t:esc(nameOf(cb.t)),s:WARGOALS[cb.k].n+(cb.prov?": "+esc(P(cb.prov).n):"")+" · "+esc(cb.why),v:Math.round(e.p*100)+"%",vs:"to win · infamy +"+Math.round(inf),vc:e.p<.4?"bad":e.p>.65?"good":"",btn:["Declare","declareask",{t:cb.t,k:cb.k,p:cb.prov||"",c:cb.cul||""},"",busy,"Finish the war we are already fighting first."]});}).join("")+(cbs.length>12?note((cbs.length-12)+" more causes. Open a nation's page to see all of its causes."):""):`<p class="calm">We have no cause for war. Fabricate one: tap a neighbour's province on the map.</p>`;
 const s4=R.map((t,i)=>{const o=G.c[t],sc=o.score;return lr({lead:`<span class="rk">${i+1}</span>${FL(t)}`,t:esc(o.n),s:(isGP(t)?"Great Power · ":"")+(sc?"industry "+sc.ind+" · army "+sc.mil:""),v:Math.round(o.pres),vs:"prestige",cls:t===tag?"me":"",a:"dipnat",d:{t}});}).join("")+cta("Open the ledger of all nations","tab",{t:"ledger"},{sec:1});
 const rels=Object.keys(c.rel).filter(t=>G.c[t].alive).sort((a,b)=>(c.rel[b]||0)-(c.rel[a]||0)),near=rels.filter(t=>Math.abs(c.rel[t])>15||c.ally.includes(t)||G.c[t].sphere===tag).slice(0,16);
 const s5=near.map(t=>{const o=G.c[t],r=c.rel[t],gu=guarantors(t).filter(g=>g!==tag),tags=[c.ally.includes(t)?"ally":"",(c.guar||[]).includes(t)?"we guarantee":"",gu.length?"guaranteed by "+(gu.length>2?gu.length+" powers":gu.map(g=>G.c[g].adj).join(", ")):"",o.sphere===tag?"our sphere":o.sphere?G.c[o.sphere].adj+" sphere":""].filter(x=>x).join(" · ");
  return lr({lead:FL(t),t:esc(o.n),s:esc(tags),mid:`<span class="rel"><i class="${r<0?"neg":"pos"}" style="width:${Math.min(50,Math.abs(r)/4)}%;${r<0?"right":"left"}:50%"></i><u></u></span>`,v:Math.round(r),vc:r<0?"bad":"good",a:"dipnat",d:{t}});}).join("")+(isGP(tag)?note("Influence points: "+Math.round(c.infPts||0)+". At 60 influence and good relations a state joins our sphere."):"");
 return pageHTML("dip","dip","The world","Rivals, allies and the balance of power",[
  wars.length?["Wars","Wars",s1,{sum:wars.length+""}]:null,
  ["Infamy","Infamy and coalitions",infamyBody(c),{info:["Infamy","Taking land and annexing states raises infamy; it fades slowly. Above "+COAL_AT+" our neighbours and the Great Powers ally against us, join every war against us, and may attack to make us give our conquests back. The coalition ends when infamy falls under "+COAL_OFF+"."]}],
  ["Causes","Causes for war",s3,{info:["Causes for war","The chance is our estimate of winning, counting allies and guarantors on both sides. Infamy is what the war would add to ours. Fabricate a cause by tapping a neighbour's province on the map."]}],
  ["Powers","The powers",s4],
  ["Relations","Relations",s5,{closed:1,info:["Relations","The bar runs from −100 on the left to +100 on the right. Tap a nation for its page: what it would answer to each move, before you make it."]}]],{pre:crisisBanner()});}
/* ---------- a nation's own page ---------- */
function actRow(title,a,act,d,label){return`<div class="act"><div><b>${esc(title)}</b><div class="small ${a.ok?"good":"muted"}">${esc(a.why||"")}</div></div><button class="btn sm ${a.ok?"pri":""}" ${DA(act,d)} ${a.ok?"":"disabled"}>${esc(label||title)}</button></div>`;}
function pgDipNation(t){const c=me(),o=G.c[t];if(!o||!o.alive){UI.dipT=null;return pgDip();}const f=dipFacts(c,t),isGPo=isGP(t),cbs=cbsOf(c).filter(cb=>cb.t===t),sc=x=>x.score||{ind:0,mil:0};
 const tg=(x,cl)=>`<span class="tag ${cl||""}">${x}</span>`,tags=[isGPo?tg("Great Power"):"",f.ally?tg("allied","good"):"",f.weGuar?tg("we guarantee"):"",f.theyGuarUs?tg("guarantees us"):"",f.sphere===c.tag?tg("our sphere"):f.sphere?tg(esc(G.c[f.sphere].adj)+" sphere"):"",f.truce?tg("truce","good"):"",f.atWar?tg("at war","bad"):""].join(" ");
 const hereWar=G.wars.find(w=>(w.att.includes(c.tag)&&w.def.includes(t))||(w.def.includes(c.tag)&&w.att.includes(t)));
 const last=f.last?`${dateStr(f.last.t)}: ${f.last.res==="won"?"we won":f.last.res==="lost"?"we lost":"it ended in a draw"}`:"None on record";
 const acts=[actRow("Improve relations",improveAsk(c,t),"improve",{t},"Improve")];
 acts.push(f.ally?`<div class="act"><div><b>Alliance</b><div class="small muted">Allied. Breaking it costs 25 relations on both sides.</div></div><button class="btn sm" data-a="unallyask" data-t="${t}">Break it</button></div>`:actRow("Alliance",allyAsk(c,t),"ally",{t},"Propose"));
 if(!isGPo)acts.push(f.weGuar?`<div class="act"><div><b>Guarantee</b><div class="small muted">We guarantee them. Withdrawing costs 20 relations.</div></div><button class="btn sm" data-a="unguar" data-t="${t}">Withdraw</button></div>`:actRow("Guarantee independence",guarAsk(c,t),"guar",{t},"Guarantee"));
 if(isGP(c.tag)&&!isGPo)acts.push(actRow("Build influence",influenceAsk(c,t),"influence",{t},"Spend 10"));
 const busy=c.war.length&&!c.ai;
 const wars=cbs.map(cb=>{const e=warEV(c,cb),back=[...new Set([...guarantors(t),...(o.sphere&&o.sphere!==c.tag?[o.sphere]:[]),...o.ally])].filter(x=>x!==c.tag&&G.c[x]&&G.c[x].alive).map(nameOf),inf=estInf(c,cb),cong=crisisWorthy(c,o)&&!c.war.length;
  return lr({t:WARGOALS[cb.k].n+(cb.prov?": "+esc(P(cb.prov).n):""),s:esc(cb.why)+". Infamy +"+Math.round(inf)+(c.infamy+inf>COAL_AT?' <b class="bad">(a coalition would form)</b>':"")+(back.length?". Backing them: "+esc(back.slice(0,4).join(", ")):"")+(cong?". Three times in ten the powers meet in congress first":"")+".",v:Math.round(e.p*100)+"%",vs:"to win",vc:e.p<.4?"bad":e.p>.65?"good":"",btn:["Declare","declareask",{t,k:cb.k,p:cb.prov||"",c:cb.cul||""},"",busy,"Finish the war we are already fighting first."]});}).join("");
 const subject=c.overlord===o.tag?c:o.overlord===c.tag?o:null;
 const autonomy=subject?`<div class="row"><button class="btn" data-a="subjectterms" data-t="${esc(t)}">Negotiate subject status</button></div>`:"";
 const s0=autonomy+`<div class="kgrid">${tl("They rate us",f.relBack,f.relBack<0?"cool":"warm",{bad:f.relBack<-40})}${tl("We rate them",f.rel,f.rel<0?"cool":"warm",{bad:f.rel<-40})}</div>${gz("Their infamy",f.infamy,COAL_AT*1.2,Math.round(f.infamy)+" of "+COAL_AT,{c:f.infamy>COAL_AT-6?"red":"",mk:COAL_AT/(COAL_AT*1.2)})}<div class="pblegend"><span><i style="background:var(--red)"></i>${esc(c.n)}</span><span><i style="background:var(--line2)"></i>${esc(o.n)}</span></div>${pbRow("Army",Math.round(armyStr(c.tag)),Math.round(armyStr(t)))}${pbRow("Industry",sc(c).ind||0,sc(o).ind||0)}${pbRow("Navy",fleetOf(c.tag),fleetOf(t))}${pbRow("Prestige",Math.round(c.pres),Math.round(o.pres))}${f.coal.length?note(f.coal.length+" states stand against them in a coalition."):""}`;
 const s1=`<div class="facts">${kr("Alliance",f.ally?"allied":"none")}${kr("Their allies",f.allies.length?esc(f.allies.map(nameOf).join(", ")):"none")}${kr("Guarantees",[f.weGuar?"we guarantee them":"",f.guarBy.length?"also by "+esc(f.guarBy.map(nameOf).join(", ")):"",f.theyGuarUs?"they guarantee us":""].filter(x=>x).join("; ")||"none")}${kr("Sphere",f.sphere===c.tag?"in our sphere":f.sphere?"in the "+esc(G.c[f.sphere].adj)+" sphere":f.overlord?"vassal of "+esc(nameOf(f.overlord)):"independent")}${kr("Truce",f.truce?"until "+dateStr(f.truce):"none")}${kr("Last war with us",last)}</div>`;
 const sW=hereWar?`${warCard(hereWar,c)}`:"";
 return`<div class="row" style="margin-bottom:.2rem"><button class="btn sm" data-a="dipback">← The world</button></div><header class="headpiece natpg"><div class="bigflag">${flagOf(t)}</div><h1>${esc(o.n)}</h1><div class="sub">${esc(GOVS[o.gov].n)} · ${ppl(popOf(t))} · ${provsOf(t).length} province${provsOf(t).length>1?"s":""} · rank ${G.rank.indexOf(t)+1}</div>${HEADORN}<p class="tags">${tags}</p></header>`+
  (()=>{const secs=[["Standing","Where we stand",s0],["Ties","Treaties and ties",s1],hereWar?["War","We are at war",sW]:null,["Actions","What we can do",`<p class="small muted">The answer is shown before you commit.</p>${acts.join("")}`],["Going","Going to war",wars||'<p class="small muted">We have no cause for war against them. Fabricate one by tapping their province next to ours on the map.</p>']].filter(x=>x);
   return`<nav class="jumpbar">${secs.map((s,i)=>`<button data-a="jumpsec" data-i="${i}">${s[0]}</button>`).join("")}</nav>`+secs.map((s,i)=>fr("nation",i,s[1],s[2])).join("");})()+TAILORN;}
/* ---------- the ledger of all nations ---------- */
const LCOL2={rank:["Rank",v=>v+""],pop:["People",ppl],inc:["Income",v=>money(v)],ind:["Mills",v=>Math.round(v)+""],army:["Army",v=>v+""],navy:["Navy",v=>v+""],lit:["Literacy",v=>Math.round(v*100)+"%"]};
function pgLedger(){const lv={};for(const p of G.plist)if(p.o&&p.factories.length)lv[p.o]=(lv[p.o]||0)+sum(p.factories,f=>f.lv);const au={},nu={};for(const a of G.armies){if(a.reb)continue;const n=a.u.length;if(a.naval)nu[a.o]=(nu[a.o]||0)+n;else au[a.o]=(au[a.o]||0)+n;}
 const rows=Object.values(G.c).filter(c=>c.alive).map(c=>({t:c.tag,n:c.n,rank:G.rank.indexOf(c.tag)+1,pop:c.stat.pop||0,inc:(c.stat.gdp||0)*12,ind:lv[c.tag]||0,army:au[c.tag]||0,navy:nu[c.tag]||0,lit:c.stat.lit||0}));
 const k=UI.lk||"rank",d=UI.ld||1;rows.sort((a,b)=>(a[k]-b[k])*d||a.rank-b.rank);const mx=Math.max(1e-9,...rows.map(r=>r[k])),shown=UI.lall?rows:rows.slice(0,20),me_=rows.find(r=>r.t===G.player),pos=rows.indexOf(me_)+1,F=LCOL2[k][1];
 const chips=Object.keys(LCOL2).map(x=>`<button class="pill${k===x?" on":""}" data-a="lsort" data-k="${x}">${LCOL2[x][0]}</button>`).join("");
 const list=shown.map((r,i)=>lr({lead:`<span class="rk">${k==="rank"&&d>0?r.rank:i+1}</span>${FL(r.t)}`,t:esc(r.n),s:k==="rank"?"people "+ppl(r.pop)+" · income "+fmt(r.inc):"rank "+r.rank,bar:k==="rank"?null:r[k]/mx,bc:r.t===G.player?"red":"dim",v:k==="rank"?r.rank+"":F(r[k]),vs:k==="rank"?"":LCOL2[k][0].toLowerCase(),cls:r.t===G.player?"me":"",a:"dipnat",d:{t:r.t}})).join("");
 const s0=`<div class="kgrid">${tl("Our place",ord(pos),"by "+LCOL2[k][0].toLowerCase()+" of "+rows.length)}${tl("The leader",F(rows[0][k]),esc(rows[0].n))}</div><div class="dfil chips" role="group" aria-label="Sort by">${chips}</div><div class="row sp"><span class="small muted">${d>0?"Low to high":"High to low"}</span><button class="btn sm" data-a="lsort" data-k="${k}">Reverse</button></div>${list}${rows.length>20?`<div class="row"><button class="btn sm" data-a="lall">${UI.lall?"Show the top 20":"Show all "+rows.length+" nations"}</button></div>`:""}`;
 return pageHTML("ledger","ledger","The ledger","Every nation, side by side",[["All","All nations",s0,{info:["The ledger","Tap a chip to sort the nations by that figure; tap again to reverse. Mills are factory levels; army and navy count units. Tap a nation for its page."]}]]);}
/* ---------- research ---------- */
function techFxTxt(t){return Object.keys(t.fx).map(k=>k==="unit"?"unlocks "+UNITS[t.fx.unit].n.toLowerCase():k==="good"?"unlocks "+GOODS[t.fx.good].n.toLowerCase():k==="rail"?"railways to level "+t.fx.rail:k+" "+(t.fx[k]>0?"+":"")+(Math.abs(t.fx[k])<.01?t.fx[k]*1e4/100+"%":Math.round(t.fx[k]*100)+"%")).join(", ");}
function pgTech(){const c=me(),y=yearOf(G.t),rp=c.stat.rp||0,cur=c.res?TF[c.res]:null,cost=cur?techCost(c,cur):0,pk=pickTech(c),eta=cur&&rp>0?Math.ceil(Math.max(0,cost-c.rp)/rp):null,Q=c.resQ||[];
 const full=Q.length>=RES_QMAX;
 const qrows=Q.map((id,i)=>{const t=TF[id];return lr({lead:`<span class="ck">${i+1}</span>`,t:esc(t.n),s:esc(techFxTxt(t))+" · "+techCost(c,t)+" points",btn:["Remove","rqdel",{id},""],btn2:[["↑","rqmv",{id,dir:-1},"",i===0,"Move up"],["↓","rqmv",{id,dir:1},"",i===Q.length-1,"Move down"]]});}).join("");
 const qbox=`<p class="small muted">Queue (${Q.length} of ${RES_QMAX}): the next study starts by itself when the current one is finished.${full?" Queue full ("+RES_QMAX+").":""}</p>${qrows}`;
 const s0=`<div class="kgrid">${tl("Research points",rp.toFixed(1),"a month",{sp:""})}${tl("Banked",Math.floor(c.rp)+"","points in hand")}${tl("Known",Object.keys(c.tech).length+"",`of ${TECHS.length} studies`)}</div>${cur?`<div class="curres"><b>${esc(cur.n)}</b><span class="small muted">${esc(techFxTxt(cur))}</span>${gz("Progress",c.rp,cost,Math.floor(c.rp)+" of "+cost,{c:"green"})}${eta!=null?note(eta===0?"Done next month.":"About "+eta+" month"+(eta===1?"":"s")+" at this pace."):""}</div>`:`<p class="calm">The scholars sit idle; points are kept for the next study. Choose a study below.</p>${pk?cta("Start "+esc(tNm(TF[pk].n)),"research",{id:pk}):""}`}${qbox}`;
 const adoption=provsOf(c.tag).flatMap(p=>p.ctl===c.tag?p.factories.map((f,i)=>({p,f,i})):[])
  .filter(({p,f})=>f.own==="state"&&ECON[c.econ].build>0&&upgCan(c,p,f).ok)
  .slice(0,6);
 const adoptionRows=adoption.map(({p,f,i})=>lr({
  t:esc(GOODS[f.g].n+" in "+p.n),
  s:esc(methOf(f.g).n[f.m||0])+" · "+esc(costTxt(upgCost(f)))+" · "+pct(.2/(1+.2*(f.m||0)))+" more theoretical output",
  btn:["Review adoption","upgask",{p:p.id,i},""]
 })).join("");
 const F=Object.keys(FIELDS).map((f,i)=>{const L=TECHS.filter(t=>t.f===f),kn=L.filter(t=>c.tech[t.id]!=null).length;
  const rows=L.map(t=>{const known=c.tech[t.id]!=null,av=techAvail(c,t);return lr({lead:`<span class="ck${known?" on":""}">${known?"✓":""}</span>`,t:esc(t.n)+(pk===t.id?' <span class="tag gold">minister’s pick</span>':""),s:esc(techFxTxt(t))+" · "+t.y,v:known?"known":c.res===t.id?"under way":av?techCost(c,t):(t.y>y+4?"from "+(t.y-4):"later"),vs:av&&!known&&c.res!==t.id?"points":"",vc:known?"good":"",btn:av&&!known&&c.res!==t.id?["Study","research",{id:t.id},pk===t.id?"pri":""]:null,btn2:av&&!known&&c.res!==t.id?[Q.includes(t.id)?["Queued","rqadd",{id:t.id},"",true,"Already queued"]:full?["Queue full (5)","rqadd",{id:t.id},"",true,"Queue full"]:["Queue","rqadd",{id:t.id},""]]:null});}).join("");
  return[FIELDS[f],FIELDS[f],rows,{sum:kn+" of "+L.length,closed:i>0&&!L.some(t=>techAvail(c,t))}];});
 return pageHTML("tech","tech","Research","Studies, discoveries and the march of knowledge",[["Now","The scholars",s0,{info:["Research","Scholars master one technology at a time. Points come from literacy, education spending and the learned classes. Studies a few years ahead of their date cost more."]}],["Adoption","Factory adoption",adoptionRows||note("No state-owned works can adopt a new method at present.")]].concat(F));}
/* ---------- news: the chronicle of the world ---------- */
const NF=[["all","All",null],["us","About us",1],["war","War",["war"]],["dip","Diplomacy",["diplomacy"]],["pol","Politics",["politics"]],["eco","Economy",["economy","science"]]];
function pgNews(){const f=NF.find(x=>x[0]===(UI.nf||"all"))||NF[0],n=me().n,all=G.msgs.slice(0,80),m=(f[2]===1?all.filter(x=>x.txt.includes(n)):f[2]?all.filter(x=>f[2].includes(x.cat)):all).slice(0,50),b=(G.battles||[]).slice(0,20);
 const CC={war:"var(--red)",diplomacy:"var(--cobalt)",politics:"var(--gold)",economy:"var(--turq)",science:"var(--turq)"};
 const s0=`<div class="dfil chips" role="group" aria-label="Show">${NF.map(x=>`<button class="pill${x[0]===f[0]?" on":""}" data-a="nfil" data-f="${x[0]}">${x[1]}</button>`).join("")}</div>`+(m.length?m.map(x=>`<div class="nw" style="--cat:${CC[x.cat]||"var(--muted)"}"><span class="nd">${dateStr(x.t)}</span><span class="nt">${esc(x.txt)}</span></div>`).join(""):`<p class="calm">Nothing of this kind yet.</p>`);
 const s1=b.length?b.map(x=>lr({lead:FL(x.w),t:esc(x.n),s:esc(nameOf(x.w))+" defeats "+esc(nameOf(x.l))+(x.m>1?" after "+x.m+" months":""),v:x.la+"k / "+x.ld+"k",vs:"losses",cls:"nb"})).join(""):`<p class="calm">No battles yet.</p>`;
 return pageHTML("chron","chron","The chronicle","What has happened, month by month",[["News","News",s0,{info:["The chronicle","The last 80 reports. Letters that need you are in Dispatches."]}],["Battles","Battles",s1]]);}

/* ---------- the province sheet ---------- */
const CULC=["var(--red)","var(--gold)","var(--turq)","var(--cobalt)","#8a5aa8","var(--muted)"];
function sx(title,body,open,sum){return`<details class="sx"${open?" open":""}><summary><span>${title}</span>${sum?`<em>${sum}</em>`:""}${CHEV}</summary>${body}</details>`;}
function provHTML(p){const c=p.o&&G.c[p.o],pl=me(),mine=p.o===G.player,n=p.pops.length?counts(p):null,cul={};for(const q of p.pops)cul[q.c]=(cul[q.c]||0)+q.n;
 let mil=0,lit=0,tot=0;for(const q of p.pops){mil+=q.mil*q.n;lit+=q.lit*q.n;tot+=q.n;}
 const armies=G.armies.filter(a=>a.loc===p.id&&a.u.length),ctlOther=p.ctl&&p.ctl!==p.o;
 let h=`<div class="ph" data-pid="${p.id}">${p.o?`<span class="phf">${flagOf(p.o)}</span>`:`<span class="phf none"></span>`}<div class="phm"><h2>${esc(p.n)}</h2><div class="small muted">${c?esc(c.n)+(p.col===0?" colony":""):p.waste?"Wasteland":"Unclaimed land"}${ctlOther?", occupied by "+esc(nameOf(p.ctl)):""} · ${TERRAIN[p.t].n}${p.sea?" · coastal":""}</div></div><button class="x" data-a="close" aria-label="Close">×</button></div>`;
 const sceneMeta=!p.waste&&window.LC_ASSET_FN?.getProvinceSceneMeta?window.LC_ASSET_FN.getProvinceSceneMeta(p,c):null;
 if(sceneMeta){h+=`<div class="lc-scene-banner" style="background:${sceneMeta.fallbackGradient}"><img src="${sceneMeta.src}" alt="${esc(sceneMeta.alt)}" onerror="this.style.display='none'"><div class="lc-scene-cap">${esc(sceneMeta.caption||p.n)}</div></div>`;}
 const administrator=indiaAdministrator(p);
 if(administrator)h+=kr("Administration",esc(administrator));
 if(!p.waste){h+=`<div class="mini"><div><span>People</span><b>${ppl(p.pop)}</b></div><div class="${tot&&mil/tot>=5?"bad":""}"><span>Militancy</span><b>${tot?(mil/tot).toFixed(1):"—"}</b></div><div><span>Literacy</span><b>${tot?pct(lit/tot):"—"}</b></div><div><span>Unrest</span><b>${Math.round(p.un)}</b></div></div>
  <div class="chipset"><span>Farms <b>${p.farm?GOODS[p.farm].n:"none"}</b></span><span>Mines <b>${p.mine?GOODS[p.mine].n:"none"}</b></span><span>Railway <b>${p.rail}</b></span><span>Fort <b>${p.fort}</b></span></div>`;
  if(tot&&tot>0){const cs=Object.keys(cul).sort((a,b)=>cul[b]-cul[a]).slice(0,5);h+=sx("Peoples",`<div class="stack">${cs.map((k,i)=>`<i style="width:${cul[k]/tot*100}%;background:${CULC[i]}"></i>`).join("")}</div><div class="legp">${cs.map((k,i)=>`<span>${dot(CULC[i])}${esc(k[0].toUpperCase()+k.slice(1))}<b>${pct(cul[k]/tot)}</b></span>`).join("")}</div><p class="small muted">${PTK.filter(k=>n[k]>.5).sort((a,b)=>n[b]-n[a]).slice(0,6).map(k=>PTYPES[k].n+" "+ppl(n[k])).join(" · ")}</p>`,false,cs[0]?esc(cs[0][0].toUpperCase()+cs[0].slice(1)):"");}}
 if(p.emigrantFlow||p.immigrantFlow)h+=note("Recorded migration abroad: "+ppl(p.immigrantFlow||0)+" arrivals · "+ppl(p.emigrantFlow||0)+" departures.");
 const fl=p.factories.filter(f=>f.lv>0);
 if(fl.length||(mine&&p.ctl===p.o))h+=sx("Factories",facList(p,fl),true,fl.length+"");
 if(p.build.length)h+=sx("Under construction",p.build.map(b=>lr({t:projName(b),bar:projProgress(b),v:pct(projProgress(b))})).join(""),true,p.build.length+"");
 if(mine)h+=sx("Buildings",bldHTML(p),false);
 if(armies.length)h+=sx("Forces here",armies.map(a=>lr({lead:`<span class="ctr" style="background:${a.reb?"#222":G.c[a.o].col}">${a.u.length}</span>`,t:(a.reb?"Rebels":esc(G.c[a.o].adj))+" "+(a.naval?"fleet":"army"),s:"power "+Math.round(strength(a))})).join(""),true,armies.length+"");
 let foot="";
 if(mine&&p.ctl===p.o)foot+=`<button class="btn pri" data-a="facmenu" data-p="${p.id}">Build a factory</button><button class="btn" data-a="recmenu" data-p="${p.id}">Recruit</button>`;
 if(!p.o&&!p.waste)foot+=`<button class="btn pri" data-a="colonize" data-p="${p.id}" ${canColonize(pl,p)?"":"disabled"}>${p.colz?"Being settled by "+esc(G.c[p.colz.tag].n):"Colonize"}</button>`;if(!p.o&&!p.waste&&!p.colz&&!canColonize(pl,p))foot+=`<span class="hint">We can settle it only by land from a province of ours or from a port, and only with colonial technology.</span>`;
 if(p.o&&p.o!==G.player&&provsOf(G.player).some(m=>ADJ[m.id].includes(p.id)))foot+=`<button class="btn" data-a="fabask" data-p="${p.id}">Fabricate a claim</button>`;
 if(p.o&&p.o!==G.player)foot+=`<button class="btn" data-a="dipnat" data-t="${p.o}">${esc(c.adj||c.n)} page</button>`;
 return h+`<div class="sfoot">${foot}<button class="btn" data-a="close">Close</button></div>`;}
/* ---------- the army sheet ---------- */
function batHTML(a){if(a.naval)return"";const t=armyTag(a),r=(G.bt||[]).find(x=>x.p===a.loc&&!x.nv&&(x.a.includes(t)||x.d.includes(t))),dg=Math.floor(a.dig||0),w=Math.max(2,Math.round(10*TERRAIN[P(a.loc).t].width));
 return(r?`<div class="al bad" style="pointer-events:none">Battle in progress, ${r.m} month${r.m>1?"s":""} fought.</div>`:"")+gz("Dug in",dg,3,"level "+dg+" of 3",{c:"green"})+`<p class="small muted">The front here is ${w} brigades wide; the rest wait in reserve. A battle ends when one side cannot hold its front (four months at most). An army that stays put gains a level each month, up to 3, each making it 10% harder to hit; marching loses them.</p>`;}
function genHTML(a){if(a.naval||a.reb)return"";const c=G.c[a.o],g=a.gen,mine=a.o===G.player,L=c.leaders||[];
 let h=g?lr({t:esc(g.n),s:"General, age "+Math.floor(g.age),v:GEN_PILL(g),btn:mine&&!a.bt?["Relieve","ungen",{}]:null}):lr({t:"No general",s:"The army fights without a commander."});
 if(!mine||g||a.bt)return a.bt&&mine?h+note("Generals cannot be changed while a battle is being fought."):h;
 return h+(L.length?L.map(x=>lr({t:esc(x.n),s:"age "+Math.floor(x.age),v:GEN_PILL(x),btn:["Assign","setgen",{g:x.id}]})).join(""):note("No general is free. Leadership grows with our officers and military spending: "+Math.floor((c.lead||0)/GEN_AT*100)+"% of the way to the next one."));}
/* ---------- the peace screen ---------- */
function dealHTML(){const d=UI.deal,w=d&&G.wars.find(x=>x.id===d.w);if(!w)return`<div class="msheet" tabindex="-1"><div class="sh-h"><h2>Peace terms</h2><button class="x" data-a="close" aria-label="Close">×</button></div><p class="calm">That war is over.</p></div>`;
 const c=me(),side=w.att.includes(c.tag)?1:2,menu=dealMenu(w,side),v=dealVerdict(w,side,d.sel),foes=side===1?w.def:w.att,mine=side===1?w.att:w.def;
 const rows=menu.map(i=>{const on=d.sel.includes(i.key);return lr({cls:on?"on":"",t:esc(i.n),s:"costs "+i.cost+" war score",v:i.cost,vs:"score",btn:[on?"✓ Included":"Add","dealtog",{k:i.key},on?"pri":""]});}).join("");
 return`<div class="msheet peace" tabindex="-1"><div class="sh-h"><h2>Peace terms</h2><button class="x" data-a="close" aria-label="Close">×</button></div>
 ${PGV.peace}<div class="sides"><span>${mine.slice(0,2).map(FL).join("")}<b>${esc(nameOf(mine[0]))}</b></span><i>against</i><span>${foes.slice(0,2).map(FL).join("")}<b>${esc(nameOf(foes[0]))}</b></span></div>
 ${gz("Terms cost",v.cost,Math.max(1,v.sc),Math.round(v.cost)+" of "+Math.round(Math.max(0,v.sc))+" held",{c:v.cost>v.sc?"red":"green",mk:v.lim>0?clamp(v.lim/Math.max(1,v.sc),0,1):null})}
 <div class="verdict ${v.ok?"yes":"no"}">${esc(v.why)}</div>
 <div class="list2">${rows}</div>${note("War score is what we have won on the field. Each term costs some of it. "+esc(nameOf(foes[0]))+" accepts only what it thinks it must: the tick on the bar shows its limit.")}
 <div class="dfoot2"><button class="btn" data-a="close">Cancel</button><button class="btn pri" data-a="dealgo"${v.ok?"":" disabled"}>Propose peace</button></div></div>`;}
const showDeal=()=>modalRe(dealHTML());
/* ---------- the war declaration sheet ---------- */
function declareSheet(d){const c=me(),o=G.c[d.t];if(!o)return;const cb=cbsOf(c).find(x=>x.t===d.t&&x.k===d.k&&String(x.prov||"")===String(d.p||""))||{t:d.t,k:d.k,prov:d.p||null,why:"",cul:d.c||null},e=warEV(c,cb),inf=estInf(c,cb),back=[...new Set([...guarantors(d.t),...(o.sphere&&o.sphere!==c.tag?[o.sphere]:[]),...o.ally])].filter(x=>x!==c.tag&&G.c[x]&&G.c[x].alive),cong=crisisWorthy(c,o)&&!c.war.length,after=c.infamy+inf,sc=x=>x.score||{ind:0,mil:0};
 const busy=c.war.length&&!c.ai,truce=(c.truce[d.t]||0)>G.t;
 openModal(`<div class="msheet cf declare" tabindex="-1"><div class="sh-h"><h2>Declare war?</h2><button class="x" data-a="close" aria-label="Close">×</button></div>
 ${PGV.war}<div class="sides"><span>${FL(c.tag)}<b>${esc(c.n)}</b></span><i>against</i><span>${FL(d.t)}<b>${esc(o.n)}</b></span></div>
 <p class="goal"><b>${WARGOALS[d.k].n}${d.p?": "+esc(P(d.p).n):""}</b>${cb.why?" · "+esc(cb.why):""}</p>
 ${gz("Chance of winning",e.p,1,Math.round(e.p*100)+"%",{c:e.p<.4?"red":e.p>.6?"green":"",mk:.5})}
 <div class="pblegend"><span><i style="background:var(--red)"></i>${esc(c.n)}</span><span><i style="background:var(--line2)"></i>${esc(o.n)}</span></div>${pbRow("Army",Math.round(armyStr(c.tag)),Math.round(armyStr(d.t)))}${pbRow("Industry",sc(c).ind||0,sc(o).ind||0)}${pbRow("Navy",fleetOf(c.tag),fleetOf(d.t))}
 ${gz("Infamy after the war",after,COAL_AT*1.2,Math.round(c.infamy)+" → "+Math.round(after),{c:after>COAL_AT?"red":"",mk:COAL_AT/(COAL_AT*1.2)})}${after>COAL_AT&&c.infamy<=COAL_AT?`<div class="al bad" style="pointer-events:none">Above ${COAL_AT} our neighbours and the Great Powers will form a coalition against us.</div>`:""}
 <div class="exl">${exR("Backing "+esc(o.n),back.length?esc(back.slice(0,4).map(nameOf).join(", "))+(back.length>4?" and "+(back.length-4)+" more":""):"none")}${exR("Relations with "+esc(o.n),"fall to −80","bad")}${exR("Other nations' regard","falls by about "+Math.round(inf>0?declInf({k:d.k}):0),"bad")}${cong?exR("A congress first","3 times in 10"):""}${exR("After peace","a truce of five years")}</div>
 ${note("A war costs lives and money every month and cannot be undone. Only the war's leader can make peace.")}
 <div class="dfoot2"><button class="btn" data-a="close">Not now</button><button class="btn dng" ${DA("cf",{go:"declare",t:d.t,k:d.k,p:d.p||"",c:d.c||""})}${busy||truce?" disabled":""}>Declare war</button></div>${busy?`<p class="small bad" style="text-align:center">Finish the war we are already fighting first.</p>`:truce?`<p class="small bad" style="text-align:center">A truce holds until ${dateStr(c.truce[d.t])}.</p>`:""}</div>`);}
/* ---------- choosing a factory and units: rows with figures ---------- */
function recSheet(p){const c=me();return`<div class="ph"><div class="phm"><h2>Raise forces at ${esc(p.n)}</h2><div class="small muted">Units are paid for in goods, at once.</div></div><button class="x" data-a="close" aria-label="Close">×</button></div>${Object.keys(UNITS).filter(k=>(!UNITS[k].tech||c.tech[UNITS[k].tech])&&(UNITS[k].land||p.sea)).map(k=>lr({t:UNITS[k].n,s:"costs "+Object.keys(UNITS[k].cost).map(g=>UNITS[k].cost[g]+" "+GOODS[g].n.toLowerCase()).join(", "),btn:["Raise","recruit",{k,p:p.id},"pri"]})).join("")}<div class="sfoot"><button class="btn" data-a="close">Close</button></div>`;}
/* ---------- the actions that ask first, and the ones restyled ---------- */
Object.assign(ACT,{
 nfil:d=>{UI.nf=d.f;render();},
 dfltask:()=>{const c=me();if(c.debt<=0)return;askSheet({ti:"Default on the debt?",danger:1,lab:"Default",body:"We stop paying what we owe. The debt of "+money(c.debt)+" is wiped out, and the lenders never forget.",rows:[["Debt wiped out",money(c.debt),"good"],["Prestige","falls","bad"],["Credit market","closed for ten years","bad"],["The Great Powers","gain a reason for war","bad"]],go:["dflt",{}]});},
 unallyask:d=>{askSheet({ti:"Break the alliance?",danger:1,lab:"Break it",body:"We end our alliance with "+esc(nameOf(d.t))+". They will remember it.",rows:[["Relations with "+esc(nameOf(d.t)),"−25","bad"],["Their regard for us","−25","bad"]],go:["unally",{t:d.t}]});},
 peaceask:d=>{const w=G.wars.find(x=>x.id===d.w);if(!w)return;const c=me(),side=w.att.includes(c.tag)?1:2,s=side===1?w.ws:-w.ws,foe=nameOf((side===1?w.def:w.att)[0]);
  if(d.k==="white")askSheet({ti:"Offer white peace?",lab:"Offer peace",body:"We offer to end the war on the old borders, with nothing won or lost.",rows:[["War score now",Math.round(s).toString().replace("-","−"),s<0?"bad":"good"],["Accepted if",s>-10?"they are not winning, or the war is 24 months old":"the war is 24 months old"],["Afterwards","a truce of five years"]],go:["peace",{w:w.id,k:"white"}]});
  else askSheet({ti:"Concede the war?",danger:1,lab:"Concede",body:side===1?"We give up. "+esc(foe)+" holds, and its prestige rises.":"We give up, and "+esc(foe)+" takes what it fought for: "+WARGOALS[w.goal.k].n.toLowerCase()+(w.goal.prov?" ("+esc(P(w.goal.prov).n)+")":"")+".",rows:[["Prestige",side===1?"−5":"−5, and "+esc(foe)+" gains 5","bad"],["The war","ends at once"],["Afterwards","a truce of five years"]],go:["peace",{w:w.id,k:"concede"}]});},
 gwask:d=>{const w=GW.find(x=>x.id===d.id);if(!w)return;askSheet({ti:"Begin "+esc(w.n)+"?",lab:"Begin the work",body:esc(w.d),rows:[["Total cost",money(w.cost),"bad"],["Paid each month",money(w.cost/w.m)],["Time",w.m+" months"]].concat(w.uniq?[["Unique","whoever finishes first wins it"]]:[]),note:"The money leaves the treasury a little each month. The work cannot be cancelled.",go:["gw",{id:w.id}]});},
 decask:d=>{const x=DEC.find(y=>y.id===d.id);if(!x)return;askSheet({ti:esc(x.n),lab:"Enact",body:esc(x.d),note:"A decision is taken once and cannot be undone.",go:["dec",{id:x.id}]});},
 reformask:d=>{const r=REFORMS.find(x=>x.id===d.id),c=me(),l=c.reforms[r.id]||0,can=canReform(c,r);if(!r)return;
 const vote=r.id==="vote"?franchiseConcession(c):null;
 const bargain=vote&&!can.ok&&canReform(c,r,true).ok;
 askSheet({ti:esc(r.n),lab:bargain?"Fund transition and pass":"Pass the reform",body:esc(r.lv[l])+" becomes "+esc(r.lv[l+1])+".",rows:[["How it passes",bargain?"Moderates accept a transition grant of "+money(vote.cost):esc(can.how||can.why||"")],...(vote?[["Supporters",pct(vote.supporters)+" · extend the franchise"],["Undecided",pct(vote.undecided)+" · seek transition funds"],["Opponents",pct(vote.opponents)+" · retain restrictions"]]:[]),["Afterwards","no other reform for a year"]],note:"Reforms calm some of the people and anger others. They cannot be taken back.",off:!can.ok&&!bargain,why:esc(can.why||""),go:["reform",{id:r.id,concession:bargain?"1":"0"}]});},
 upgask:d=>{const c=me(),p=P(d.p),f=p.factories[+d.i];if(!f)return;const C=upgCost(f);askSheet({ti:"Modernize the "+GOODS[f.g].n.toLowerCase()+" works?",lab:"Modernize",body:"New methods raise output per worker in "+esc(p.n)+".",rows:[["Materials",costTxt(C),"bad"]],note:"The state buys the machinery and cement on the market as it is delivered.",go:["upg",{p:p.id,i:d.i}]});},
 fabask:d=>{const p=P(d.p);askSheet({ti:"Fabricate a claim on "+esc(p.n)+"?",lab:"Begin",body:"Our agents build a claim on the province, which becomes a cause for war.",rows:[["Time","10 months"],["Risk","a small chance of scandal: infamy +2 and relations −30"]],go:["fab",{p:p.id}]});},
 mobask:()=>{const c=me(),pl=mobPlan(c),bad=mobCan(c,pl);askSheet({ti:"Mobilize the army?",danger:1,lab:"Mobilize now",body:mobFx(c,pl),note:"The troops stay under arms until we demobilize.",off:!!bad,why:bad?esc(bad):"",go:["mobgo",{}]});},
 demask:()=>{const c=me();let n=0;for(const a of G.armies)if(a.o===c.tag&&!a.naval)for(const u of a.u)if(u.mob)n++;askSheet({ti:"Demobilize?",lab:"Demobilize",body:n+" conscript brigades are disbanded at the start of next month. The survivors go back to the farms and mines of the provinces they came from, so output recovers.",rows:[["Brigades lost in battle","do not return"],["Mobilizing again","not for three months"]],go:["demgo",{}]});},
 declareask:d=>declareSheet(d),
 declare:d=>{const c=me();if(c.war.length){toast("Finish the war we are already fighting first.");return;}const w=declareWar(c.tag,d.t,{k:d.k,tag:d.t,prov:d.p||null,cul:d.c||null,fab:false});toast(w?"War is declared.":G.card?"The Great Powers call a congress first.":"We cannot declare war on them now.");render();},
 facmenu:d=>openSheet(facSheet(P(d.p))),recmenu:d=>openSheet(recSheet(P(d.p))),
 dealopen:d=>{const w=G.wars.find(x=>x.id===d.w);if(!w)return;closeSheet();UI.deal={w:w.id,sel:w.att.includes(me().tag)?["goal"]:[]};showDeal();},
 dealtog:d=>{const s=UI.deal.sel,i=s.indexOf(d.k);if(i<0)s.push(d.k);else s.splice(i,1);showDeal();},
 dealgo:()=>{const w=G.wars.find(x=>x.id===UI.deal.w);if(!w)return;const r=peaceOffer(w,"deal",UI.deal.sel);toast(r.txt);if(r.ok){closeModal();render();}else showDeal();},
 dflt:()=>{const c=me();if(c.debt<=0)return;defaultDebt(c,true);toast("We have defaulted on our debts.");render();},
 unally:d=>{toast(unallyDo(me(),d.t).txt);render();}
});
/* old calls that went to the sheet or to confirm(): kept as thin routes */
ACT.ledger=()=>{closeModal();UI.tab="ledger";UI.dipT=null;closeSheet();render();const pg=$("#page");if(pg)pg.scrollTop=0;};
PAGES.nat=pgNat;PAGES.eco=pgEco;PAGES.pol=pgPol;PAGES.mil=pgMil;PAGES.dip=pgDip;PAGES.tech=pgTech;PAGES.chron=pgNews;PAGES.ledger=pgLedger;

ACT.subjectterms=d=>{
 const country=G.c[d.t];
 if(!country?.alive)return;
 openModal(`<div class="msheet" tabindex="-1"><div class="sh-h"><h2>Terms with ${esc(country.n)}</h2><button class="x" data-a="close" aria-label="Close">×</button></div>
 <p>Fiscal compact: the ruler pays up to 2% of income to the subject for two years.</p>
 <button class="btn" data-a="subjectoffer" data-month="${G.t}" data-serial="${issueCampaignCommand().serial}" data-t="${esc(d.t)}" data-term="compact">Offer fiscal compact</button>
 <p>Independence: the subject keeps its territory and assets. Both governments agree to a two-year truce.</p>
 <button class="btn" data-a="subjectoffer" data-month="${G.t}" data-serial="${issueCampaignCommand().serial}" data-t="${esc(d.t)}" data-term="release">Offer independence</button></div>`);
};
ACT.subjectoffer=d=>{
 const partner=G.c[d.t];
 if(!partner)return;
 const result=applyCampaignCommand({month:+d.month,serial:+d.serial,kind:"subject",target:partner.tag,term:d.term});
 closeModal();
 autosave();
 render();
 toast(result.txt||result.why);
};

;

/* === src/ui5.js === */
"use strict";
/* ================= U7 (title page), U8 (the map) and U9 (comfort) ================= */
/* ---------- options kept in the browser ---------- */
let OPT_=null;const OPT=(k,d)=>{if(!OPT_){try{OPT_=JSON.parse(localStorage.getItem("vic.opt")||"{}")||{};}catch(e){OPT_={};}}return OPT_[k]===undefined?d:OPT_[k];};
const OPTS=(k,v)=>{OPT(k);OPT_[k]=v;try{localStorage.setItem("vic.opt",JSON.stringify(OPT_));}catch(e){}};
/* ================= THE TITLE PAGE ================= */
const SITU={GBR:"The workshop of the world, with the strongest fleet afloat. Keep the empire fed and the new towns quiet.",FRA:"A liberal kingdom with a big army, a restless Paris and old quarrels with Britain.",RUS:"A vast empire with the largest army and hardly any industry: serfs, snow and distance.",AUS:"The old heart of Europe, a patchwork of peoples held together by the throne.",PRU:"A drilled and ambitious kingdom at the head of a customs union, and the likely maker of a united Germany.",USA:"A young republic with endless land and fast growth, and a quarrel over slavery that will not go away.",CHI:"The largest nation on earth: rich in people, poor in guns, and the foreign merchants are coming.",OTT:"A great empire in slow decline, pressed by Russia and by its own provinces. Reform or fall.",NED:"A rich trading kingdom with an eastern empire and a small army.",SPA:"An old empire in civil war and debt, with colonies still across the sea.",BEL:"A new, small, industrial kingdom: coal, iron, and a guarantee from the Powers.",EGY:"Muhammad Ali's strong, modernizing state, ready to quarrel with the Sultan.",SWE:"A quiet northern kingdom with a long coast, a thin purse and a wish to be left alone.",POR:"A faded seafaring kingdom with colonies in Africa and Asia and a weak home economy.",PUN:"The Sikh kingdom: a fine army, a rich land, and the British closing in.",SAR:"The Italian kingdom with the best army and a free spirit: the seed of unification.",BRA:"A vast young empire of coffee and slaves, ruled in a boy emperor's name.",JAP:"A closed island country under the shogun. Foreign ships will soon arrive.",DEN:"A small kingdom with an old empire and a quarrel with the Germans in the south.",SIC:"A large, poor southern kingdom with a harsh government, ripe for revolution.",PAP:"The Pope's own state, held up by foreign bayonets.",MEX:"A republic in turmoil, with Texas restless and the northern frontier undefended.",GRE:"A tiny new kingdom that dreams of gathering all the Greeks.",SWI:"A neutral league of cantons: no empire, but good defences and a free press.",TEX:"A frontier republic of settlers, newly independent and very small.",TRN:"Farmers on the high veld, outnumbered and free.",ETH:"A mountain empire of ancient faith, split among regional lords.",PER:"An old empire between Russia and Britain, weak at the centre.",KOR:"The hermit kingdom, closed to all but China.",DAI:"A strong southern empire with a proud army and a closed door.",SIA:"A balanced, clever kingdom between the British and the French.",TUS:"A mild, cultured grand duchy among the Italian states.",SER:"A principality on the Ottoman border, half free and half bound."};
