/* ================= V1.4 the sheet: peek, half and full ================= */
const SHK=["peek","half","full"],SH_BACK='<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path d="M15 5l-7 7 7 7" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>';
UI.shH=SHK.includes(OPT("shh","peek"))?OPT("shh","peek"):"peek";UI.shSx=UI.shSx||{};
/* the three numbers that matter for the current lens, and one main action */
function peekHTML(p){const c=p.o&&G.c[p.o],pl=me();let mil=0,lit=0,tot=0;for(const q of p.pops){mil+=q.mil*q.n;lit+=q.lit*q.n;tot+=q.n;}
 const N=(l,v,bad)=>`<span${bad?' class="bad"':""}><i>${l}</i><b>${v}</b></span>`,mi=tot?mil/tot:0,fac=p.factories.reduce((a,f)=>a+f.lv,0),ppn=N("People",ppl(p.pop)),
  mN=N("Militancy",tot?mi.toFixed(1):"—",mi>=5),lN=N("Literacy",tot?pct(lit/tot):"—"),uN=N("Unrest",Math.round(p.un),p.un>=25);
 const T={pol:[ppn,mN,lN],pop:[ppn,lN,uN],mil:[mN,uN,N("Fort",p.fort)],ind:[N("Factories",fac),N("Railway",p.rail),ppn],rail:[N("Railway",p.rail),N("Factories",fac),N("Fort",p.fort)],
  dip:c?[N("Owner rank",ord(G.rank.indexOf(p.o)+1)),N("Prestige",Math.round(c.pres)),ppn]:[N("Owner","none"),ppn,N("Terrain",TERRAIN[p.t].n)],
  ter:[N("Terrain",TERRAIN[p.t].n),N("Farms",p.farm?GOODS[p.farm].n:"none"),N("Mines",p.mine?GOODS[p.mine].n:"none")]};
 let act;if(p.o===G.player&&p.ctl===p.o)act=`<button class="btn pri sm" data-a="facmenu" data-p="${p.id}" aria-label="Build a factory here">Build</button>`;
 else if(!p.o&&!p.waste&&canColonize(pl,p))act=`<button class="btn pri sm" data-a="colonize" data-p="${p.id}">Colonize</button>`;
 else if(p.o&&p.o!==G.player&&provsOf(G.player).some(m=>ADJ[m.id].includes(p.id)))act=`<button class="btn sm" data-a="fabask" data-p="${p.id}" aria-label="Fabricate a claim">Claim</button>`;
 else act=`<button class="btn sm" data-a="shsize" data-k="half">Details</button>`;
 return`<div class="pkr"><button class="shb" data-a="shclose" aria-label="Back: close the sheet">${SH_BACK}</button><span class="phf${p.o?"":" none"}">${p.o?flagOf(p.o):""}</span><b class="pkn">${esc(p.n)}</b>${act}</div><div class="pkn3" aria-label="${esc(MODES[UI.mode])} lens">${(T[UI.mode]||T.pol).join("")}</div>`;}
function shPx(k){const s=$("#sheet"),M=$("main").clientHeight;if(k==="full")return Math.round(M*.9);if(k==="half")return Math.round(M*.5);const pk=s.querySelector(".shpeek");return Math.max(96,pk?pk.offsetHeight+10:96);}
function shSet(k,keep){const s=$("#sheet");if(!s)return;s._k=k;s.dataset.k=k;s._px=shPx(k);s.style.height=s._px+"px";if(!keep&&(s._peekable||k!=="peek")){UI.shH=k;OPTS("shh",k);}shReveal();}
function openSheet(h,o){const s=$("#sheet"),was=s.classList.contains("open"),m=/^<div class="ph" data-pid="([^"]+)"/.exec(h),pk=m&&P(m[1])?peekHTML(P(m[1])):(o&&o.peek)||null,old=was&&s.querySelector(".shbody"),st=old?old.scrollTop:0;
 s._peekable=!!pk;let k=was?s._k:UI.shH;if(k==="peek"&&!pk)k="half";
 s.innerHTML=`<div class="shbar"><button class="shb" data-a="shclose" aria-label="Back: close the sheet">${SH_BACK}</button><div class="grab" aria-hidden="true"></div><button class="shb tog" data-a="shsize" aria-label="Make the sheet taller or shorter">${CHEV}</button></div>`+(pk?`<div class="shpeek">${pk}</div>`:"")+`<div class="shbody">${h}</div>`;
 s.querySelectorAll("details.sx").forEach(d=>{const t=d.querySelector("summary span"),v=t&&UI.shSx[t.textContent];if(v!=null)d.open=v;});
 s.classList.add("open");if(!was)s.classList.add("drag");shSet(k,1);if(!was){void s.offsetHeight;s.classList.remove("drag");}
 const b=s.querySelector(".shbody");if(b&&st)b.scrollTop=st;}
function closeSheet(){const s=$("#sheet");s.classList.remove("open");UI.sel=null;UI.crane=null;if(UI.bm)UI.bm.rev=null;UI.rtp=null;UI.thsheet=null;UI.nsheet=null;closeChooser();if(UI.tab==="map"&&$("#svg"))drawMap();}
/* when a province is selected the map moves so that it sits in the part of the map the sheet leaves free */
function shReveal(){if(UI.tab!=="map"||!UI.sel||!UI.view||!P(UI.sel))return;const s=$("#sheet");if(!s.classList.contains("open"))return;const p=P(UI.sel),M=$("main").getBoundingClientRect(),r=mapRect(),top=r.top,bot=Math.min(r.bottom,M.bottom-(s._px||0));
 if(bot-top<90)return;const v=UI.view,sc=r.width/v.w,sx=r.left+(p.x-v.x)*sc,sy=top+(p.y-v.y)*sc,mg=30;
 if(sx>r.left+mg&&sx<r.right-mg&&sy>top+mg&&sy<bot-mg)return;v.x=p.x-r.width/2/sc;v.y=p.y-((top+bot)/2-r.top)/sc;applyView();}
Object.assign(ACT,{shsize:d=>{const s=$("#sheet");if(!s.classList.contains("open"))return;const k=d.k||(s._k==="full"?"half":"full");shSet(k);},shclose:()=>closeSheet()});
/* swipe on the bar or the peek: follow the finger, then snap; down from the smallest height closes */
{let g=null;const s=()=>$("#sheet");
 document.addEventListener("pointerdown",e=>{const sh=s(),z=e.target.closest&&e.target.closest("#sheet .shbar,#sheet .shpeek");if(!z||e.target.closest("button")||!sh.classList.contains("open"))return;g={y:e.clientY,id:e.pointerId,h:sh.offsetHeight,moved:false,z};});
 window.addEventListener("pointermove",e=>{if(!g||e.pointerId!==g.id)return;const sh=s(),dy=g.y-e.clientY;if(Math.abs(dy)>8)g.moved=true;if(!g.moved)return;sh.classList.add("drag");const lo=(sh._peekable?96:shPx("half"))*.6;sh.style.height=Math.max(lo,Math.min(shPx("full"),g.h+dy))+"px";});
 const end=e=>{if(!g||e.pointerId!==g.id)return;const sh=s(),dy=g.y-e.clientY,d=g;g=null;sh.classList.remove("drag");
  if(!d.moved){if(d.z.classList.contains("shpeek"))shSet("half");else ACT.shsize({});return;}
  const ks=sh._peekable?SHK:SHK.slice(1),i=ks.indexOf(sh._k);let j=i;if(dy>=40)j=Math.min(ks.length-1,i+1);else if(dy<=-40){if(i===0)return closeSheet();j=i-1;}else{const h=sh.offsetHeight;let bd=1e9;ks.forEach((k,n)=>{const q=Math.abs(shPx(k)-h);if(q<bd){bd=q;j=n;}});}
  shSet(ks[j]);};
 window.addEventListener("pointerup",end);window.addEventListener("pointercancel",e=>{if(g&&e.pointerId===g.id){g=null;const sh=s();sh.classList.remove("drag");if(sh._k)sh.style.height=sh._px+"px";}});
 document.addEventListener("toggle",e=>{const d=e.target;if(d.matches&&d.matches("#sheet details.sx")){const t=d.querySelector("summary span");if(t)UI.shSx[t.textContent]=d.open;}},true);
 window.addEventListener("resize",()=>{const sh=s();if(sh&&sh.classList.contains("open")&&sh._k){sh.classList.add("drag");sh._px=shPx(sh._k);sh.style.height=sh._px+"px";void sh.offsetHeight;sh.classList.remove("drag");}});}

;

/* === src/ui8.js === */
"use strict";
/* ================= V2: Build mode =================
   Choose a project once, tap provinces on the Atlas, review once, confirm once. No tap spends money:
   only Confirm issues orders, each through applyCampaignCommand (kinds building, queue and rail).
   Everything here reads the game and draws; the rules (bldCan, bldCost, bldPay, railCan, startRail) are the engine's own.
   Railway routes use their own breadth-first search over adjacent land provinces we hold and control. */
Object.assign(ICON,{rail:'<path d="M7 3l-3 18M17 3l3 18M5.3 9h13.4M4.5 15h15"/>'});
UI.bm={on:false,proj:null,rail:{a:null,b:null},msg:"",rev:null,batches:[],last:null,undo:null,pend:null};
/* V2c: the selection of the chosen project is a view of the one basket shared with the Works board (ui9.js) */
Object.defineProperty(UI.bm,"sel",{configurable:true,enumerable:true,get(){return UI.bm.proj&&UI.bm.proj!=="rail"?wbIds(UI.bm.proj):[];},set(v){if(UI.bm.proj&&UI.bm.proj!=="rail"){for(const id of wbIds(UI.bm.proj))if(!v.includes(id))wbDel(UI.bm.proj,id);for(const id of v)wbAdd(UI.bm.proj,id);}else if(!v.length)wbClear();}});
const BM_GROUPS=[["eco","Economy"],["mil","Military"],["civic","Civic"]];
const bmGrp=k=>k==="rail"?"eco":BLD[k].grp==="soc"||BLD[k].grp==="cul"?"civic":BLD[k].grp;
const bmNm=k=>k==="rail"?"Railway":BLD[k].n;
const bmOne=k=>k==="rail"?"Faster marches and more output from the province it runs through.":BLD[k].d.split(/\.\s/)[0].replace(/\.$/,"")+".";
const bmOn=()=>!!(UI.bm.on&&UI.bm.proj&&G&&G.player);
const bmValid=k=>k==="rail"||!!(k&&BLD[k]);
function bmSave(){OPTS("bm",{p:UI.bm.proj,on:UI.bm.on?1:0});}
/* after a load or Continue: the chosen project comes back with the campaign */
function bmRestore(){const s=OPT("bm",null),b=UI.bm;wbClear();b.rail={a:null,b:null};b.msg="";b.rev=null;b.undo=null;b.pend=null;b.last=null;
 if(s&&bmValid(s.p)&&s.on){b.proj=s.p;b.on=true;}else{b.proj=null;b.on=false;}}
const heldBy=(c,p)=>!!p&&p.o===c.tag&&p.ctl===p.o&&!p.waste;

/* ---------- who can take the project ---------- */
function bmCan(c,p,k){
 if(k==="rail"){if(!heldBy(c,p))return{ok:false,why:p.waste?"Nothing can be built here.":p.o===c.tag?"An enemy holds this province.":"Only in provinces we hold."};return{ok:true};}
 if(p.waste)return{ok:false,why:"Nothing can be built here."};
 if(p.o!==c.tag)return{ok:false,why:p.o?"Not ours: only provinces we hold can be built in.":"Nobody holds this land yet."};
 if(p.ctl!==p.o)return{ok:false,why:"An enemy holds this province."};
 if((c.bq||[]).some(x=>x.p===p.id&&x.b===k))return{ok:false,why:"Already waiting in the queue."};
 return bldCan(c,p,k);}
function bmEligible(c,k){const s=new Set();for(const p of provsOf(c.tag))if(bmCan(c,p,k).ok)s.add(p.id);return s;}

/* ---------- railway routes: our own search, over land we hold and control ---------- */
function bmRoute(c,a,b){
 const ok=id=>heldBy(c,P(id));
 if(!ok(a))return{ok:false,why:"The line must start in a province we hold.",path:[],gap:[],segs:[]};
 const prev={[a]:null},q=[a];let found=a===b;
 for(let i=0;i<q.length&&!found;i++){const x=q[i];for(const n of ADJ[x]){if(n in prev||!ok(n))continue;prev[n]=x;if(n===b){found=true;break;}q.push(n);}}
 if(found){const path=[];for(let x=b;x!==null;x=prev[x])path.push(x);path.reverse();return{ok:true,path,gap:[],segs:path.map(id=>bmSeg(c,P(id)))};}
 /* no all-land route we control: find the shortest land line at all, to show where it breaks */
 const dist={[a]:0},pv2={[a]:null},todo=[a];
 while(todo.length){let bi=0;for(let i=1;i<todo.length;i++)if(dist[todo[i]]<dist[todo[bi]])bi=i;const x=todo.splice(bi,1)[0];if(x===b)break;
  for(const n of ADJ[x]){const pn=P(n);if(pn.waste)continue;const d=dist[x]+(ok(n)?.01:1);if(!(n in dist)||d<dist[n]-1e-9){dist[n]=d;pv2[n]=x;if(!todo.includes(n))todo.push(n);}}}
 if(!(b in dist))return{ok:false,why:"These provinces are not joined by land, and railways do not cross the sea.",path:[],gap:[],segs:[]};
 const path=[];for(let x=b;x!==null;x=pv2[x])path.push(x);path.reverse();
 const gap=path.filter(id=>!ok(id)),first=P(gap[0]);
 const holder=first.o?(first.o===c.tag?"occupied by an enemy":"held by "+G.c[first.o].n):"held by nobody";
 return{ok:false,why:"No all-land route through provinces we control. The line breaks at "+first.n+" ("+holder+").",path,gap,segs:path.filter(ok).map(id=>bmSeg(c,P(id)))};}
/* one province on the line: already railed (by level), can start now, or blocked with the reason. Railways have no waiting list, so none "joins a queue". */
function bmSeg(c,p){
 if(p.rail>=1)return{p,state:"built",lv:p.rail,why:"Railway level "+p.rail};
 if(p.build.some(b=>b.k==="rail"))return{p,state:"block",lv:0,why:"Already under construction."};
 const r=railCan(c,p);
 return r.ok?{p,state:"start",lv:0,why:""}:{p,state:"block",lv:0,why:r.why};}

/* ---------- the plan for the basket: what Review shows and Confirm issues (one basket, many buildings) ---------- */
function bmPlan(){
 const c=me(),b=UI.bm,rows=[],built=[],items=UI.wb.bk.map(x=>({k:x.k,p:x.p,why:x.why||""}));let route=null;const pre=[];
 if(b.proj==="rail"&&b.rail.a&&b.rail.b){route=bmRoute(c,b.rail.a,b.rail.b);
  for(const s of route.segs){if(s.state==="built")built.push(s);
   else if(s.state==="start"){if(!items.some(x=>x.k==="rail"&&x.p===s.p.id))items.push({k:"rail",p:s.p.id,why:""});}
   else pre.push({p:s.p,k:"rail",state:"skip",why:s.why});}}
 const order=[];for(const x of items)if(!order.includes(x.k))order.push(x.k);if(pre.length&&!order.includes("rail"))order.push("rail");
 let free=Math.max(0,buildSlots(c)-bldActive(c));
 for(const k of order){
  for(const x of items){if(x.k!==k)continue;const p=P(x.p);if(!p)continue;
   if(k==="rail"){const can=heldBy(c,p)?railCan(c,p):bmCan(c,p,"rail");
    if(!can.ok){rows.push({p,k,state:"skip",why:can.why});continue;}
    rows.push({p,k,lv:p.rail,next:p.rail+1,C:Object.assign({},RAIL_COST),cost:bldMoney(RAIL_COST),months:Math.round(1/BUILD_RATE),val:null,upk:0,state:"start",pick:x.why});continue;}
   const can=bmCan(c,p,k);
   if(!can.ok){rows.push({p,k,state:"skip",why:can.why});continue;}
   const y=bldPay(c,p,k),lv=BLD[k].lv(p),st=free>0?"start":"queue";if(free>0)free--;
   rows.push({p,k,lv,next:lv+1,C:y.C,cost:y.cost,months:BLD[k].m,val:y.val,upk:BLD[k].upk||0,why:y.why,state:st,pick:x.why});}
  if(k==="rail")for(const r of pre)rows.push(r);}
 const live=rows.filter(r=>r.state!=="skip"),mats={};
 for(const r of live)for(const g in r.C)mats[g]=(mats[g]||0)+r.C[g];
 const est=sum(live,r=>r.cost),first=sum(live.filter(r=>r.state==="start"),r=>r.cost/Math.max(1,r.months)),c0=Math.max(0,c.tr),kinds=[...new Set(rows.map(r=>r.k))];
 const pl={t:G.t,k:kinds.length===1?kinds[0]:kinds.length?"mixed":b.proj,kinds,rows,built,route,mats,est,first,val:sum(live,r=>r.val||0),upk:sum(live,r=>r.upk||0),
  started:live.filter(r=>r.state==="start").length,queued:live.filter(r=>r.state==="queue").length,skipped:rows.length-live.length,
  tr:c.tr,after:c.tr-first,warn:est>0&&est>.25*c0};
 pl.sig=rows.map(r=>r.k+":"+r.p.id+":"+r.state).join("|");
 return pl;}

/* ---------- the map: highlight, dim, selection, route preview, crane badges ---------- */
const bmMk=(x,y,txt,cls)=>`<g class="mk ${cls}" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><g class="us"><circle r="10"/><text y="4">${txt}</text></g></g>`;
function bmCraneHTML(c){
 const bq=c.bq||[],qn={};for(const x of bq)qn[x.p]=(qn[x.p]||0)+1;let h="";
 for(const p of provsOf(c.tag)){const w=p.build,q=qn[p.id]||0;if(!w.length&&!q)continue;
  const pr=w.length?sum(w,projProgress)/w.length:0,n=w.length+q;
  h+=`<g class="cr${w.length?"":" qd"}" data-cr="${p.id}" transform="translate(${p.x.toFixed(1)} ${p.y.toFixed(1)})"><g class="us"><circle class="hit" cx="18" cy="-18" r="22"/><circle class="cb" cx="18" cy="-18" r="12.5"/><circle class="crt" cx="18" cy="-18" r="11" pathLength="100"/><circle class="crp" cx="18" cy="-18" r="11" pathLength="100" stroke-dasharray="${w.length?Math.max(2,Math.round(pr*100)):0} 100" transform="rotate(-90 18 -18)"/><g class="cri" transform="translate(11 -25) scale(.58)">${ICON.works}</g>${n>1?`<text class="crn" x="27" y="-6">${n}</text>`:""}</g></g>`;}
 return h;}
function bmDraw(){
 const app=$("#app"),map=$("#map");if(!app||!map||!G||!G.player||!$("#bmcr"))return;
 const c=me(),on=bmOn(),b=UI.bm,k=b.proj,top=$("#bmtop"),bot=$("#bmbot"),ov=$("#bmov"),cr=$("#bmcr");
 app.classList.toggle("bm",on);
 const bb=$("#bmbtn");if(bb)bb.classList.toggle("on",on);
 let lit=new Set(),marks="",ovh="";
 if(on){
  const sel=new Set(b.sel);
  if(k==="rail"){
   for(const p of provsOf(c.tag))if(heldBy(c,p))lit.add(p.id);
   const r=b.rail,pl=r.a&&r.b?bmPlan():null,route=pl&&pl.route;
   for(const id of lit)ovh+=`<path class="bmok" d="${WP[id].d}"/>`;
   if(route){
    const seg=new Map(route.segs.map(s=>[s.p.id,s]));
    for(const id of route.path){const s=seg.get(id);lit.add(id);
     if(!s){ovh+=`<path class="bmrg" d="${WP[id].d}"/>`;marks+=bmMk(P(id).x,P(id).y,"×","gap");}
     else{ovh+=`<path class="bmr${s.state==="built"?"b":s.state==="start"?"s":"x"}" d="${WP[id].d}"/>`;marks+=bmMk(P(id).x,P(id).y,s.state==="built"?"L"+s.lv:s.state==="start"?"+":"×",s.state);}}}
   for(const id of[r.a,r.b])if(id){lit.add(id);ovh+=`<path class="bmra" d="${WP[id].d}"/>`;}
   if(r.a&&!r.b)marks+=bmMk(P(r.a).x,P(r.a).y,"A","start");
  }else{
   lit=bmEligible(c,k);
   for(const id of lit)if(!sel.has(id))ovh+=`<path class="bmok" d="${WP[id].d}"/>`;
   for(const id of b.sel){if(!WP[id])continue;ovh+=`<path class="bmsel" d="${WP[id].d}"/>`;marks+=bmMk(P(id).x,P(id).y,"✓","sel");}}
 }
 for(const p of G.plist){const e=document.getElementById("pv-"+p.id);if(!e)continue;const d=on&&!lit.has(p.id);if(e._bd!==d){e.classList.toggle("bm-dim",d);e._bd=d;}}
 setH(ov,ovh);setH(cr,bmCraneHTML(c)+marks);
 top.hidden=bot.hidden=!on;
 if(on){const pl=bmPlan(),n=k==="rail"?(b.rail.a&&b.rail.b&&pl&&pl.route?pl.route.path.length:0):b.sel.length;
  const tot=UI.wb.bk.length,oth=tot-(k==="rail"?0:n),cnt=(k==="rail"?(b.rail.a?(b.rail.b?n+" province"+(n===1?"":"s")+" on the line":"Start chosen"):"No start yet"):n+" selected")+(oth>0?" · "+tot+" in basket":"");
  setH(top,`<div class="bmh"><button class="bmproj" data-a="bmpicker" aria-label="Project: ${esc(bmNm(k))}. Tap to choose another.">${ic(k)}<b>${esc(bmNm(k))}</b>${CHEV}</button><span class="bmn">${cnt}</span><button class="bmx" data-a="bmleave" aria-label="Leave Build mode">×</button></div><div class="bmt">Estimated total at today's prices: <b>${money(pl?pl.est:0)}</b></div><div class="bmm" role="status">${esc(b.msg||bmHint(k,n))}</div>`);
  const none=!pl||(pl.rows.length===0);const nrev=pl?pl.rows.length:0;
  setH(bot,k==="rail"?`<button class="btn" data-a="bmclear">Clear route</button><button class="btn pri" data-a="bmreview"${b.rail.a&&b.rail.b?"":" disabled"}>Review route</button>`
   :`<button class="btn" data-a="bmall" aria-label="Select all eligible in view">Select all eligible in view</button><button class="btn" data-a="bmclear"${n?"":" disabled"}>Clear</button><button class="btn pri" data-a="bmreview"${none?" disabled":""}>Review${nrev?" ("+nrev+")":""}</button>`);}
}
const bmHint=(k,n)=>k==="rail"?"Tap the start of the line, then its end. Nothing is bought until you confirm.":n?"Tap a province to add or remove it. Nothing is bought until you confirm.":"Tap the highlighted provinces to add them. The others are dimmed; tap one to see why.";

/* ---------- taps ---------- */
function bmTap(id){
 const c=me(),b=UI.bm,k=b.proj,p=P(id);if(!p)return;
 if(b.rev||$("#sheet").classList.contains("open"))closeSheet();
 if(k==="rail"){const r=b.rail;
  if(!r.a||r.b){if(heldBy(c,p)){r.a=id;r.b=null;b.msg=p.n+" is the start. Now tap the end of the line.";}else b.msg=p.n+": "+bmCan(c,p,"rail").why;}
  else if(id===r.a){r.a=null;b.msg="Start cleared.";}
  else{r.b=id;const pl=bmPlan(),rt=pl.route;
   b.msg=rt.ok?p.n+" is the end. "+rt.path.length+" provinces on the line"+(pl.skipped?"; "+pl.skipped+" blocked":"")+".":rt.why;}
  drawMap();return;}
 const i=wbIds(k).indexOf(id),can=bmCan(c,p,k);
 if(i>=0){wbDel(k,id);b.msg=p.n+" removed.";}
 else if(!can.ok)b.msg=p.n+": "+can.why;
 else{wbAdd(k,id);b.msg=p.n+" added.";}
 drawMap();}
/* long-press from the ordinary map starts the same thing (V2.2) */
function bmLong(id){if(!P(id)||!G.player)return;if(bmOn())return bmTap(id);if(UI.bm.proj&&bmValid(UI.bm.proj)){bmEnter(UI.bm.proj);return bmTap(id);}UI.bm.pend=id;bmPicker();}

/* ---------- the picker ---------- */
function bmPicker(){
 const c=me(),cur=UI.bm.proj,keys=["rail",...Object.keys(BLD)];
 const row=k=>{const n=k==="rail"?provsOf(c.tag).filter(p=>heldBy(c,p)&&railCan(c,p).ok).length:bmEligible(c,k).size;
  return`<button class="bmp${k===cur?" on":""}" data-a="bmpick" data-k="${k}" aria-pressed="${k===cur}">${ic(k)}<span class="bmpt"><b>${esc(bmNm(k))}</b><small>${esc(bmOne(k))}</small></span><i class="bmpc${n?"":" none"}">${n?n+" can build":"none yet"}</i></button>`;};
 const h=`<div class="ph"><div class="phm"><h2>Build</h2><div class="small muted">Choose a project once, then tap provinces on the map.</div></div><button class="x" data-a="shclose" aria-label="Close">×</button></div>`
  +`<div class="wb-where" role="group" aria-label="Where to build"><button class="btn sm on" aria-pressed="true" data-a="bmpicker">On the map</button><button class="btn sm" aria-pressed="false" data-a="wbopen">Works board: plan every province</button></div>`
  +BM_GROUPS.map(([g,l])=>`<h3>${l}</h3><div class="bmpl">${keys.filter(k=>bmGrp(k)===g).map(row).join("")}</div>`).join("")
  +note("Nothing is bought when you choose a project or tap a province. You will see an estimate and confirm once.");
 openSheet(h);shSet("full",1);}
function bmEnter(k){const b=UI.bm;if(b.proj!==k){b.rail={a:null,b:null};b.msg="";}b.proj=k;b.on=true;b.rev=null;bmSave();hdrX(false);
 if($("#sheet").classList.contains("open"))closeSheet();drawMap();}
function bmLeave(){const b=UI.bm;b.on=false;b.proj=null;b.rail={a:null,b:null};b.msg="";b.rev=null;b.pend=null;bmSave();if($("#sheet").classList.contains("open"))closeSheet();bmUndoHide();drawMap();}

/* ---------- review once ---------- */
const bmArrow=r=>r.k==="rail"?"Railway level "+r.lv+" → "+r.next:"Level "+r.lv+" → "+r.next;
const ST={start:["Starts now","start"],queue:["Joins the queue","queue"],skip:["Skipped","skip"]};
function bmReviewHTML(pl,note0){
 const nm=pl.k==="mixed"?"Orders":bmNm(pl.k),n=pl.started+pl.queued;
 const title=pl.k==="mixed"?n+" orders in "+pl.kinds.length+" kinds":pl.k==="rail"?"Railway route":nm+(n===1?"":"s");
 const rowH=r=>{const[l,c]=ST[r.state];
  return`<div class="bmr ${c}"><div class="bmr1"><b>${esc(r.p.n)}</b><span class="bmst ${c}">${l}</span></div>`+(r.state==="skip"?`<div class="bmr2">${esc(r.why)}</div>`
   :`<div class="bmr2">${bmArrow(r)} · about ${r.months} months</div><div class="bmr2">Estimated ${money(r.cost)} · ${r.val==null?"return not priced: faster marches, more output":"return "+money(r.val)+" a month"+(r.why?": "+esc(r.why):"")}</div>`+(r.pick?`<div class="bmr2 wb-pick">Minister: ${esc(r.pick)}</div>`:""))+`</div>`;};
 const groups=[];for(const r of pl.rows){let g=groups.find(x=>x.k===r.k);if(!g)groups.push(g={k:r.k,rows:[]});g.rows.push(r);}
 const rows=groups.map(g=>{const live=g.rows.filter(r=>r.state!=="skip");
  return`<h3 class="wb-gh">${ic(g.k)}<span>${esc(bmNm(g.k))}</span><small>${live.length} order${live.length===1?"":"s"}${g.rows.length-live.length?", "+(g.rows.length-live.length)+" skipped":""} · estimated ${money(sum(live,r=>r.cost))}</small></h3>`+g.rows.map(rowH).join("");}).join("");
 const built=pl.built.length?`<p class="small muted">Already railed, so no order: ${pl.built.map(s=>esc(s.p.n)+" (level "+s.lv+")").join(", ")}.</p>`:"";
 const left=n?"":`<p class="small bad">Nothing here can be ordered, so there is nothing to confirm.</p>`;
 const rail=pl.k==="rail",tot=`<div class="exl bmtot">${kr("Estimated total at today's prices",money(pl.est),"")}${kr("Materials",esc(costTxt(pl.mats)||"none"),"")}${rail?kr("Return a month","not priced",""):kr("Return a month","+"+money(pl.val)+(pl.upk?", less upkeep "+money(pl.upk):""),"good")}${kr("Treasury after the first month",moneyS(pl.after),pl.after<0?"bad":"")}</div>`;
 const warn=pl.warn?`<div class="bmw" role="alert">Large order: the estimate of ${money(pl.est)} is ${pl.tr>0?Math.round(100*pl.est/pl.tr)+"% of the treasury ("+money(pl.tr)+")":"more than the treasury holds"}. The whole batch is counted, not each order.</div>`:"";
 return`<div class="ph"><div class="phm"><h2>Review: ${esc(title)}</h2><div class="small muted">${pl.started} start, ${pl.queued} queue, ${pl.skipped} skipped</div></div><button class="x" data-a="bmback" aria-label="Back">×</button></div>`
  +(note0?`<p class="bmw" role="alert">${esc(note0)}</p>`:"")+tot
  +note("Estimated total at today's prices; materials are bought as they are delivered, so the final bill follows the market. Returns are estimates.")
  +rows+built+left
  +`<div class="sfoot bmfoot">${warn}<button class="btn" data-a="bmback">Back</button><button class="btn pri" data-a="bmconfirm"${n?"":" disabled"}>Confirm ${n} order${n===1?"":"s"}</button></div>`;}
function bmReview(note0){
 const pl=bmPlan();if(!pl||!pl.rows.length){UI.bm.msg=UI.bm.proj==="rail"?"Tap a start and an end first.":"Select at least one province first.";if(UI.tab==="map")drawMap();else toast(UI.bm.msg);return;}
 UI.bm.rev={t:pl.t,sig:pl.sig};openSheet(bmReviewHTML(pl,note0));shSet("half",1);}
function bmConfirm(){
 const b=UI.bm,rev=b.rev;if(!rev)return;
 const c=me(),pl=bmPlan();
 if(!pl||rev.t!==G.t||rev.sig!==pl.sig){bmReview("Things changed since you looked, so here is a fresh estimate. Nothing was ordered.");return;}
 b.rev=null;
 let started=0,queued=0;const skipped=pl.rows.filter(r=>r.state==="skip").map(r=>[r.p.n,r.why]),qids=[],orders=[];
 for(const r of pl.rows){if(r.state==="skip")continue;
  let res,kind=r.k==="rail"?"rail":r.state==="start"?"building":"queue";
  const go=kd=>applyCampaignCommand({...issueCampaignCommand(),kind:kd,province:r.p.id,building:r.k==="rail"?undefined:r.k});
  res=go(kind);
  if(!res.ok&&res.full&&kind==="building"){kind="queue";res=go(kind);}
  if(!res.ok){skipped.push([r.p.n,res.why||res.txt||"It could not be ordered."]);continue;}
  if(kind==="queue"){queued++;qids.push(c.bq.at(-1).id);}else started++;
  orders.push({p:r.p.id,k:r.k,kind,C:r.C,orderId:G.commandSerial});}
 const last={t:G.t,proj:pl.k,started,queued,skipped:skipped.length,reasons:skipped,qids,orders,est:pl.est,mats:pl.mats};
 b.last=last;b.batches.push(last);wbClear();b.rail={a:null,b:null};b.msg="";
 try{autosave();}catch(e){}
 openSheet(bmResultHTML(last));shSet("half",1);drawMap();if(UI.tab!=="map")render();
 if(qids.length)bmUndoShow(qids);}
function bmResultHTML(l){
 return`<div class="ph"><div class="phm"><h2>${esc(l.proj==="mixed"?"Orders":bmNm(l.proj))}: done</h2></div><button class="x" data-a="shclose" aria-label="Close">×</button></div>`
  +`<p class="bmres" role="status"><b>Started ${l.started}, queued ${l.queued}, skipped ${l.skipped}</b></p>`
  +(l.reasons.length?`<div class="exl">${l.reasons.map(([n,w])=>kr(esc(n),esc(w),"bad")).join("")}</div>`:"")
  +note("Estimated total at today's prices: "+money(l.est)+". Materials are bought month by month as they arrive, so the final bill follows the market. Work that has started cannot be cancelled; queued orders can be removed on the Works page or from the crane badge on the map.")
  +`<div class="sfoot">${l.qids.length?`<button class="btn" data-a="bmundo">Undo all queued (${l.qids.length})</button>`:""}<button class="btn" data-a="shclose">Keep building</button><button class="btn pri" data-a="bmworks">${UI.tab==="works"?"Back to the Works board":"Open the Works page"}</button></div>`;}
/* a six-second chance to take back what only joined the queue */
function bmUndoShow(ids){const b=UI.bm,u=$("#bmundo");if(!u)return;clearTimeout(b._ut);b.undo=ids.slice();u.innerHTML=`<span>${ids.length} order${ids.length===1?"":"s"} queued.</span><button class="btn sm" data-a="bmundo">Undo all queued</button>`;u.hidden=false;b._ut=setTimeout(bmUndoHide,6000);}
function bmUndoHide(){const b=UI.bm,u=$("#bmundo");clearTimeout(b._ut);b.undo=null;if(u){u.hidden=true;u.innerHTML="";}}
function bmUndo(){const b=UI.bm,ids=b.undo||(b.last&&b.last.qids)||[];bmUndoHide();const c=me();let n=0;
 for(const id of ids){if(!(c.bq||[]).some(x=>x.id===id))continue;ACT.bqdel({id,...issueCampaignCommand()});n++;}
 if(b.last)b.last.qids=[];const ub=document.querySelector("#sheet [data-a=bmundo]");if(ub){ub.disabled=true;ub.textContent="Queued orders removed";}
 toast(n?"Removed "+n+" queued order"+(n===1?"":"s")+". Work already started carries on.":"Nothing left in the queue to remove.");
}

/* ---------- crane badges: the queue of one province ---------- */
function bmCraneAt(cx,cy){for(const g of document.querySelectorAll("#bmcr g.cr")){const h=g.querySelector(".hit");if(!h)continue;const r=h.getBoundingClientRect();if(r.width&&Math.hypot(cx-(r.left+r.right)/2,cy-(r.top+r.bottom)/2)<=r.width/2)return g.dataset.cr;}return null;}
function bmCrane(id,keep){
 const c=me(),p=P(id);if(!p)return;UI.crane=id;if(!keep)UI.sel=null;
 const q=c.bq||[],mine=q.map((x,i)=>[x,i]).filter(([x])=>x.p===id);
 const works=p.build.map(b=>lr({lead:ic(b.k==="bld"?b.b:b.k==="rail"?"rail":"works"),t:esc(projName(b)),s:(b.paid==null?"under way":money(b.paid)+" paid")+(b.lastProgress?.delayed?" · short of funds":"")+projectShortage(c,b),bar:projProgress(b),v:pct(projProgress(b))})).join("");
 const wait=mine.map(([x,i])=>lr({lead:ic(x.b),t:esc(BLD[x.b].n),s:"waiting list, place "+(i+1)+" of "+q.length,mid:`<span class="qbtns"><button class="btn sm" ${DA("bqmv",{id:x.id,d:-1,...issueCampaignCommand()})}${i?"":" disabled"} aria-label="Move up">Up</button><button class="btn sm" ${DA("bqmv",{id:x.id,d:1,...issueCampaignCommand()})}${i<q.length-1?"":" disabled"} aria-label="Move down">Down</button><button class="btn sm dng" ${DA("bqdel",{id:x.id,...issueCampaignCommand()})}>Remove</button></span>`})).join("");
 const h=`<div class="ph"><div class="phm"><h2>Works in ${esc(p.n)}</h2><div class="small muted">${p.build.length} under way, ${mine.length} waiting</div></div><button class="x" data-a="shclose" aria-label="Close">×</button></div>`
  +(works?`<h3>Under way</h3>${works}`:"")+(wait?`<h3>Waiting list</h3>${wait}`:"")+(works||wait?"":note("Nothing is being built here now."))
  +note("Work that has started cannot be cancelled. Waiting orders can be moved or removed.")
  +`<div class="sfoot"><button class="btn" data-a="bmworks">Open the Works page</button><button class="btn" data-a="shclose">Close</button></div>`;
 openSheet(h);shSet("half",1);UI.crane=id;}
/* a queue edit changes the serial numbers in the buttons, so the open crane sheet is drawn again */
for(const k of["bqmv","bqdel"]){const f=ACT[k];ACT[k]=(d,el)=>{f(d,el);if(UI.crane&&P(UI.crane)&&$("#sheet").classList.contains("open"))bmCrane(UI.crane,true);};}

Object.assign(ACT,{
 bmopen:()=>{closeLens();hdrX(false);UI.bm.pend=null;bmPicker();},
 bmpicker:()=>bmPicker(),
 bmpick:d=>{const pend=UI.bm.pend;UI.bm.pend=null;bmEnter(d.k);if(pend&&UI.bm.proj!=="rail")bmTap(pend);},
 bmleave:()=>bmLeave(),
 bmclear:()=>{const b=UI.bm;if(b.proj==="rail")b.rail={a:null,b:null};else b.sel=[];b.msg="Cleared.";drawMap();},
 bmall:()=>{const c=me(),b=UI.bm,v=UI.view,el=bmEligible(c,b.proj);let n=0;
  for(const id of el){const p=P(id);if(p.x<v.x||p.x>v.x+v.w||p.y<v.y||p.y>v.y+v.h)continue;if(wbAdd(b.proj,id))n++;}
  b.msg=n?n+" eligible province"+(n===1?"":"s")+" in view added.":"No more eligible provinces in view. Pan or zoom out to see others.";drawMap();},
 bmreview:()=>bmReview(),
 bmback:()=>closeSheet(),
 bmconfirm:()=>bmConfirm(),
 bmundo:()=>bmUndo(),
 bmworks:()=>{closeSheet();if(UI.tab==="works")render();else ACT.tab({t:"works"});}});

;

/* === src/ui9.js === */
"use strict";
/* ================= V2c: the Works board =================
   Build by plan: every building in every province on one screen, one basket shared with the map's Build mode,
   one review and one confirm (both live in ui8.js: bmPlan, bmReviewHTML, bmConfirm). Nothing here spends money:
   ticks and bulk tools only fill the basket. The rules (bldCan, bldPay, railCan) stay the engine's own, and every
   order still goes through applyCampaignCommand. The basket lives in localStorage, never in the save, and is cleared
   on confirm, on a new game and on every load. */
UI.wb={view:OPT("wbv","bld"),cur:OPT("wbc",null),sort:OPT("wbs","pay"),can:!!OPT("wbf",0),reg:"",grp:OPT("wbg","mil"),tgt:2,cap:"",msg:"",open:{},more:!!OPT("wbm",0),cs:null,bk:[],ver:0,ev:null,evN:0,page:0,bw:0};
const WB_KEY="vic.wb";
const WB_VIEWS=[["bld","By building"],["prov","By province"],["grid","Grid"],["ord","Orders"]];
const WB_GRPS=[["mil","Military"],["eco","Economy"],["soc","People"],["cul","Culture"],["rail","Railway"]];
const WB_SORTS=[["pay","Payback"],["cost","Cost"],["lv","Level"],["name","Name"]];
const wbKeys=g=>g==="rail"?["rail"]:Object.keys(BLD).filter(k=>BLD[k].grp===g);
const wbAllKeys=()=>["rail",...Object.keys(BLD)];
const wbMax=(c,k)=>k==="rail"?railMax(c):BLD[k].max;

/* ---------- the basket ---------- */
function wbStore(){try{localStorage.setItem(WB_KEY,JSON.stringify(UI.wb.bk.map(x=>x.why?[x.k,x.p,x.why]:[x.k,x.p])));}catch(e){}}
const wbHas=(k,p)=>UI.wb.bk.some(x=>x.k===k&&x.p===p);
const wbIds=k=>UI.wb.bk.filter(x=>x.k===k).map(x=>x.p);
function wbAdd(k,p,why){if(wbHas(k,p))return false;UI.wb.bk.push({k,p,why:why||""});UI.wb.ver++;wbStore();return true;}
function wbDel(k,p){const i=UI.wb.bk.findIndex(x=>x.k===k&&x.p===p);if(i<0)return false;UI.wb.bk.splice(i,1);UI.wb.ver++;wbStore();return true;}
function wbClear(){UI.wb.bk=[];UI.wb.ver++;UI.wb.msg="";wbStore();}
function wbToggle(k,p){return wbHas(k,p)?(wbDel(k,p),false):wbAdd(k,p);}
const wbWhy=(k,p)=>{const x=UI.wb.bk.find(y=>y.k===k&&y.p===p);return x?x.why:"";};

/* ---------- the evaluation of every building in every province, cached until the month or an order changes ---------- */
function wbCell(c,p,k,qpos){
 const cell={k,pid:p.id,lv:0,max:wbMax(c,k),st:"need",txt:"",pct:0,qn:0,cost:0,C:null,val:null,net:null,yrs:null,why:""};
 if(k==="rail"){const b=p.build.find(x=>x.k==="rail");cell.lv=p.rail;cell.C=RAIL_COST;cell.cost=bldMoney(RAIL_COST);
  if(b){cell.st="building";cell.pct=projProgress(b);cell.txt="building "+pct(cell.pct);}
  else if(!heldBy(c,p)){cell.txt=bmCan(c,p,"rail").why;}
  else{const r=railCan(c,p);if(r.ok){cell.st="can";cell.txt="can build";}else if(cell.max>0&&p.rail>=cell.max){cell.st="max";cell.txt="at maximum";}else cell.txt=r.why;}
  return cell;}
 const B=BLD[k],lv=B.lv(p);cell.lv=lv;
 if(B.ok&&!B.ok(p)&&!lv){cell.st="na";cell.txt=B.okw||"Not possible here.";return cell;}
 const bj=p.build.find(x=>x.k==="bld"&&x.b===k);
 if(bj){cell.st="building";cell.pct=projProgress(bj);cell.txt="building "+pct(cell.pct);return cell;}
 if(qpos[p.id+"|"+k]){cell.st="queued";cell.qn=qpos[p.id+"|"+k];cell.txt="queued #"+cell.qn;return cell;}
 if(lv>=B.max){cell.st="max";cell.txt="at maximum";return cell;}
 const can=bmCan(c,p,k);cell.C=bldCost(p,k);cell.cost=bldMoney(cell.C);
 if(can.ok){const y=bldPay(c,p,k);cell.st="can";cell.txt="can build";cell.val=y.val;cell.net=y.net;cell.yrs=y.net>0?y.yrs:null;cell.why=y.why;}
 else cell.txt=can.why;
 return cell;}
function wbEval(){
 const c=me();let nb=0;for(const p of provsOf(c.tag))nb+=p.build.length;
 const key=G.t+"|"+(G.commandSerial||0)+"|"+c.tag+"|"+(c.bq||[]).length+"|"+nb+"|"+bldActive(c);
 const o=UI.wb.ev;if(o&&o.g===G&&o.key===key)return o;
 const ev={key,g:G,provs:[],by:{},cnt:{},n:++UI.wb.evN},qpos={};
 (c.bq||[]).forEach((x,i)=>{qpos[x.p+"|"+x.b]=i+1;});
 const keys=wbAllKeys();for(const k of keys)ev.cnt[k]=0;
 ev.provs=provsOf(c.tag).filter(p=>!p.waste).sort((a,b)=>a.n<b.n?-1:a.n>b.n?1:0);
 for(const p of ev.provs){const row=ev.by[p.id]={};for(const k of keys){const cell=row[k]=wbCell(c,p,k,qpos);if(cell.st==="can")ev.cnt[k]++;}}
 return UI.wb.ev=ev;}
function wbCurKey(){const k=UI.wb.cur;if(k&&(k==="rail"||BLD[k]))return k;const b=bldBestAll(me(),1)[0];return UI.wb.cur=b?b.k:"school";}

/* ---------- small pieces of text ---------- */
const wbPay=cell=>cell.st!=="can"?"":cell.k==="rail"?"not priced":cell.yrs==null?"no money return":cell.yrs<1?"pays back in under a year":"pays back in about "+Math.round(cell.yrs)+(Math.round(cell.yrs)===1?" yr":" yrs");
const wbPips=cell=>`<i class="pips" aria-hidden="true">${Array.from({length:Math.max(1,cell.max)},(_,i)=>`<b class="${i<cell.lv?"on":""}"></b>`).join("")}</i>`;
const wbReason=(p,k,cell)=>{const nm=bmNm(k)+" in "+p.n,pay=cell.yrs==null?"it has no money return":cell.yrs<1?"it pays for itself within a year":"it pays for itself in about "+Math.round(cell.yrs)+(Math.round(cell.yrs)===1?" year":" years");return nm+": "+pay+" ("+cell.why+"), about "+money(cell.net)+" a month after upkeep.";};
function wbParseMoney(s){s=String(s||"").toLowerCase().replace(/[£,\s]/g,"");const m=/^(\d+(?:\.\d+)?)(k|m)?$/.exec(s);return m?+m[1]*(m[2]==="k"?1e3:m[2]==="m"?1e6:1):NaN;}
function wbSpend(c){let sp=0;for(const p of provsOf(c.tag))for(const b of p.build){const C=costOf(b);for(const g in b.left||{}){if(C[g]==null)continue;sp+=Math.min(Math.max(0,b.left[g]),monthlyConstructionOrder(b,g))*G.price[g];}}return sp;}

/* ---------- status strip ---------- */
function wbStripHTML(c){
 const slots=buildSlots(c),act=bldActive(c),q=(c.bq||[]).length,free=Math.max(0,slots-act),sp=wbSpend(c);
 return`<button class="wb-strip" data-a="wbstrip" aria-label="Works status: treasury ${esc(moneyS(c.tr))}, about ${esc(money(sp))} of construction this month, ${act} of ${slots} slots used, ${q} waiting. Tap for detail.">`
  +`<span><small>Treasury</small><b>${esc(moneyS(c.tr))}</b></span><span><small>Spend, month</small><b>~${esc(money(sp))}</b></span><span><small>Slots used</small><b>${act}/${slots}</b><small>${free} free</small></span><span><small>Queue</small><b>${q}</b></span></button>`;}

/* ---------- controls ---------- */
const WB_SHORT={fort:"Fort",port:"Naval",depot:"Depot",barracks:"Barrack",arsenal:"Arsenal",dock:"Dock",coal:"Coal",irr:"Irrigat",minew:"Mines",telegraph:"Telegr.",customs:"Customs",bank:"Bank",exchange:"Exch.",power:"Power",uni:"Univ.",hosp:"Hosp.",school:"School",college:"College",silo:"Silo",water:"Water",police:"Police",court:"Court",worship:"Worship",theatre:"Opera",press:"Press",rail:"Railway"};
const wbSeg=(L,cur,a,cls)=>`<div class="wb-seg ${cls||""}" role="group">${L.map(([v,l])=>`<button class="btn sm${v===cur?" on":""}" aria-pressed="${v===cur}" data-a="${a}" data-v="${v}">${esc(l)}</button>`).join("")}</div>`;
function wbToolsHTML(c,ev,k){
 const n=ev.cnt[k]||0,mx=wbMax(c,k),slots=buildSlots(c),free=Math.max(0,slots-bldActive(c)),tg=clamp(UI.wb.tgt,1,Math.max(1,mx)),bld=UI.wb.view==="bld",more=!bld||UI.wb.more;
 const sel=bld?"":`<label class="wb-f">Building<select data-wb="cur" aria-label="Building for the bulk tools">${[["mil","Military"],["eco","Economy"],["soc","People"],["cul","Culture"],["rail","Railway"]].map(([g,l])=>`<optgroup label="${l}">${wbKeys(g).map(x=>`<option value="${x}"${x===k?" selected":""}>${esc(bmNm(x))}</option>`).join("")}</optgroup>`).join("")}</select></label>`;
 const top=bld?`<div class="wb-tr wb-tr1"><button class="btn pri" data-a="wball"${n?"":" disabled"}>Select all eligible (${n})</button><button class="btn" data-a="wbmore" aria-expanded="${!!UI.wb.more}" aria-controls="wbmore">More tools${bld&&(UI.wb.can||UI.wb.reg)?" ●":""}${CHEV}</button></div>`
  :`<div class="wb-tr"><button class="btn" data-a="wball"${n?"":" disabled"}>Select all eligible: ${esc(bmNm(k))} (${n})</button></div>`;
 const rest=more?`<div id="wbmore" class="wb-more">${bld?wbFilHTML(ev):""}
 <div class="wb-tr"><label class="wb-f">Raise to level<select data-wb="tgt" aria-label="Target level">${Array.from({length:Math.max(1,mx)},(_,i)=>`<option value="${i+1}"${i+1===tg?" selected":""}>${i+1}</option>`).join("")}</select></label><button class="btn" data-a="wbraise"${n?"":" disabled"}>Raise every ${esc(bmNm(k).toLowerCase())} to level ${tg}</button></div>
 <div class="wb-tr"><label class="wb-f">Best value within £<input data-wb="cap" type="text" inputmode="decimal" autocomplete="off" placeholder="20000 or 20k" value="${esc(UI.wb.cap)}" aria-label="Amount to spend, in pounds"></label><button class="btn" data-a="wbbest">Best value within the amount</button></div>
 <div class="wb-tr"><button class="btn" data-a="wbfill">Fill free slots (${free} free)</button></div></div>`:"";
 const msg=UI.wb.msg||(more?"These tools only tick boxes. Nothing is bought until you review and confirm.":"");
 return`<div class="wb-tools${bld?" wb-tc":""}" role="group" aria-label="Bulk tools: they only tick boxes, nothing is bought">${sel}${top}${rest}${msg?`<p class="wb-msg small muted" role="status">${esc(msg)}</p>`:""}</div>`;}

/* ---------- view 1: by building ---------- */
function wbChips(c,ev,k){
 const G5=[["mil","Military"],["eco","Economy"],["soc","People"],["cul","Culture"],["rail","Railway"]];
 return`<div class="wb-chiprow" role="group" aria-label="Buildings, swipe sideways" tabindex="-1">`+G5.map(([g,l])=>`<span class="wb-gl" aria-hidden="true">${l}</span>`+wbKeys(g).map(x=>{const n=ev.cnt[x]||0,t=wbIds(x).length;
   return`<button class="wb-chip${x===k?" on":""}" aria-pressed="${x===k}" data-a="wbcur" data-k="${x}" aria-label="${esc(bmNm(x))}, ${l}, ${n} province${n===1?"":"s"} can build${t?", "+t+" ticked":""}">${ic(x)}<span>${esc(bmNm(x))}</span><i class="wb-n${n?"":" none"}">${t?t+"/":""}${n}</i></button>`;}).join("")).join("")+`</div>`;}
function wbRowHTML(cell,p){
 const on=wbHas(cell.k,p.id),can=cell.st==="can",why=on?wbWhy(cell.k,p.id):"";
 const st=cell.st==="building"?"building "+pct(cell.pct):cell.txt;
 return`<button class="wb-row st-${cell.st}${on?" on":""}" role="checkbox" aria-checked="${on}" data-a="wbtick" data-k="${cell.k}" data-p="${p.id}"${can?"":" disabled"}><span class="wb-tk" aria-hidden="true">${on?"✓":""}</span><span class="wb-rm"><b>${esc(p.n)}</b><span class="wb-rs">${wbPips(cell)}<em>${esc(st)}</em></span>${why?`<span class="wb-why">${esc(why)}</span>`:""}</span><span class="wb-rn">${cell.st==="na"?"":esc(money(cell.cost))}<small>${esc(wbPay(cell))}</small></span></button>`;}
function wbFilHTML(ev){
 const by=UI.wb.sort,regs=new Map();for(const p of ev.provs)if(REG_OF[p.id]&&REGION[REG_OF[p.id]])regs.set(REG_OF[p.id],REGION[REG_OF[p.id]].n);
 return`<div class="wb-fil"><label class="wb-f">Sort by<select data-wb="sort" aria-label="Sort by">${WB_SORTS.map(([v,l])=>`<option value="${v}"${v===by?" selected":""}>${l}</option>`).join("")}</select></label><label class="wb-f">Region<select data-wb="reg" aria-label="Region"><option value="">All regions</option>${[...regs].sort((a,b)=>a[1]<b[1]?-1:1).map(([id,n])=>`<option value="${id}"${id===UI.wb.reg?" selected":""}>${esc(n)}</option>`).join("")}</select></label><button class="btn sm${UI.wb.can?" on":""}" aria-pressed="${UI.wb.can}" data-a="wbcan">Can build now</button></div>`;}
function wbListHTML(c,ev,k){
 let L=ev.provs.map(p=>[p,ev.by[p.id][k]]);
 if(UI.wb.reg)L=L.filter(([p])=>REG_OF[p.id]===UI.wb.reg);
 if(UI.wb.can)L=L.filter(([p,x])=>x.st==="can");
 const by=UI.wb.sort,nm=(a,b)=>a[0].n<b[0].n?-1:a[0].n>b[0].n?1:0,can=x=>x[1].st==="can"?0:x[1].st==="na"?2:1;
 L.sort((a,b)=>by==="cost"?(can(a)-can(b))||(a[1].cost-b[1].cost)||nm(a,b):by==="lv"?(a[1].lv-b[1].lv)||nm(a,b):by==="name"?nm(a,b):(can(a)-can(b))||((a[1].yrs==null?1e9:a[1].yrs)-(b[1].yrs==null?1e9:b[1].yrs))||(a[1].cost-b[1].cost)||nm(a,b));
 return (L.length?`<div class="wb-list">${L.map(([p,x])=>wbRowHTML(x,p)).join("")}</div>`:note("No province matches. Clear a filter."));}
function wbByBuilding(c,ev){const k=wbCurKey();
 return wbChips(c,ev,k)+`<p class="wb-desc"><b>${esc(bmNm(k))}.</b> ${esc(bmOne(k))}</p>`+wbToolsHTML(c,ev,k)+wbListHTML(c,ev,k);}

/* ---------- view 2: by province ---------- */
function wbTile(cell,p){
 const on=wbHas(cell.k,p.id),can=cell.st==="can";
 return`<button class="wb-tile st-${cell.st}${on?" on":""}" role="checkbox" aria-checked="${on}" data-a="wbtick" data-k="${cell.k}" data-p="${p.id}"${can?"":" disabled"}>${ic(cell.k)}<span class="wb-tn">${esc(bmNm(cell.k))}</span>${wbPips(cell)}<small>${on?"ticked":esc(cell.st==="building"?"building "+pct(cell.pct):cell.st==="can"?(cell.cost?money(cell.cost):"can build"):cell.txt)}</small></button>`;}
function wbByProvince(c,ev){
 const k=wbCurKey(),open=UI.wb.open;
 return wbToolsHTML(c,ev,k)+ev.provs.map(p=>{const row=ev.by[p.id],ks=wbAllKeys().filter(x=>row[x].st!=="na"),t=ks.filter(x=>wbHas(x,p.id)).length,n=ks.filter(x=>row[x].st==="can").length,o=open[p.id]===undefined?p.id===c.cap&&!Object.keys(open).length:open[p.id];
  return`<section class="wb-card"><button class="wb-ch" data-a="wbfold" data-p="${p.id}" aria-expanded="${!!o}"><span class="wb-cn"><b>${esc(p.n)}</b><small>${t?t+" ticked, ":""}${n} can build</small></span>${t?`<i class="wb-n">${t}</i>`:""}${CHEV}</button>${o?`<div class="wb-tiles">${ks.map(x=>wbTile(row[x],p)).join("")}</div>`:""}</section>`;}).join("");}

/* ---------- view 3: grid ---------- */
const wbCols=()=>{const w=UI.wb.bw||Math.min(window.innerWidth,560)-40;return clamp(Math.floor((w-114)/44),2,5);};
const WB_SYM={can:"+",need:"–",building:"…",queued:"#",max:"●",na:""};
function wbCellBtn(cell,p){
 const on=wbHas(cell.k,p.id),can=cell.st==="can",lab=bmNm(cell.k)+", "+p.n+": level "+cell.lv+" of "+cell.max+", "+(cell.st==="building"?"building "+pct(cell.pct):cell.txt)+(on?", ticked":"");
 return`<button class="wb-cell st-${cell.st}${on?" on":""}" role="checkbox" aria-checked="${on}" aria-label="${esc(lab)}" data-a="wbtick" data-k="${cell.k}" data-p="${p.id}"${can?"":" disabled"}><b>${cell.st==="na"?"":cell.lv}</b><i>${on?"✓":WB_SYM[cell.st]}</i></button>`;}
function wbGrid(c,ev){
 const g=UI.wb.grp,keys=wbKeys(g),cols=wbCols(),pages=[];for(let i=0;i<keys.length;i+=cols)pages.push(keys.slice(i,i+cols));
 const pg=clamp(UI.wb.page,0,pages.length-1);
 const body=pages.map(ks=>`<div class="wb-gp" style="grid-template-columns:110px repeat(${ks.length},44px)"><div class="wb-gh0">Province</div>${ks.map(k=>`<div class="wb-gh1" title="${esc(bmNm(k))}">${ic(k)}<span>${esc(WB_SHORT[k]||bmNm(k))}</span></div>`).join("")}${ev.provs.map(p=>`<div class="wb-gn">${esc(p.n)}</div>`+ks.map(k=>wbCellBtn(ev.by[p.id][k],p)).join("")).join("")}</div>`).join("");
 return wbSeg(WB_GRPS.map(([v,l])=>[v,l+" "+wbKeys(v).length]),g,"wbgrp","wb-seg5")
  +`<p class="small muted">Each cell shows the level now. + can build, – blocked, … building, # queued, ● at maximum, ✓ ticked. Swipe sideways for the next page.</p>`
  +`<div class="wb-gscroll" tabindex="0" aria-label="Grid of provinces and buildings" data-pg="${pg}">${body}</div>`
  +(pages.length>1?`<div class="wb-dots" role="group" aria-label="Grid pages">${pages.map((ks,i)=>`<button class="btn sm${i===pg?" on":""}" aria-pressed="${i===pg}" data-a="wbpage" data-i="${i}" aria-label="Page ${i+1} of ${pages.length}: ${esc(ks.map(bmNm).join(", "))}">${i+1}</button>`).join("")}</div>`:"")
  +wbToolsHTML(c,ev,wbCurKey());}

/* ---------- view 4: the orders ---------- */
function wbOrdersData(c){
 const led=G.constructionLedger||{},out={going:[],wait:[],done:[]};
 for(const p of provsOf(c.tag))for(const b of p.build){if(b.k==="upg")continue;
  const lg=b.ledgerId!=null?led[b.ledgerId]:null,pr=projProgress(b),rate=b.k==="bld"?1/(BLD[b.b].m||10):BUILD_RATE;
  out.going.push({st:"building",o:b.orderId,k:b.k==="bld"?b.b:b.k==="rail"?"rail":"works",nm:projName(b),p:p.id,pr,left:Math.max(1,Math.ceil((1-pr)/rate-1e-9)),paid:lg?lg.paid:(b.paid||0),late:!!(b.lastProgress&&b.lastProgress.delayed)});}
 out.going.sort((a,b)=>(a.o==null?1e9:a.o)-(b.o==null?1e9:b.o));
 (c.bq||[]).forEach((x,i)=>out.wait.push({st:"queued",o:x.orderId,k:x.b,nm:BLD[x.b].n,p:x.p,id:x.id,i,n:(c.bq||[]).length,paid:0}));
 for(const w of (c.completedWorks||[]).filter(w=>w.t>=G.t-12).slice().reverse()){const lg=Object.values(led).find(a=>a.orderId!=null&&a.orderId===w.orderId&&a.province===w.province&&a.owner===c.tag&&a.status==="Completed");
  out.done.push({st:"done",o:w.orderId,k:BLD[w.kind]?w.kind:w.kind==="rail"?"rail":"works",nm:BLD[w.kind]?BLD[w.kind].n:w.kind==="rail"?"Railway":w.good&&GOODS[w.good]?GOODS[w.good].n+" works":"Project",p:w.province,paid:lg?lg.paid:(w.paid||0),t:w.t});}
 return out;}
function wbOrderRow(r){
 const pn=P(r.p).n,name=`<button class="wb-pn" data-a="wbmap" data-p="${r.p}" aria-label="Show ${esc(pn)} on the map">${esc(pn)}</button>`;
 const paid=`<span class="wb-paid" data-paid="${(+r.paid).toFixed(2)}">${esc(money(r.paid))} paid</span>`;
 let s,btns="",bar="";
 if(r.st==="building"){s=`Building ${pct(r.pr)} · about ${r.left} month${r.left===1?"":"s"} left · ${paid}${r.late?" · short of funds":""}`;bar=`<span class="meter"><i style="width:${(clamp(r.pr,0,1)*100).toFixed(0)}%"></i></span>`;}
 else if(r.st==="queued"){s=`Waiting, place ${r.i+1} of ${r.n} · starts when a slot is free · ${paid}`;
  btns=`<span class="wb-ob"><button class="btn sm" ${DA("bqmv",{id:r.id,d:-1,...issueCampaignCommand()})}${r.i?"":" disabled"} aria-label="Move ${esc(r.nm)} in ${esc(pn)} up">Up</button><button class="btn sm" ${DA("bqmv",{id:r.id,d:1,...issueCampaignCommand()})}${r.i<r.n-1?"":" disabled"} aria-label="Move ${esc(r.nm)} in ${esc(pn)} down">Down</button><button class="btn sm dng" ${DA("bqdel",{id:r.id,...issueCampaignCommand()})} aria-label="Remove ${esc(r.nm)} in ${esc(pn)} from the queue">Remove</button></span>`;}
 else s=`Finished ${dateStr(r.t)} · ${paid}`;
 return`<div class="wb-or st-${r.st}" data-order="${r.o==null?"":r.o}" data-st="${r.st}" data-prov="${r.p}"><span class="wb-oi">${ic(r.k)}</span><div class="wb-om"><b>${esc(r.nm)} in ${name}</b><small>${s}</small>${bar}${btns}</div></div>`;}
function wbOrders(c){
 const o=wbOrdersData(c),sec=(t,L,e)=>`<h3 class="wb-gt">${t}<small>${L.length}</small></h3>`+(L.length?L.map(wbOrderRow).join(""):note(e));
 return sec("Under way",o.going,"Nothing is being built.")+sec("Waiting in the queue",o.wait,"Nothing is waiting.")+sec("Finished in the last 12 months",o.done,"Nothing finished in the last 12 months.")
  +note("Paid so far comes from the construction ledger. Work that has started cannot be cancelled; waiting orders can be moved or removed. Tap a province to see it on the map.");}

/* ---------- the basket bar and the whole board ---------- */
function wbBarHTML(){
 const n=UI.wb.bk.length,kinds=new Set(UI.wb.bk.map(x=>x.k)).size,pl=n?bmPlan():null;
 return`<div class="wb-bar${n?"":" empty"}" role="region" aria-label="Basket"><div class="wb-bt" role="status"><b>${n} order${n===1?"":"s"}</b> · ${kinds} kind${kinds===1?"":"s"} · estimated ${money(pl?pl.est:0)} at today's prices</div><div class="wb-bb"><button class="btn" data-a="wbclear"${n?"":" disabled"}>Clear</button><button class="btn pri" data-a="wbreview"${n?"":" disabled"}>Review${n?" ("+n+")":""}</button></div></div>`;}
function wbInner(c){
 const ev=wbEval(),v=UI.wb.view;
 return wbStripHTML(c)+wbSeg(WB_VIEWS,v,"wbview")
  +`<div class="wb-body">${v==="prov"?wbByProvince(c,ev):v==="grid"?wbGrid(c,ev):v==="ord"?wbOrders(c):wbByBuilding(c,ev)}</div>`+wbBarHTML();}
const wbHTML=c=>`<div id="wbboard" class="wb">${wbInner(c)}</div>`;
function wbRefresh(){
 const el=$("#wbboard");if(!el||UI.tab!=="works"||!G||!G.player)return;
 const f=document.activeElement,fk=f&&el.contains(f)?{a:f.dataset.a,k:f.dataset.k,p:f.dataset.p,v:f.dataset.v,i:f.dataset.i,w:f.dataset.wb}:null,gs=el.querySelector(".wb-gscroll"),sl=gs?gs.scrollLeft:0;
 el.innerHTML=wbInner(me());wbPost(sl,fk);}
/* after a draw: keep the grid page, keep the focus, and fit the grid to the real width */
function wbPost(sl,fk){
 const el=$("#wbboard");if(!el)return;
 if(el.clientWidth&&el.clientWidth!==UI.wb.bw){const was=wbCols();UI.wb.bw=el.clientWidth;if(UI.wb.view==="grid"&&wbCols()!==was){el.innerHTML=wbInner(me());}}
 const cr=el.querySelector(".wb-chiprow");
 if(cr){const on=cr.querySelector(".wb-chip.on");
  if(UI.wb.cs!=null)cr.scrollLeft=UI.wb.cs;
  if(on){const l=on.offsetLeft-cr.offsetLeft,r=l+on.offsetWidth;if(UI.wb.cs==null||l<cr.scrollLeft||r>cr.scrollLeft+cr.clientWidth)cr.scrollLeft=Math.max(0,l-(cr.clientWidth-on.offsetWidth)/2);}
  UI.wb.cs=cr.scrollLeft;
  if(!cr._b){cr._b=1;cr.addEventListener("scroll",()=>{UI.wb.cs=cr.scrollLeft;},{passive:true});}}
 const gs=el.querySelector(".wb-gscroll");
 if(gs){const pg=+gs.dataset.pg||0;gs.scrollLeft=sl!=null&&sl>0?sl:pg*gs.clientWidth;if(!gs._b){gs._b=1;gs.addEventListener("scroll",()=>{const w=gs.clientWidth||1,i=Math.round(gs.scrollLeft/w);if(i!==UI.wb.page){UI.wb.page=i;el.querySelectorAll(".wb-dots .btn").forEach((b,j)=>{b.classList.toggle("on",j===i);b.setAttribute("aria-pressed",String(j===i));});}},{passive:true});}}
 if(fk){const sel=[fk.a?`[data-a="${fk.a}"]`:"",fk.k?`[data-k="${fk.k}"]`:"",fk.p?`[data-p="${fk.p}"]`:"",fk.v?`[data-v="${fk.v}"]`:"",fk.i?`[data-i="${fk.i}"]`:"",fk.w?`[data-wb="${fk.w}"]`:""].join("");if(sel){const n=el.querySelector(sel);if(n&&!n.disabled&&n!==document.activeElement)try{n.focus({preventScroll:true});}catch(e){}}}}
const _wbRender=render;
render=function(){_wbRender();if(UI.tab==="works")wbPost();};
/* the map's Build bar and the board show the same basket */
function wbSync(){wbRefresh();if(UI.tab==="map"&&bmOn())drawMap();}

/* ---------- the tools: they only tick ---------- */
function wbPickList(c,ev,free){
 const L=[];for(const p of ev.provs)for(const k of Object.keys(BLD)){const x=ev.by[p.id][k];if(x.st==="can"&&x.net!=null&&x.net>0&&!wbHas(k,p.id))L.push({p,k,x});}
 L.sort((a,b)=>(a.x.yrs-b.x.yrs)||(a.x.cost-b.x.cost)||(a.p.n<b.p.n?-1:1));return L;}
function wbBulk(kind){
 const c=me(),ev=wbEval(),b=UI.wb;let msg="";
 const have=()=>bmPlan(),slots=buildSlots(c),free=Math.max(0,slots-bldActive(c));
 if(kind==="all"||kind==="raise"){
  const k=wbCurKey(),tg=clamp(b.tgt,1,Math.max(1,wbMax(c,k)));let n=0,skip=0;
  for(const p of ev.provs){const x=ev.by[p.id][k];if(x.st!=="can"){continue;}if(kind==="raise"&&x.lv>=tg){skip++;continue;}if(wbAdd(k,p.id))n++;}
  msg=kind==="all"?(n?"Ticked "+n+" "+bmNm(k).toLowerCase()+" order"+(n===1?"":"s")+" in every province that can build one.":"Every eligible province is already ticked."):
   (n?"Ticked "+n+" province"+(n===1?"":"s")+" below level "+tg+". Each order adds one level, so a province at level 0 needs a second order once the first is done.":"No province below level "+tg+" can take "+bmNm(k).toLowerCase()+" now.");}
 else if(kind==="best"||kind==="fill"){
  const L=wbPickList(c,ev),pl=have(),inBasket=pl.rows.filter(r=>r.state!=="skip"&&r.k!=="rail").length;let est=pl.est,n=0,cost=0;
  if(kind==="best"){const X=wbParseMoney(b.cap);
   if(!(X>0)){b.msg="Type an amount first, for example 20000 or 20k.";return wbSync();}
   const room=free+10-inBasket;
   for(const r of L){if(n>=room)break;if(est+r.x.cost>X+1e-6)continue;if(wbAdd(r.k,r.p.id,wbReason(r.p,r.k,r.x))){est+=r.x.cost;cost+=r.x.cost;n++;}}
   msg=n?"Ticked the "+n+" best-value project"+(n===1?"":"s")+" by payback, adding "+money(cost)+"; the basket is now estimated at "+money(est)+", within "+money(X)+".":"Nothing more fits within "+money(X)+" (the basket is estimated at "+money(est)+").";}
  else{let room=free-inBasket;
   for(const r of L){if(room<=0)break;if(wbAdd(r.k,r.p.id,wbReason(r.p,r.k,r.x))){room--;n++;cost+=r.x.cost;}}
   msg=n?"Ticked "+n+" project"+(n===1?"":"s")+" for the free slots, best payback first, adding "+money(cost)+".":free-inBasket<=0?"No free slots are left once the basket's projects start.":"No project with a money return can use a free slot.";}}
 b.msg=msg;wbSync();}

Object.assign(ACT,{
 wbopen:()=>{closeSheet();closeLens();hdrX(false);if(UI.tab==="works")render();else ACT.tab({t:"works"});},
 wbview:d=>{UI.wb.view=d.v;OPTS("wbv",d.v);wbRefresh();},
 wbmore:()=>{UI.wb.more=!UI.wb.more;OPTS("wbm",UI.wb.more?1:0);wbRefresh();},
 wbcur:d=>{UI.wb.cur=d.k;OPTS("wbc",d.k);UI.wb.msg="";wbRefresh();},
 wbsort:d=>{UI.wb.sort=d.v;OPTS("wbs",d.v);wbRefresh();},
 wbcan:()=>{UI.wb.can=!UI.wb.can;OPTS("wbf",UI.wb.can?1:0);wbRefresh();},
 wbgrp:d=>{UI.wb.grp=d.v;UI.wb.page=0;OPTS("wbg",d.v);wbRefresh();},
 wbpage:d=>{const gs=$("#wbboard .wb-gscroll");UI.wb.page=+d.i;if(gs)gs.scrollTo({left:+d.i*gs.clientWidth,behavior:"smooth"});},
 wbfold:d=>{const o=UI.wb.open,c=me(),cur=o[d.p]===undefined?(d.p===c.cap&&!Object.keys(o).length):o[d.p];o[d.p]=!cur;wbRefresh();},
 wbtick:d=>{wbToggle(d.k,d.p);UI.wb.msg="";wbSync();},
 wball:()=>wbBulk("all"),wbraise:()=>wbBulk("raise"),wbbest:()=>wbBulk("best"),wbfill:()=>wbBulk("fill"),
 wbclear:()=>{wbClear();wbSync();},
 wbreview:()=>bmReview(),
 wbstrip:()=>{const c=me(),slots=buildSlots(c),act=bldActive(c),q=(c.bq||[]).length,sp=wbSpend(c);
  openModal(`<div class="msheet" tabindex="-1"><div class="sh-h"><h2>Works status</h2><button class="x" data-a="close" aria-label="Close">×</button></div><div class="exl">${kr("Treasury",esc(moneyS(c.tr)),c.tr<0?"bad":"")}${kr("Construction this month, about",esc(money(sp)))}${kr("Building slots",act+" of "+slots+" used, "+Math.max(0,slots-act)+" free")}${kr("Waiting in the queue",String(q))}</div>${note("The spend is an estimate: the state buys materials as they are delivered at the market price, so the real bill follows the market. When every slot is busy, new orders wait in the queue and start in turn.")}<div class="dfoot2"><button class="btn pri" data-a="close">Close</button></div></div>`);},
 wbmap:d=>{ACT.tab({t:"map"});const p=P(d.p);if(!p)return;centerOn(p,260,.3);pickProv(d.p);}});
document.addEventListener("change",e=>{const f=e.target&&e.target.dataset&&e.target.dataset.wb;if(!f||UI.tab!=="works")return;const v=e.target.value,b=UI.wb;
 if(f==="cap"){b.cap=v;return;}
 if(f==="tgt"){b.tgt=+v;wbRefresh();return;}
 if(f==="sort"){b.sort=v;OPTS("wbs",v);}else if(f==="reg")b.reg=v;else if(f==="cur"){b.cur=v;OPTS("wbc",v);b.msg="";}
 wbRefresh();});
document.addEventListener("input",e=>{if(e.target&&e.target.dataset&&e.target.dataset.wb==="cap")UI.wb.cap=e.target.value;});

/* the Works entry on the bar: one tap from every tab */
{const _pick=ACT.pick;ACT.pick=(d,el)=>{_pick(d,el);wbClear();};}
if(typeof window!=="undefined"){
 Object.defineProperty(window,"G",{get:()=>G,set:v=>{G=v;},configurable:true});
 Object.defineProperty(window,"UI",{get:()=>UI,configurable:true});
 Object.assign(window,{
  WORLD,ADJ,SEAADJ,SEAR_OF,REG_OF,REGION,ACT,P,me,friendly,bmOn,
  provPts,provColor,seenSet,labelLayout,provLabelItems,bbOf,edgeDist,
  navSheet,pickProv,returnCampaignView,dateStr,advanceCampaign
 });
}
if(typeof _startLC==="function"){
 if(typeof document!=="undefined"&&document.readyState==="complete")_startLC();
 else if(typeof window!=="undefined")window.addEventListener("load",_startLC);
}
